ter: {\\n          type: \'shadow\',\\n        },\\n        axisTick: {\\n          show: false,\\n        },\\n        axisLine: {\\n          show: false,\\n        },\\n      },\\n    ],\\n    yAxis: [\\n      {\\n        type: \'value\',\\n        minInterval: 5,\\n      },\\n    ],\\n    series: [\\n      {\\n        name: \'耗时1周内\',\\n        type: \'bar\',\\n        stack: \'stack\',\\n        data: array1,\\n        barMaxWidth: 12,\\n      },\\n      {\\n        name: \'耗时1-2周\',\\n        type: \'bar\',\\n        stack: \'stack\',\\n        data: array2,\\n        barMaxWidth: 12,\\n      },\\n      {\\n        name: \'耗时2-4周\',\\n        type: \'bar\',\\n        stack: \'stack\',\\n        data: array3,\\n        barMaxWidth: 12,\\n      },\\n      {\\n        name: \'耗时4周以上\',\\n        type: \'bar\',\\n        stack: \'stack\',\\n        data: array4,\\n        barMaxWidth: 12,\\n      },\\n    ],\\n  }\\n  echartsInstance.setOption(option)\"},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"rawQuery\":true,\"rawSql\":\"select $__timeGroupAlias(i.create_time,1d),\\ncase when UNIX_TIMESTAMP(cast(i.close_time as datetime)) - UNIX_TIMESTAMP(cast(i.real_start_time as datetime)) \\u003c= 604800 then \'耗时1周内\'\\nwhen UNIX_TIMESTAMP(cast(i.close_time as datetime)) - UNIX_TIMESTAMP(cast(i.real_start_time as datetime)) \\u003c= 1209600 then \'耗时1-2周\'\\nwhen UNIX_TIMESTAMP(cast(i.close_time as datetime)) - UNIX_TIMESTAMP(cast(i.real_start_time as datetime)) \\u003c= 2419200 then \'耗时2-4周\'\\nelse \'耗时4周以上\' end as metric,count(1)\\n\\n\\n\\n from issues i left join issues_status s on i.status_id=s.id  where  i.issues_type_id=\'98\' and i.del_flag=0 and i.real_start_time is not null and i.close_time is not null and i.del_flag=0 and s.type in(2,3)\\n and $__timeFilter(i.create_time) and find_in_set(\'$userId\',assigned_ids)\\n   and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\n group by date_format(i.create_time, \'%Y%m%d\'),metric\\n\\n\\n\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"缺陷修复吞吐量\",\"type\":\"bilibala-echarts-panel\"},{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"If5u9w-Vz\"},\"gridPos\":{\"h\":8,\"w\":24,\"x\":0,\"y\":22},\"id\":18,\"options\":{\"followTheme\":false,\"getOption\":\"if(data.series.length ==0||data.series[0].length==0||(data.series[0].fields[0].values.buffer.length==1\\u0026\\u0026data.series[0].fields[0].values.buffer[0]==null)) {\\n  const option = {\\n    graphic: {\\n      elements: [\\n        {\\n          type: \'text\',\\n          left: \'center\',\\n          top: \'center\',\\n          style: {\\n            text: \'No data\',\\n            fontSize: 18,\\n//             fontWeight: 400,\\n            fill: \'#5E6164\',\\n            fontFamily:\'Inter, Helvetica, Arial, sans-serif\',\\n          }\\n        }\\n      ]\\n    }\\n  };\\n  echartsInstance.setOption(option)\\n  return \\n}\\n  const buffer = data.series[0].fields[0].values.buffer[0]\\n  const obj = JSON.parse(buffer)\\n  if (!obj) {\\n    return\\n  }\\n  const itemArr = obj.items\\n  const timeArray = itemArr.map((item) =\\u003e item?.date)\\n  const lineCountArray = itemArr.map((item) =\\u003e item?.lineCount) //代码行数\\n  const countArray = itemArr.map((item) =\\u003e item?.count) //代码提交次数\\n  const option = {\\n    color: [\'#396CDF\', \'#E05933\'],\\n    grid: {\\n      left: 40,\\n      right: 40,\\n      bottom: 40,\\n    },\\n    tooltip: {\\n      trigger: \'axis\',\\n    },\\n    legend: {\\n      data: [\'代码行数\', \'代码提交次数\'],\\n      icon: \'rect\',\\n      itemHeight: 8,\\n      itemWidth: 12,\\n      right: 0,\\n    },\\n    xAxis: [\\n      {\\n        type: \'category\',\\n        data: timeArray,\\n        axisPointer: {\\n          type: \'shadow\',\\n        },\\n        axisTick: {\\n          show: false,\\n        },\\n        axisLine: {\\n          show: false,\\n        },\\n      },\\n    ],\\n    yAxis: [\\n      {\\n        type: \'value\',\\n        name: \'代码行数(/行)\',\\n        minInterval: 100,\\n      },\\n      {\\n        type: \'value\',\\n        name: \'提交次数(/次)\',\\n        minInterval: 5,\\n      },\\n    ],\\n    series: [\\n      {\\n        name: \'代码行数\',\\n        type: \'line\',\\n        symbol: \'none\',\\n        data: lineCountArray,\\n        tooltip: {\\n          valueFormatter: function (value) {\\n            return value + \' 行\'\\n          },\\n        },\\n      },\\n      {\\n        name: \'代码提交次数\',\\n        type: \'line\',\\n        symbol: \'none\',\\n        yAxisIndex: 1,\\n        tooltip: {\\n          valueFormatter: function (value) {\\n            return value + \' 次\'\\n          },\\n        },\\n        data: countArray,\\n      },\\n    ],\\n  }\\n  echartsInstance.setOption(option)\"},\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"If5u9w-Vz\"},\"fields\":[{\"jsonPath\":\"$.data\"}],\"headers\":[[\"X-SCM-TOKEN\",\"SCM@2023\"],[\"Amp-Organ-Id\",\"$amp_organ_id\"]],\"method\":\"GET\",\"queryParams\":\"\",\"refId\":\"A\",\"urlPath\":\"/dashboard/getCommitWorkLoads?username=$userLoginName\\u0026from=$__from\\u0026to=$__to\"}],\"title\":\"代码提交情况\",\"type\":\"bilibala-echarts-panel\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"auto\",\"cellOptions\":{\"type\":\"auto\"},\"inspect\":false},\"mappings\":[],\"noValue\":\"暂无数据\",\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":30},\"id\":7,\"options\":{\"cellHeight\":\"sm\",\"footer\":{\"countRows\":false,\"fi