', \\nsubstring(\\\"$userIdAndName\\\", locate(\',\', \\\"$userIdAndName\\\",locate(i.create_by,\\\"$userIdAndName\\\"))+1,locate(\\\"\'\\\",\\\"$userIdAndName\\\",locate(\\\",\\\", \\\"$userIdAndName\\\",locate(i.create_by,\\\"$userIdAndName\\\"))+1) - locate(\',\', \\\"$userIdAndName\\\",locate(i.create_by,\\\"$userIdAndName\\\"))-1)  as \'提出人\',\\ni.end_date as \'计划完成日期\'\\nfrom issues i left join issues_status s on i.status_id=s.id\\n where  issues_type_id=\'98\' and s.type in (\'0\',\'1\')\\n and find_in_set(\'$userId\',i.assigned_ids)\\n and i.del_flag=0\\n and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\n order by s.type,i.create_time desc\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"未开始和进行中的缺陷列表\",\"type\":\"table\"}],\"schemaVersion\":39,\"tags\":[],\"templating\":{\"list\":[{\"current\":{\"selected\":true,\"text\":\"超级管理员\",\"value\":\"超级管理员\"},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select name from sys_user \\nwhere \\nis_deleted=0\\nand if(\'$amp_organ_id\'=\'null\', 1=1,id in(select user_id from sys_user_organization  where organ_id =\'$amp_organ_id\' and resource_id=0)) \\n\\n\\n\",\"hide\":0,\"includeAll\":false,\"label\":\"成员名称\",\"multi\":false,\"name\":\"username\",\"options\":[],\"query\":\"select name from sys_user \\nwhere \\nis_deleted=0\\nand if(\'$amp_organ_id\'=\'null\', 1=1,id in(select user_id from sys_user_organization  where organ_id =\'$amp_organ_id\' and resource_id=0)) \\n\\n\\n\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"},{\"current\":{\"selected\":false,\"text\":\"null\",\"value\":\"null\"},\"hide\":2,\"label\":\"amp_organ_id\",\"name\":\"amp_organ_id\",\"options\":[{\"selected\":false,\"text\":\"null\",\"value\":\"null\"}],\"query\":\"null\",\"skipUrlSync\":false,\"type\":\"textbox\"},{\"curren