Names)) and is_deleted=0\\nand  if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope=1))\\nunion\\nselect -9999999\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"}]},\"time\":{\"from\":\"now-1M\",\"to\":\"now\"},\"timeRangeUpdatedDuringEditOrView\":false,\"timepicker\":{},\"timezone\":\"\",\"title\":\"流水线维度\",\"uid\":\"sSo1HuISz\",\"version\":71,\"weekStart\":\"\"}', 1, '2023-11-21 16:34:52', '2025-01-14 14:57:26', 40, 1, 0, '', 45, 0, 0, 'sSo1HuISz', 0, NULL, 'wYE1pDwIz');
