INSERT INTO `dashboard` VALUES (46, 123, 'e9a1b9-e79bae-e8bfad-e4bba3-e4bbaa-e8a1a8-e79b98', '项目迭代仪表盘', '{\"annotations\":{\"list\":[{\"builtIn\":1,\"datasource\":{\"type\":\"grafana\",\"uid\":\"-- Grafana --\"},\"enable\":true,\"hide\":true,\"iconColor\":\"rgba(0, 211, 255, 1)\",\"name\":\"Annotations \\u0026 Alerts\",\"type\":\"dashboard\"}]},\"editable\":true,\"fiscalYearStartMonth\":0,\"graphTooltip\":0,\"id\":42,\"links\":[],\"panels\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"fixedColor\":\"#2050d1\",\"mode\":\"fixed\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[]},\"gridPos\":{\"h\":4,\"w\":6,\"x\":0,\"y\":0},\"id\":8,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"auto\",\"orientation\":\"auto\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"\",\"values\":false},\"showPercentChange\":false,\"textMode\":\"auto\",\"wideLayout\":true},\"pluginVersion\":\"11.1.0\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"SELECT \\n    (SELECT count(1)\\n     FROM issues i \\n     INNER JOIN issues_type_ext_pm_demand ispr ON i.id = ispr.issues_id\\n     WHERE ispr.sprint = $sprint_id\\n     AND i.del_flag = 0 \\n     AND tenant_id = IF(\'$amp_organ_id\' = \'null\', tenant_id, \'$amp_organ_id\')\\n    )\\n    +\\n    (SELECT count(1)\\n     FROM issues i \\n     INNER JOIN issues_type_ext_pm_task ispr ON i.id = ispr.issues_id\\n     WHERE ispr.sprint = $sprint_id\\n     AND i.del_flag = 0 \\n     AND tenant_id = IF(\'$amp_organ_id\' = \'null\', tenant_id, \'$amp_organ_id\')\\n    )\\n    +\\n    (SELECT count(1)\\n     FROM issues i \\n     INNER JOIN issues_type_ext_pm_bug ispr ON i.id = ispr.issues_id\\n     WHERE ispr.sprint = $sprint_id\\n     AND i.del_flag = 0 \\n     AND tenant_id = IF(\'$amp_organ_id\' = \'null\', tenant_id, \'$amp_organ_id\')\\n    ) \\n    AS total_count;\\n\",\"refId\":\"任务\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"工作项总数\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"fixedColor\":\"#88d9b2\",\"mode\":\"fixed\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[]},\"gridPos\":{\"h\":4,\"w\":6,\"x\":6,\"y\":0},\"id\":9,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"auto\",\"orientation\":\"auto\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"\",\"values\":false},\"showPercentChange\":false,\"textMode\":\"auto\",\"wideLayout\":true},\"pluginVersion\":\"11.1.0\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select  count(1) as count\\nfrom issues i INNER JOIN issues_type_ext_pm_demand ispr\\nON i.id = ispr.issues_id\\nwhere \\nispr.sprint =  $sprint_id\\nAND\\ni.del_flag=0 and tenant_id = if(\'$amp_organ_id\'=\'null\', tenant_id,\'$amp_organ_id\')\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"研发需求数量\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"fixedColor\":\"#6e94f3\",\"mode\":\"fixed\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[]},\"gridPos\":{\"h\":4,\"w\":6,\"x\":12,\"y\":0},\"id\":11,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"auto\",\"orientation\":\"auto\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"\",\"values\":false},\"showPercentChange\":false,\"textMode\":\"auto\",\"wideLayout\":true},\"pluginVersion\":\"11.1.0\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select  count(1) as count\\nfrom issues i INNER JOIN issues_type_ext_pm_task ispr\\nON i.id = ispr.issues_id\\nwhere\\nispr.sprint =  $sprint_id\\nAND\\ni.del_flag=0 and tenant_id = if(\'$amp_organ_id\'=\'null\', tenant_id,\'$amp_organ_id\')\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"任务数量\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"fixedColor\":\"#707e9a\",\"mode\":\"fixed\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[]},\"gridPos\":{\"h\":4,\"w\":6,\"x\":18,\"y\":0},\"id\":10,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"auto\",\"orientation\":\"auto\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"\",\"values\":false},\"showPercentChange\":false,\"textMode\":\"auto\",\"wideLayout\":true},\"pluginVersion\":\"11.1.0\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select  count(1) as count\\nfrom issues i INNER JOIN issues_type_ext_pm_bug ispr\\nON i.id = ispr.issues_id\\nwhere \\nispr.sprint =  $sprint_id\\nAND\\ni.del_flag=0 and tenant_id = if(\'$amp_organ_id\'=\'null\', tenant_id,\'$amp_organ_id\')\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"缺陷数量\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"CfuKN5mIk\"},\"description\":\"按照迭代排期时的工作项数量进行燃尽，如下图左侧所示，存量曲线高高飘起，说明进度已经严重滞后\",\"gridPos\":{\"h\":10,\"w\":24,\"x\":0,\"y\":4},\"id\":2,\"options\":{\"followTheme\":false,\"getOption\":\"console.log(data)\\nif (data.series.length == 0 || data.series[0].fields.length == 0) {\\n    const option = {\\n        graphic: {\\n            elements: [\\n                {\\n                    type: \'text\',\\n                    left: \'center\',\\n                    top: \'center\',\\n                    style: {\\n                        text: \'暂无数据\',\\n                        fontSize: 18,\\n                        //             fontWeight: 400,\\n                        fill: \'#5E6164\',\\n                        fontFamily: \'Inter, Helvetica, Arial, sans-serif\',\\n                    }\\n                }\\n            ]\\n        }\\n    };\\n    echartsInstance.setOption(option)\\n    return\\n}\\nfunction formatDate(date) {\\n    var year = date.getFullYear();\\n    var month = (date.getMonth() + 1).toString();\\n    var day = (date.getDate()).toString();\\n    if (month.length == 1) {\\n        month = \\\"0\\\" + month;\\n    }\\n    if (day.length == 1) {\\n        day = \\\"0\\\" + day;\\n    }\\n    var dateTime = year + \\\"-\\\" + month + \\\"-\\\" + day;\\n    return dateTime;\\n}\\nconst timestampArr = data.series[0].fields[0].values;\\nconst plan = data.series[0].fields[1].values;\\nconst real = data.series[1].fields[1].values;\\n\\n\\n\\nconst dateTimeArr = [];\\nconst today = new Date().setHours(0, 0, 0, 0);\\nlet todayF = timestampArr.length;\\nfor (let i = 0; i \\u003c timestampArr.length; i++) {\\n    if (todayF == timestampArr.length \\u0026\\u0026 today \\u003c timestampArr[i]) {\\n        todayF = i;\\n    }\\n    dateTimeArr.push(formatDate(new Date(timestampArr[i])))\\n}\\n\\nconst newReal = [];\\nif (todayF \\u003e 0) {\\n//     for (let i = todayF; i \\u003c plan.length; i++) {\\n//         plan[i] = plan[todayF-1];\\n//     }\\n    for (let i = 0; i \\u003c todayF; i++) {\\n        newReal[i] = real[i];\\n    }\\n}\\n\\nconst option = {\\n    color: [\'#6593eb\', \'#4472d2\'],\\n    grid: {\\n        left: \'10%\'\\n    },\\n    tooltip: {\\n        trigger: \'axis\',\\n        // formatter: (params) =\\u003e {\\n        //     let res = `${params[0].name} \\u003cbr/\\u003e`;\\n        //     for (const item of params) {\\n        //         res += `\\u003cspan style=\\\"background: ${item.color}; height:10px; width: 10px; border-radius: 50%;display: inline-block;margin-right:10px;margin-top: 5px\\\"\\u003e\\u003c/span\\u003e ${item.seriesName} ：${Math.abs(item.value)}\\u003cbr/\\u003e`;\\n        //     }\\n        //     return res;\\n        // },\\n        formatter: (params) =\\u003e {\\n            let res = `${params[0].name} \\u003cbr/\\u003e`\\n            for (const item of params) {\\n                // 根据 lineStyle.type 来判断是实线还是虚线\\n                const lineType = item.seriesName === \'存量\' ? \'solid\' : \'dashed\';\\n                \\n                // 设置不同的线条样式\\n                const lineSymbol = lineType === \'solid\' ? \'━\' : \'╌\';\\n                \\n                res += `\\u003cspan style=\\\"font-size: 14px; color: ${item.color}; margin-right: 5px;\\\"\\u003e${lineSymbol}\\u003c/span\\u003e${item.seriesName} ：${item.value}\\u003cbr/\\u003e`\\n            }\\n            return res\\n        }\\n    },\\n\\n    legend: {\\n        data: [\'基线\', \'存量\'],\\n        icon: \'rect\',\\n        itemHeight: 8,\\n        itemWidth: 8,\\n        right: 0,\\n    },\\n    xAxis: [\\n        {\\n            type: \'category\',\\n            data: dateTimeArr,\\n            axisLine: { show: false },\\n            axisTick: { show: false },\\n            axisLabel: { show: true },\\n        }\\n    ],\\n    yAxis: [\\n        {\\n            min: 0,\\n            type: \'value\',\\n            minInterval: 5,\\n            axisLabel: { formatter: (value) =\\u003e Math.abs(value) },\\n            splitLine: { lineStyle: { type: \'solid\', color: \'#ccc\' } },\\n        }\\n    ],\\n    series: [\\n        {\\n            name: \'基线\',\\n            type: \'line\',\\n            data: plan,\\n            smooth: true,\\n            lineStyle: { \\n                color: \'#6593eb\',\\n                width: 2,\\n                type: \'dashed\'\\n            },\\n            symbol: \'none\',\\n        },\\n        {\\n            name: \'存量\',\\n            type: \'line\',\\n            data: newReal,\\n            barWidth: 20,\\n            areaStyle: { color: \'#b8c9ee\', opacity: 0.5 },\\n            // z: -1,\\n            itemStyle: { normal: { barBorderRadius: [5, 5, 0, 0] } },\\n        }\\n    ],\\n};\\n\\nechartsInstance.setOption(option);\\n\"},\"targets\":[{\"cacheDurationSeconds\":0,\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"CfuKN5mIk\"},\"fields\":[{\"jsonPath\":\"$.data[*].date\",\"language\":\"jsonpath\",\"name\":\" \",\"type\":\"time\"},{\"jsonPath\":\"$.data[*].count\",\"language\":\"jsonpath\",\"name\":\" \",\"type\":\"number\"}],\"headers\":[[\"Amp-Organ-Id\",\"$amp_organ_id\"]],\"method\":\"GET\",\"params\":[[\"issueTypes\",\"${issueType:csv}\"],[\"metricType\",\"2\"],[\"sprintId\",\"$sprint_id\"]],\"queryParams\":\"\",\"refId\":\"基线\",\"urlPath\":\"/track/issues/analyse/issuesTimeSeriesMetric-overview\"},{\"cacheDurationSeconds\":0,\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"CfuKN5mIk\"},\"fields\":[{\"jsonPath\":\"$.data[*].date\",\"name\":\" \",\"type\":\"time\"},{\"jsonPath\":\"$.data[*].count\",\"language\":\"jsonpath\",\"name\":\" \",\"type\":\"number\"}],\"headers\":[[\"Amp-Organ-Id\",\"$amp_organ_id\"]],\"hide\":false,\"method\":\"GET\",\"params\":[[\"issueTypes\",\"${issueType:csv}\"],[\"metricType\",\"1\"],[\"sprintId\",\"$sprint_id\"]],\"queryParams\":\"\",\"refId\":\"存量\",\"urlPath\":\"/track/issues/analyse/issuesTimeSeriesMetric-overview\"}],\"title\":\"工作项燃尽图\",\"type\":\"bilibala-echarts-panel\"},{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"CfuKN5mIk\"},\"description\":\"横坐标为日期，纵坐标为工作项数量，横坐标上方蓝色柱子代表这一天新增的工作项数量；横坐标下方绿色柱子代表这一天完成的工作项数量；橙色曲线代表工作项存量。\",\"gridPos\":{\"h\":10,\"w\":24,\"x\":0,\"y\":14},\"id\":5,\"options\":{\"followTheme\":false,\"getOption\":\"console.log(data)\\nif (data.series.length == 0 || data.series[0].fields.length == 0) {\\n    const option = {\\n        graphic: {\\n            elements: [\\n                {\\n                    type: \'text\',\\n                    left: \'center\',\\n                    top: \'center\',\\n                    style: {\\n                        text: \'暂无数据\',\\n                        fontSize: 18,\\n                        //             fontWeight: 400,\\n                        fill: \'#5E6164\',\\n                        fontFamily: \'Inter, Helvetica, Arial, sans-serif\',\\n                    }\\n                }\\n            ]\\n        }\\n    };\\n    echartsInstance.setOption(option)\\n    return\\n}\\nfunction formatDate(date) {\\n    var year = date.getFullYear();\\n    var month = (date.getMonth() + 1).toString();\\n    var day = (date.getDate()).toString();\\n    if (month.length == 1) {\\n        month = \\\"0\\\" + month;\\n    }\\n    if (day.length == 1) {\\n        day = \\\"0\\\" + day;\\n    }\\n    var dateTime = year + \\\"-\\\" + month + \\\"-\\\" + day;\\n    return dateTime;\\n}\\nconst timestampArr = data.series[0].fields[0].values;\\nconst total = data.series[0].fields[1].values;\\nconst add = data.series[1].fields[1].values;\\nconst over = data.series[2].fields[1].values;\\n// 计算 \\\"新增\\\" 和 \\\"完成\\\" 的总数\\nconst addTotal = add.reduce((sum, val) =\\u003e sum + val, 0);\\nconst overTotal = over.reduce((sum, val) =\\u003e sum + val, 0);\\n\\nconst dateTimeArr = [];\\nconst today = new Date().setHours(0, 0, 0, 0);\\nfor (let i = 0; i \\u003c timestampArr.length; i++) {\\n    if (timestampArr[i] \\u003c= today) {\\n        dateTimeArr.push(formatDate(new Date(timestampArr[i])))\\n    }\\n}\\n\\n\\n\\nconst option = {\\n    color: [\'#FADF60\', \'#5fa7ea\', \'#6BC07A\'],\\n    grid: [\\n        {  top: \'10%\', height: \'40%\' },  // 上半部分网格\\n        {  bottom: \'10%\', height: \'40%\' }, // 下半部分网格\\n    ],\\n    tooltip: {\\n        trigger: \'axis\',\\n        formatter: (params) =\\u003e {\\n            let res = `${params[0].name} \\u003cbr/\\u003e`;\\n            for (const item of params) {\\n                res += `\\u003cspan style=\\\"background: ${item.color}; height:10px; width: 10px; border-radius: 50%;display: inline-block;margin-right:10px;margin-top: 5px\\\"\\u003e\\u003c/span\\u003e ${item.seriesName} ：${Math.abs(item.value)}\\u003cbr/\\u003e`;\\n            }\\n            return res;\\n        },\\n    },\\n    legend: {\\n        data: [\'存量\', \'新增\', \'完成\'],\\n        icon: \'circle\',\\n        itemHeight: 8,\\n        itemWidth: 8,\\n        right: 0,\\n    },\\n    xAxis: [\\n        {\\n            type: \'category\',\\n            gridIndex: 0,\\n            data: dateTimeArr,\\n            axisLine: { show: false },\\n            axisTick: { show: false },\\n            axisLabel: { show: false },\\n        },\\n        {\\n            type: \'category\',\\n            gridIndex: 1,\\n            position: \'bottom\',\\n            data: dateTimeArr,\\n            axisPointer: { type: \'shadow\' },\\n            axisTick: { show: false },\\n            axisLine: { show: false },\\n        },\\n    ],\\n    yAxis: [\\n        {\\n            gridIndex: 0,\\n            min: 0,\\n            type: \'value\',\\n            minInterval: 5,\\n            axisLabel: { formatter: (value) =\\u003e Math.abs(value) },\\n            splitLine: { lineStyle: { type: \'solid\', color: \'#ccc\' } },\\n        },\\n        {\\n            inverse: true,\\n            gridIndex: 1,\\n            min: 0,\\n            type: \'value\',\\n            minInterval: 5,\\n            axisLabel: { formatter: (value) =\\u003e Math.abs(value) },\\n        }\\n    ],\\n    series: [\\n        {\\n            name: \'存量\',\\n            xAxisIndex: 0,\\n            yAxisIndex: 0,\\n            type: \'line\',\\n            data: total.slice(0,dateTimeArr.length),\\n            smooth: true,\\n            lineStyle: { color: \'#FADF60\', width: 3 },\\n            areaStyle: { color: \'rgba(250, 223, 96, 0.2)\', opacity: 0.5 },\\n            z: -1,\\n            symbol: \'none\',\\n        },\\n        {\\n            name: \'新增\',\\n            type: \'bar\',\\n            xAxisIndex: 0,\\n            yAxisIndex: 0,\\n            data: add,\\n            barWidth: 20,\\n            itemStyle: { normal: { barBorderRadius: [5, 5, 0, 0] } },\\n        },\\n        {\\n            name: \'完成\',\\n            type: \'bar\',\\n            xAxisIndex: 1,\\n            yAxisIndex: 1,\\n            data: over,\\n            barWidth: 20,\\n            itemStyle: { normal: { barBorderRadius: [0, 0, 5, 5] } },\\n        }\\n    ],\\n    graphic: [\\n        {\\n            type: \'text\',\\n            gridIndex: 0,\\n            left: \'7%\', // 确保在最左边\\n            top: \'1%\',\\n            style: {\\n                text: `新增总数: ${addTotal}`,\\n                fontSize: 13,\\n                fill: \'#333\',\\n                fontFamily: \'Inter, Helvetica, Arial, sans-serif\',\\n            },\\n        },\\n        {\\n            type: \'text\',\\n            gridIndex: 0,\\n            left: \'22%\', // 确保在最左边\\n            top: \'1%\',\\n            style: {\\n                text: `完成总数: ${overTotal}`,\\n                fontSize: 13,\\n                fill: \'#333\',\\n                fontFamily: \'Inter, Helvetica, Arial, sans-serif\',\\n            },\\n        },\\n    ],\\n};\\n\\nechartsInstance.setOption(option);\\n\"},\"targets\":[{\"cacheDurationSeconds\":0,\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"CfuKN5mIk\"},\"fields\":[{\"jsonPath\":\"$.data[*].date\",\"language\":\"jsonpath\",\"name\":\" \",\"type\":\"time\"},{\"jsonPath\":\"$.data[*].count\",\"language\":\"jsonpath\",\"name\":\" \",\"type\":\"number\"}],\"headers\":[[\"Amp-Organ-Id\",\"$amp_organ_id\"]],\"method\":\"GET\",\"params\":[[\"issueTypes\",\"${issueType:csv}\"],[\"metricType\",\"1\"],[\"sprintId\",\"$sprint_id\"]],\"queryParams\":\"\",\"refId\":\"total\",\"urlPath\":\"/track/issues/analyse/issuesTimeSeriesMetric-overview\"},{\"cacheDurationSeconds\":0,\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"CfuKN5mIk\"},\"fields\":[{\"jsonPath\":\"$.data[*].date\",\"name\":\" \",\"type\":\"time\"},{\"jsonPath\":\"$.data[*].count\",\"language\":\"jsonpath\",\"name\":\" \",\"type\":\"number\"}],\"headers\":[[\"Amp-Organ-Id\",\"$amp_organ_id\"]],\"hide\":false,\"method\":\"GET\",\"params\":[[\"issueTypes\",\"${issueType:csv}\"],[\"metricType\",\"3\"],[\"sprintId\",\"$sprint_id\"]],\"queryParams\":\"\",\"refId\":\"add\",\"urlPath\":\"/track/issues/analyse/issuesTimeSeriesMetric-overview\"},{\"cacheDurationSeconds\":0,\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"CfuKN5mIk\"},\"fields\":[{\"jsonPath\":\"$.data[*].date\",\"name\":\" \",\"type\":\"time\"},{\"jsonPath\":\"$.data[*].count\",\"language\":\"jsonpath\",\"name\":\" \",\"type\":\"number\"}],\"headers\":[[\"Amp-Organ-Id\",\"$amp_organ_id\"]],\"hide\":false,\"method\":\"GET\",\"params\":[[\"issueTypes\",\"${issueType:csv}\"],[\"metricType\",\"4\"],[\"sprintId\",\"$sprint_id\"]],\"queryParams\":\"\",\"refId\":\"over\",\"urlPath\":\"/track/issues/analyse/issuesTimeSeriesMetric-overview\"}],\"title\":\"工作项趋势图\",\"type\":\"bilibala-echarts-panel\"},{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"CfuKN5mIk\"},\"description\":\"横坐标为时间，纵坐标是工作项的数量（个），“完成曲线”该项目（团队）已完成的工作项数量变化，“全部曲线”该项目（团队）总共需要完成的工作项数量变化\",\"gridPos\":{\"h\":8,\"w\":24,\"x\":0,\"y\":24},\"id\":4,\"options\":{\"followTheme\":false,\"getOption\":\"console.log(data)\\nif (data.series.length == 0 || data.series[0].fields.length == 0) {\\n    const option = {\\n        graphic: {\\n            elements: [\\n                {\\n                    type: \'text\',\\n                    left: \'center\',\\n                    top: \'center\',\\n                    style: {\\n                        text: \'暂无数据\',\\n                        fontSize: 18,\\n                        //             fontWeight: 400,\\n                        fill: \'#5E6164\',\\n                        fontFamily: \'Inter, Helvetica, Arial, sans-serif\',\\n                    }\\n                }\\n            ]\\n        }\\n    };\\n    echartsInstance.setOption(option)\\n    return\\n}\\nfunction formatDate(date) {\\n    var year = date.getFullYear();\\n    var month = (date.getMonth() + 1).toString();\\n    var day = (date.getDate()).toString();\\n    if (month.length == 1) {\\n        month = \\\"0\\\" + month;\\n    }\\n    if (day.length == 1) {\\n        day = \\\"0\\\" + day;\\n    }\\n    var dateTime = year + \\\"-\\\" + month + \\\"-\\\" + day;\\n    return dateTime;\\n}\\nconst timestampArr = data.series[0].fields[0].values;\\nconst all = data.series[0].fields[1].values; //每天的累积完成数，当前以及之前总的完成数\\nconst newAll = [];\\nconst over = data.series[1].fields[1].values;\\nconst totalCompleted = over.reduce((acc, val) =\\u003e acc + val, 0); \\n\\n\\nconst dateTimeArr = [];\\nconst today = new Date().setHours(0, 0, 0, 0);\\nlet todayF = timestampArr.length;\\nfor (let i = 0; i \\u003c timestampArr.length; i++) {\\n    if (todayF == timestampArr.length \\u0026\\u0026 today \\u003c timestampArr[i]) {\\n        todayF = i;\\n    }\\n    dateTimeArr.push(formatDate(new Date(timestampArr[i])))\\n}\\n\\n\\n\\nconst allOver = []; \\nallOver[0] = over[0];\\nnewAll[0] = all[0] + over[0];\\nfor (let i = 1; i \\u003c todayF; i++) {\\n    allOver[i] = allOver[i-1]+over[i];\\n    newAll[i] = all[i] + allOver[i];\\n}\\n\\n//当天之后数据沿用当天的值\\nif (todayF \\u003e 0) {\\n    for (let i = todayF; i \\u003c over.length; i++) {\\n//         allOver[i] = allOver[todayF-1];\\n        newAll[i] = newAll[todayF-1];\\n    }\\n}\\n\\n\\n\\n\\nconst option = {\\n    color: [\'#54a0e8\', \'#78c492\'],\\n    grid: {\\n        left: \'10%\'\\n    },\\n    tooltip: {\\n        trigger: \'axis\',\\n        formatter: (params) =\\u003e {\\n            let res = `${params[0].name} \\u003cbr/\\u003e`;\\n            for (const item of params) {\\n                res += `\\u003cspan style=\\\"background: ${item.color}; height:10px; width: 10px; border-radius: 50%;display: inline-block;margin-right:10px;margin-top: 5px\\\"\\u003e\\u003c/span\\u003e ${item.seriesName} ：${Math.abs(item.value)}\\u003cbr/\\u003e`;\\n            }\\n            return res;\\n        }\\n    },\\n\\n    legend: {\\n        data: [\'全部\', \'完成\'],\\n        icon: \'circle\',\\n        itemHeight: 8,\\n        itemWidth: 8,\\n        right: 0,\\n    },\\n    xAxis: [\\n        {\\n            type: \'category\',\\n            data: dateTimeArr,\\n            axisLine: { show: false },\\n            axisTick: { show: false },\\n            axisLabel: { show: true },\\n        }\\n    ],\\n    yAxis: [\\n        {\\n            min: 0,\\n            type: \'value\',\\n            minInterval: 5,\\n            axisLabel: { formatter: (value) =\\u003e Math.abs(value) },\\n            splitLine: { lineStyle: { type: \'solid\', color: \'#ccc\' } },\\n        }\\n    ],\\n    series: [\\n        {\\n            name: \'全部\',\\n            type: \'line\',\\n            data: newAll,\\n            smooth: true,\\n            lineStyle: { \\n                color: \'#54a0e8\',\\n                width: 2,\\n                // type: \'dashed\'\\n            },\\n            symbol: \'none\',\\n        },\\n        {\\n            name: \'完成\',\\n            type: \'line\',\\n            data: allOver,\\n            barWidth: 20,\\n            areaStyle: { color: \'#d5eddf\', opacity: 0.5 },\\n            // z: -1,\\n            itemStyle: { normal: { barBorderRadius: [5, 5, 0, 0] } },\\n        }\\n    ],\\n    graphic: [\\n        {\\n            type: \'text\',\\n            left: \'7%\', // 移动到最左边\\n            top: \'1%\', // 适当调整顶部位置\\n            style: {\\n                text: `总完成数: ${totalCompleted}`,\\n                fontSize: 13,\\n                fill: \'#333\',\\n                fontFamily: \'Inter, Helvetica, Arial, sans-serif\',\\n                fontWeight: \'bold\'\\n            },\\n        }\\n    ]\\n};\\n\\nechartsInstance.setOption(option);\\n\"},\"targets\":[{\"cacheDurationSeconds\":0,\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"CfuKN5mIk\"},\"fields\":[{\"jsonPath\":\"$.data[*].date\",\"language\":\"jsonpath\",\"name\":\" \",\"type\":\"time\"},{\"jsonPath\":\"$.data[*].count\",\"language\":\"jsonpath\",\"name\":\" \",\"type\":\"number\"}],\"headers\":[[\"Amp-Organ-Id\",\"$amp_organ_id\"]],\"method\":\"GET\",\"params\":[[\"issueTypes\",\"${issueType:csv}\"],[\"metricType\",\"1\"],[\"sprintId\",\"$sprint_id\"]],\"queryParams\":\"\",\"refId\":\"all\",\"urlPath\":\"/track/issues/analyse/issuesTimeSeriesMetric-overview\"},{\"cacheDurationSeconds\":0,\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"CfuKN5mIk\"},\"fields\":[{\"jsonPath\":\"$.data[*].date\",\"name\":\" \",\"type\":\"time\"},{\"jsonPath\":\"$.data[*].count\",\"language\":\"jsonpath\",\"name\":\" \",\"type\":\"number\"}],\"headers\":[[\"Amp-Organ-Id\",\"$amp_organ_id\"]],\"hide\":false,\"method\":\"GET\",\"params\":[[\"issueTypes\",\"${issueType:csv}\"],[\"metricType\",\"4\"],[\"sprintId\",\"$sprint_id\"]],\"queryParams\":\"\",\"refId\":\"over\",\"urlPath\":\"/track/issues/analyse/issuesTimeSeriesMetric-overview\"}],\"title\":\"工作项燃起图\",\"type\":\"bilibala-echarts-panel\"}],\"schemaVersion\":39,\"tags\":[],\"templating\":{\"list\":[{\"allValue\":\"\\\"\\\"\",\"current\":{\"sel