:\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.time,1d),\\n  middle.count as \'数量\'\\nFROM (select count(1) as count,p.create_time as time\\nfrom devops_product p\\nleft join devops_repository r on p.repo_id=r.id\\nwhere p.create_time is not null and if(\'$amp_organ_id\'=\'null\', 1=1, r.tenant_id = \'$amp_organ_id\')\\ngroup by date_format(p.create_time, \'%Y%m%d\')\\norder by p.create_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.time)\\nORDER BY $__timeGroup(middle.time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"每日新增制品数量\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"b-L36I-4z\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false}},\"mappings\":[]},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"延期项目\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"dark-red\",\"mode\":\"fixed\"}}]},{\"__systemRef\":\"hideSeriesFrom\",\"matcher\":{\"id\":\"byNames\",\"options\":{\"mode\":\"exclude\",\"names\":[\"count\",\"未开始\"],\"prefix\":\"All except:\",\"readOnly\":true}},\"properties\":[{\"id\":\"custom.hideFrom\",\"value\":{\"legend\":false,\"tooltip\":false,\"viz\":true}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"关闭\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#24292e\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"未开始\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"light-blue\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"已完成\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"延期处理\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"su