0].fields[0].values.buffer;\\nconst newCountArr = data.series[0].fields[1].values.buffer;\\nconst finishCountArr = data.series[0].fields[2].values.buffer;\\nconst remainCountArr = data.series[0].fields[3].values.buffer;\\nconst mockData = [];\\nfor(let i = 0;i\\u003ctimeArr.length;i++) {\\n  mockData.push({\\n    time: formatDate(new Date(timeArr[i])),\\n    new: newCountArr[i],\\n    fix: finishCountArr[i],\\n    stock: remainCountArr[i]\\n  })\\n}\\n\\n  const timeArray = mockData.map((item) =\\u003e item.time)\\n  const newArray = mockData.map((item) =\\u003e item.new)\\n  const fixArray = mockData.map((item) =\\u003e item.fix * -1)\\n  const stockArray = mockData.map((item) =\\u003e item.stock)\\n  const option = {\\n    color: [\'#FADF60\', \'#E27668\', \'#6BC07A\'],\\n    grid: {\\n      right: 0,\\n    },\\n    tooltip: {\\n      trigger: \'axis\',\\n      formatter: (params) =\\u003e {\\n        let res = `${params[0].name} \\u003cbr/\\u003e`\\n        for (const item of params) {\\n          res += `\\u003cspan style=\\\"background: ${\\n            item.color\\n          }; height:10px; width: 10px; border-radius: 50%;display: inline-block;margin-right:10px;margin-top: 5px\\\"\\u003e\\u003c/span\\u003e ${\\n            item.seriesName\\n          } ：${Math.abs(item.value)}\\u003cbr/\\u003e`\\n        }\\n        return res\\n      },\\n    },\\n    legend: {\\n      data: [\'存量\', \'新增\', \'修复\'],\\n      icon: \'circle\',\\n      itemHeight: 8,\\n      itemWidth: 8,\\n      right: 0,\\n    },\\n    xAxis: [\\n      {\\n        type: \'category\',\\n        data: timeArray,\\n        axisPointer: {\\n          type: \'shadow\',\\n        },\\n        axisTick: {\\n          show: false,\\n        },\\n        axisLine: {\\n          show: false,\\n        },\\n      },\\n    ],\\n    yAxis: [\\n      {\\n        type: \'value\',\\n        minInterval: 5,\\n        axisLabel: {\\n          formatter: (value) =\\u003e {\\n            return Math.abs(value)\\n          },\\n        },\\n      },\\n    ],\\n    series: [\\n      {\\n        name: \'存量\',\\n        type: \'line\',\\n        data: stockArray,\\n        smooth: true,\\n        areaStyle: {\\n          color: \'#FDFAEC\',\\n        },\\n        z: -1,\\n        symbol: \'none\',\\n      },\\n      {\\n        name: \'新增\',\\n        type: \'bar\',\\n        stack: \'stack\',\\n        data: newArray,\\n        barWidth: 20,\\n        itemStyle: {\\n          normal: {\\n            barBorderRadius: [5, 5, 0, 0],\\n          },\\n        },\\n      },\\n      {\\n        name: \'修复\',\\n        type: \'bar\',\\n        stack: \'stack\',\\n        data: fixArray,\\n        barWidth: 20,\\n        itemStyle: {\\n          normal: {\\n            barBorderRadius: [0, 0, 5, 5],\\n          },\\n        },\\n      },\\n    ],\\n  }\\n  echartsInstance.setOption(option)\"},\"pluginVersion\":\"8.4.4\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"hide\":false,\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"select \\n$__timeGroupAlias(i1.create_time,1d),\\ncount(1) as new_count,\\n(select count(1) from issues i2 where i2.del_flag=0 and i2.issues_type_id=98 and find_in_set(\'$userId\',i2.assigned_ids) and if(\'$amp_organ_id\'=\'null\', 1=1, i2.tenant_id =  \'$amp_organ_id\')   and date_format(cast(i2.close_time as datetime), \'%Y%m%d\') = date_format(cast(i1.create_time as datetime), \'%Y%m%d\') and i2.status_id in (\'7855\',\'4\') ) as finish_count,\\n\\n((select count(1) from issues i2 where i2.del_flag=0 and i2.issues_type_id=98 and find_in_set(\'$userId\',i2.assigned_ids) and if(\'$amp_organ_id\'=\'null\', 1=1, i2.tenant_id =  \'$amp_organ_id\')   and date_format(cast(i2.create_time as datetime), \'%Y%m%d\') \\u003c= date_format(cast(i1.create_time as datetime), \'%Y%m%d\')) - (select count(1) from issues i3 where i3.del_flag=0 and i3.issues_type_id=98 and find_in_set(\'$userId\',i3.assigned_ids) and if(\'$amp_organ_id\'=\'null\', 1=1, i3.tenant_id =  \'$amp_organ_id\')   and date_format(cast(i3.close_time as datetime), \'%Y%m%d\') \\u003c= date_format(cast(i1.create_time as datetime), \'%Y%m%d\') and i3.status_id in (\'7855\',\'4\'))) as remain_count\\n\\n\\n\\n\\nfrom issues i1\\nwhere  i1.issues_type_id=98\\n and find_in_set(\'$userId\',i1.assigned_ids)\\n and i1.del_flag=0\\n and if(\'$amp_organ_id\'=\'null\', 1=1, i1.tenant_id =  \'$amp_organ_id\') \\nand $__timeFilter(i1.create_time)\\ngroup by date_format(cast(i1.create_time as datetime), \'%Y%m%d\')\\n\\nORDER BY i1.create_time ASC\\n\\n\\n\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"artifacts_repositories\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"timestamp\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"缺陷趋势\",\"transformations\":[],\"type\":\"bilibala-echarts-panel\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"description\":\"统计当天完成的需求耗时，按周统计\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"bars\",\"fillOpacity\":100,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"normal\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\"}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"耗时1周内\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#6a6df6\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"耗时1-2周\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#81d4cf\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"耗时2-4周\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#edd759\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"耗时4周以上\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#e55731\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":9,\"w\":12,\"x\":0,\"y\":21},\"id\":13,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"rawQuery\":true,\"rawSql\":\"select $__timeGroupAlias(create_time,1d),\\ncase when UNIX_TIMESTAMP(cast(close_time as datetime)) - UNIX_TIMESTAMP(cast(real_start_time as datetime)) \\u003c= 604800 then \'耗时1周内\'\\nwhen UNIX_TIMESTAMP(cast(close_time as datetime)) - UNIX_TIMESTAMP(cast(real_start_time as datetime)) \\u003c= 1209600 then \'耗时1-2周\'\\nwhen UNIX_TIMESTAMP(cast(close_time as datetime)) - UNIX_TIMESTAMP(cast(real_start_time as datetime)) \\u003c= 2419200 then \'耗时2-4周\'\\nelse \'耗时4周以上\' end as metric,count(1)\\n\\n\\n\\n from issues  where  issues_type_id=\'96\' and del_flag=0 and real_start_time is not null and close_time is not null and del_flag=0\\n and $__timeFilter(create_time)\\n group by date_format(create_time, \'%Y%m%d\'),metric\\n\\n\\n\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"需求交付吞吐量\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"description\":\"统计当天修复的缺陷耗时，按周统计\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"bars\",\"fillOpacity\":100,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"normal\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\"}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"耗时1周内\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#6a6df6\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"耗时1-2周\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#81d4cf\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"耗时2-4周\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#edd759\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"耗时4周以上\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#e55731\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":9,\"w\":12,\"x\":12,\"y\":21},\"id\":14,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"rawQuery\":true,\"rawSql\":\"select $__timeGroupAlias(i.create_time,1d),\\ncase when UNIX_TIMESTAMP(cast(i.close_time as datetime)) - UNIX_TIMESTAMP(cast(i.real_start_time as datetime)) \\u003c= 604800 then \'耗时1周内\'\\nwhen UNIX_TIMESTAMP(cast(i.close_time as datetime)) - UNIX_TIMESTAMP(cast(i.real_start_time as datetime)) \\u003c= 1209600 then \'耗时1-2周\'\\nwhen UNIX_TIMESTAMP(cast(i.close_time as datetime)) - UNIX_TIMESTAMP(cast(i.real_start_time as datetime)) \\u003c= 2419200 then \'耗时2-4周\'\\nelse \'耗时4周以上\' end as metric,count(1)\\n\\n\\n\\n from issues i left join issues_status s on i.status_id=s.id  where  i.issues_type_id=\'98\' and i.del_flag=0 and i.real_start_time is not null and i.close_time is not null and i.del_flag=0 and s.type in(2,3)\\n and $__timeFilter(i.create_time)\\n group by date_format(i.create_time, \'%Y%m%d\'),metric\\n\\n\\n\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"缺陷修复吞吐量\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"auto\",\"displayMode\":\"auto\",\"inspect\":false},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\"},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":30},\"id\":7,\"options\":{\"footer\":{\"countRows\":false,\"fields\":\"\",\"reducer\":[\"sum\"],\"show\":false},\"showHeader\":true},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select  i.title as \'标题\', s.name as \'状态\', i.start_date as \'计划开始日期\',i.end_date as \'计划完成日期\'\\nfrom issues i left join issues_status s on i.status_id=s.id\\n where  issues_type_id=\'96\' and s.type in (\'0\',\'1\')\\n and find_in_set(\'$userId\',i.assigned_ids)\\n and i.del_flag=0\\n and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\n order by s.type,i.create_time\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}]