) \\u003c= 1209600 then \'耗时1-2周\'\\nwhen UNIX_TIMESTAMP(cast(i.close_time as datetime)) - UNIX_TIMESTAMP(cast(i.real_start_time as datetime)) \\u003c= 2419200 then \'耗时2-4周\'\\nelse \'耗时4周以上\' end as metric,count(1)\\n\\n\\n\\n from issues i left join issues_status s on i.status_id=s.id  where  i.issues_type_id=\'98\' and i.del_flag=0 and i.real_start_time is not null and i.close_time is not null and i.del_flag=0 and s.type in(2,3)\\n and $__timeFilter(i.create_time)\\n group by date_format(i.create_time, \'%Y%m%d\'),metric\\n\\n\\n\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"缺陷修复吞吐量\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"auto\",\"displayMode\":\"auto\",\"inspect\":false},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":22},\"id\":7,\"options\":{\"footer\":{\"countRows\":false,\"fields\":\"\",\"reducer\":[\"sum\"],\"show\":false},\"showHeader\":true},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select  i.title as \'标题\', s.name as \'状态\', i.start_date as \'计划开始日期\',i.end_date as \'计划完成日期\'\\nfrom issues i left join issues_status s on i.status_id=s.id\\n where  issues_type_id=\'96\' and s.type in (\'0\',\'1\')\\n and find_in_set(\'$userId\',i.assigned_ids)\\n and i.del_flag=0\\n and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\n order by s.type,i.create_time\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"strin