$tagIdAndName\\\",locate(\\\",\\\", \\\"$tagIdAndName\\\",locate(concat(\\\"\'\\\", tag_ids,\\\",\\\"),\\\"$tagIdAndName\\\"))+1) - locate(\',\', \\\"$tagIdAndName\\\",locate(concat(\\\"\'\\\", tag_ids,\\\",\\\"),\\\"$tagIdAndName\\\"))-1) as name,\\n\\n\\ncount(1) as \'数量\'\\nfrom issues_type_ext_pm_bug b left join issues_tag t on b.issues_id=t.issues_id \\nwhere b.issues_id in(\\nselect id from issues where issues_type_id = 98 and del_flag=0 and  if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\nand if(\\\"$userNames\\\" = \\\"\'all\'\\\", 1=1, assigned_ids regexp concat(\'(^|,)(\',replace(replace(\\\"$userIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')))\\n\\nand if(\\\"$projectName\\\" = \\\"\'all\'\\\", 1=1  ,belong_to_project in($projectIds))\\nand if(\\\"$sprintName\\\" = \\\"\'all\'\\\", 1=1  ,sprint in($sprintIds))\\nand if(\\\"$bugSolutionName\\\" = \\\"\'all\'\\\", 1=1  ,bug_type in ($bugSolutionName))\\nand if(\\\"$tagName\\\" =\\\"\'all\'\\\",1=1,t.tag_ids in ($tagIds))\\nand tag_ids is not null\\nand substring(\\\"$tagIdAndName\\\", locate(\',\', \\\"$tagIdAndName\\\",locate(concat(\\\"\'\\\", tag_ids,\\\",\\\"),\\\"$tagIdAndName\\\"))+1,locate(\\\"\'\\\",\\\"$tagIdAndName\\\",locate(\\\",\\\", \\\"$tagIdAndName\\\",locate(concat(\\\"\'\\\", tag_ids,\\\",\\\"),\\\"$tagIdAndName\\\"))+1) - locate(\',\', \\\"$tagIdAndName\\\",locate(concat(\\\"\'\\\", tag_ids,\\\",\\\"),\\\"$tagIdAndName\\\"))-1) \\n !=\'\'\\n\\ngroup by tag_ids\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"缺陷标签分布统计图\",\"transformations\":[{\"id\":\"convertFieldType\",\"options\":{\"conversions\":[{\"destinationType\":\"string\",\"targetField\":\"name\"}],\"fields\":{}}}],\"type\":\"piechart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false}},\"mappings\":[]},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"功能问题\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"性能问题\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"super-light-red\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"UI问题\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"blue\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"安全问题\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"dark-red\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"数据问题\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"orange\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"易用性问题\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"yellow\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":6},\"id\":25,\"options\":{\"legend\":{\"displayMode\":\"list\",\"placement\":\"right\",\"showLegend\":true,\"values\":[\"percent\"]},\"pieType\":\"pie\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"/^数量$/\",\"values\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"desc\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"\\n\\n\\n\\n\\n\\nselect \\nbug_type,\\n\\n\\ncount(1) as \'数量\'\\nfrom issues_type_ext_pm_bug b left join issues_tag t on b.issues_id=t.issues_id \\nwhere b.issues_id in(\\nselect id from issues where issues_type_id = 98 and del_flag=0 and  if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\nand if(\\\"$userNames\\\" = \\\"\'all\'\\\", 1=1, assigned_ids regexp concat(\'(^|,)(\',replace(replace(\\\"$userIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')))\\nand if(\\\"$projectName\\\" = \\\"\'all\'\\\", 1=1  ,belong_to_project in($projectIds))\\nand if(\\\"$sprintName\\\" = \\\"\'all\'\\\", 1=1  ,sprint in($sprintIds))\\nand if(\\\"$bugSolutionName\\\" = \\\"\'all\'\\\", 1=1  ,bug_type in ($bugSolutionName))\\nand if(\\\"$tagName\\\" =\\\"\'all\'\\\",1=1,t.tag_ids in ($tagIds))\\nand tag_ids is not null\\nand bug_type is not null\\n\\ngroup by bug_type\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"缺陷类型统计图\",\"type\":\"piechart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"description\":\"当前时刻尚未完成的缺陷按严重程度、优先级、状态、阶段的分布占比\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false}},\"mappings\":[],\"min\":-3},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":14},\"id\":10,\"options\":{\"displayLabels\":[],\"legend\":{\"displayMode\":\"list\",\"placement\":\"right\",\"showLegend\":true,\"values\":[\"percent\",\"value\"]},\"pieType\":\"donut\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"/^value$/\",\"values\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"\\n\\nselect (case priority_id\\nwhen 1 then\'低\'\\nwhen 2 then\'中\'\\nwhen 3 then\'高\'\\nwhen 4 then\'紧急\' end) as name,count(1) as value from issues where issues_type_id = 98 and  if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\nand if(\\\"$userNames\\\" = \\\"\'all\'\\\", 1=1, assigned_ids regexp concat(\'(^|,)(\',replace(replace(\\\"$userIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')) and status_id not in (3,4,7855) and del_flag=0 group by priority_id \",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"artifacts_repositories\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"timestamp\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"存量缺陷占比\",\"transformations\":[],\"type\":\"piechart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"description\":\"所选时间区间内完成的缺陷，按完成日期排列，横坐标为时间，纵坐标为缺陷创建到修复的周期（天）。其中圆点表示一个已修复的缺陷，折线表示需求修复缺陷的滚动均值，红色阴影区域表示滚动标准差，横虚线表示所选时间区间内，缺陷修复周期的平均值\",\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":14},\"id\":8,\"options\":{\"followTheme\":false,\"getOption\":\"console.log(data);\\nif(data.series.length==0) {\\n  return;\\n}\\nfunction formatDate(dat){\\n    //获取年月日，时间\\n    var year = dat.getFullYear();\\n    var mon = (dat.getMonth()+1) \\u003c 10 ? \\\"0\\\"+(dat.getMonth()+1) : dat.getMonth()+1;\\n    var data = dat.getDate()  \\u003c 10 ? \\\"0\\\"+(dat.getDate()) : dat.getDate();\\n    var hour = dat.getHours()  \\u003c 10 ? \\\"0\\\"+(dat.getHours()) : dat.getHours();\\n    var min =  dat.getMinutes()  \\u003c 10 ? \\\"0\\\"+(dat.getMinutes()) : dat.getMinutes();\\n                 \\n    var newDate = year +\\\"-\\\"+ mon +\\\"-\\\"+ data +\\\" \\\"+ hour +\\\":\\\"+ min;\\n    return newDate;\\n}\\nconst timeArr = data.series[0].fields[0].values.buffer;\\nconst needArr = data.series[0].fields[1].values.buffer;\\nconst mockData=[];\\nfor(let i=0;i\\u003ctimeArr.length;i++) {\\n  mockData.push({\\n    time: formatDate(new Date(timeArr[i])),\\n    need: needArr[i]\\n  })\\n}\\n\\n  //时间\\n  const timeArray = mockData.map((item) =\\u003e item.time)\\n  //需求-散点\\n  const timeAndNeedArray = mockData.map((item) =\\u003e [item.time, item.need])\\n  //均值-直线\\n  const needArray = mockData.map((item) =\\u003e item.need)\\n  const funcSum = (arr) =\\u003e {\\n    return eval(arr.join(\'+\'))\\n  }\\n  const avg = (funcSum(needArray) / needArray.length).toFixed(4)\\n  const avgArray = mockData.map(() =\\u003e avg)\\n  //滚动均值-折线\\n  const rollAvgArray = []\\n  //滚动标准差-max-折线\\n  const rollMaxArray = []\\n  //滚动标准差-min-折线\\n  const rollMinArray = []\\n  for (let i = 0; i \\u003c needArray.length; i++) {\\n    const temp = needArray.slice(i - 2 \\u003c 0 ? 0 : i - 2, i + 2)\\n    const avg = funcSum(temp) / temp.length\\n    rollAvgArray.push(avg.toFixed(4))\\n    let sum = 0\\n    temp.forEach((v) =\\u003e {\\n      sum += (v - avg) * (v - avg)\\n    })\\n    const sqrt = Math.sqrt(sum / temp.length)\\n    const min = (avg - sqrt).toFixed(4)\\n    const max = (avg + sqrt - min).toFixed(4)\\n    rollMinArray.push(min)\\n    rollMaxArray.push(max)\\n  }\\n\\n  const option = {\\n    color: [\'#E99F97\', \'#FBEEED\', \'#E27668\', \'#FADF60\'],\\n//     color: [\'#A3BFE6\', \'#E5F0FB\', \'#72AFE7\', \'#78C78C\'],\\n    tooltip: {\\n      show: true,\\n      trigger: \'axis\',\\n      formatter: (params) =\\u003e {\\n        let res = `${params[0].name} \\u003cbr/\\u003e`\\n        for (const item of params) {\\n          if (item.seriesName !== \'标准差\') {\\n            res += `\\u003cspan style=\\\"background: ${\\n              item.color\\n            }; height:10px; width: 10px; border-radius: 50%;display: inline-block;margin-right:10px;margin-top: 5px\\\"\\u003e\\u003c/span\\u003e ${\\n              item.seriesName\\n            } ：${\\n              typeof item.value === \'object\' ? item.value[1] : item.value\\n            }\\u003cbr/\\u003e`\\n          }\\n        }\\n        return res\\n      },\\n    },\\n    legend: {\\n      data: [\\n        {\\n          name: \'需求\',\\n        },\\n        {\\n          name: \'标准差\',\\n          icon: \'rect\',\\n        },\\n        {\\n          name: \'滚动均值(4个)\',\\n          icon: \'path://M212.8000030517578,468.79998779296875L43.20000076293945,468.79998779296875C17.600000381469727,468.79998779296875,0,486.3999938964844,0,512s17.60000038146972