);\\n})\\n\\nreturn {\\n  tooltip: {\\n    trigger: \'axis\',\\n    axisPointer: {\\n      // Use axis to trigger tooltip\\n      type: \'shadow\' // \'shadow\' as default; can also be \'line\' or \'shadow\'\\n    }\\n  },\\n  legend: {},\\n  grid: {\\n    left: \'3%\',\\n    right: \'4%\',\\n    bottom: \'3%\',\\n    containLabel: true\\n  },\\n  xAxis: {\\n    type: \'value\'\\n  },\\n  yAxis: {\\n    type: \'category\',\\n    data: Array.from(new Set(memberNameArr))\\n  },\\n  series: [\\n    {\\n      name: \'紧急\',\\n      type: \'bar\',\\n      stack: \'total\',\\n      label: {\\n        show: true\\n      },\\n      emphasis: {\\n        focus: \'series\'\\n      },\\n      data: jinji\\n    },\\n    {\\n      name: \' 高\',\\n      type: \'bar\',\\n      stack: \'total\',\\n      label: {\\n        show: true\\n      },\\n      emphasis: {\\n        focus: \'series\'\\n      },\\n      data: gao\\n    },\\n    {\\n      name: \'中\',\\n      type: \'bar\',\\n      stack: \'total\',\\n      label: {\\n        show: true\\n      },\\n      emphasis: {\\n        focus: \'series\'\\n      },\\n      data: zhong\\n    },\\n    {\\n      name: \'低\',\\n      type: \'bar\',\\n      stack: \'total\',\\n      label: {\\n        show: true\\n      },\\n      emphasis: {\\n        focus: \'series\'\\n      },\\n      data: di\\n    }\\n  ]\\n};\"},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"\\n\\nselect \\nsubstring(\\\"$projectIdAndName\\\", locate(\',\', \\\"$projectIdAndName\\\",locate(concat(\\\"\'\\\", m.belong_to_project,\\\",\\\"),\\\"$projectIdAndName\\\"))+1,locate(\\\"\'\\\",\\\"$projectIdAndName\\\",locate(\\\",\\\", \\\"$projectIdAndName\\\",locate(concat(\\\"\'\\\", m.belong_to_project,\\\",\\\"),\\\"$projectIdAndName\\\"))+1) - locate(\',\', \\\"$projectIdAndName\\\",locate(concat(\\\"\'\\\", m.belong_to_project,\\\"