\":\"auto\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"\",\"values\":false},\"textMode\":\"auto\"},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select count(1) from issues_type_ext_pm_bug where issues_id in (\\nselect id from issues where issues_type_id=\'98\' and del_flag=0 and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\nand if(\\\"$userNames\\\" = \\\"\'all\'\\\", 1=1, assigned_ids regexp concat(\'(^|,)(\',replace(replace(\\\"$userIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\nand is_reopen = \'1\'\\nand $__timeFilter(create_time) \\n) \\nand if(\\\"$projectName\\\" = \\\"\'all\'\\\", 1=1  ,belong_to_project in($projectIds))\\nand if(\\\"$sprintName\\\" = \\\"\'all\'\\\", 1=1  ,sprint in($sprintIds))\\nand if(\\\"$bugSolutionName\\\" = \\\"\'all\'\\\", 1=1  ,bug_type in ($bugSolutionName))\\nand  if(\\\"$tagName\\\" =\\\"\'all\'\\\",1=1,issues_id in(select issues_id from issues_tag where tag_ids in ($tagIds)))\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"重新打开缺陷数\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":4,\"w\":4,\"x\":20,\"y\":0},\"id\":38,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"auto\",\"orientation\":\"auto\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"\",\"limit\":1,\"values\":true},\"textMode\":\"auto\"},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorM