onth;\\n  }\\n  if (day.length == 1) {\\n    day = \\\"0\\\" + day;\\n  }\\n  var dateTime = year + \\\"-\\\" + month + \\\"-\\\" + day;\\n  return dateTime;\\n}\\nconst timeArr = data.series[0].fields[0].values.buffer;\\nconst newCountArr = data.series[0].fields[1].values.buffer;\\nconst finishCountArr = data.series[0].fields[2].values.buffer;\\nconst remainCountArr = data.series[0].fields[3].values.buffer;\\nconst mockData = [];\\nfor(let i = 0;i\\u003ctimeArr.length;i++) {\\n  mockData.push({\\n    time: formatDate(new Date(timeArr[i])),\\n    new: newCountArr[i],\\n    fix: finishCountArr[i],\\n    stock: remainCountArr[i]\\n  })\\n}\\n\\n  const timeArray = mockData.map((item) =\\u003e item.time)\\n  const newArray = mockData.map((item) =\\u003e item.new)\\n  const fixArray = mockData.map((item) =\\u003e item.fix * -1)\\n  const stockArray = mockData.map((item) =\\u003e item.stock)\\n  const option = {\\n    color: [\'#FADF60\', \'#E27668\', \'#6BC07A\'],\\n    grid: {\\n      right: 0,\\n    },\\n    tooltip: {\\n      trigger: \'axis\',\\n      formatter: (params) =\\u003e {\\n        let res = `${params[0].name} \\u003cbr/\\u003e`\\n        for (const item of params) {\\n          res += `\\u003cspan style=\\\"background: ${\\n            item.color\\n          }; height:10px; width: 10px; border-radius: 50%;display: inline-block;margin-right:10px;margin-top: 5px\\\"\\u003e\\u003c/span\\u003e ${\\n            item.seriesName\\n          } ：${Math.abs(item.value)}\\u003cbr/\\u003e`\\n        }\\n        return res\\n      },\\n    },\\n    legend: {\\n      data: [\'存量\', \'新增\', \'完成\'],\\n      icon: \'circle\',\\n      itemHeight: 8,\\n      itemWidth: 8,\\n      right: 0,\\n    },\\n    xAxis: [\\n      {\\n        type: \'category\',\\n        data: timeArray,\\n        axisPointer: {\\n          type: \'shadow\',\\n        },\\n        axisTick: {\\n          show: false,\\n        },\\n        axisLine: {\\n          show: false,\\n        },\\n      },\\n    ],\\n    yAxis: [\\n      {\\n        type: \'value\',\\n        minInterval: 5,\\n        axisLabel: {\\n          formatter: (value) =\\u003e {\\n            return Math.abs(value)\\n          },\\n        },\\n      },\\n    ],\\n    series: [\\n      {\\n        name: \'存量\',\\n        type: \'line\',\\n        data: stockArray,\\n        smooth: true,\\n        areaStyle: {\\n          color: \'#FDFAEC\',\\n        },\\n        z: -1,\\n        symbol: \'none\',\\n      },\\n      {\\n        name: \'新增\',\\n        type: \'bar\',\\n        stack: \'stack\',\\n        data: newArray,\\n        barWidth: 20,\\n        itemStyle: {\\n          normal: {\\n            barBorderRadius: [5, 5, 0, 0],\\n          },\\n        },\\n      },\\n      {\\n        name: \'完成\',\\n        type: \'bar\',\\n        stack: \'stack\',\\n        data: fixArray,\\n        barWidth: 20,\\n        itemStyle: {\\n          normal: {\\n            barBorderRadius: [0, 0, 5, 5],\\n          },\\n        },\\n      },\\n    ],\\n  }\\n  echartsInstance.setOption(option)\"},\"pluginVersion\":\"8.4.4\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"hide\":false,\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"select \\n$__timeGroupAlias(i1.create_time,1d),\\ncount(1) as new_count,\\n(select count(1) from issues i2 where i2.del_flag=0 and i2.issues_type_id=96 and find_in_set(\'$userId\',i2.assigned_ids) and if(\'$amp_organ_id\'=\'null\', 1=1, i2.tenant_id =  \'$amp_organ_id\')   and date_format(cast(i2.close_time as datetime), \'%Y%m%d\') = date_format(cast(i1.create_time as datetime), \'%Y%m%d\') and i2.status_id in (\'3\',\'4\',\'10\') ) as finish_count,\\n\\n((select count(1) from issues i2 where i2.del_flag=0 and i2.issues_type_id=96 and find_in_set(\'$userId\',i2.assigned_ids) and if(\'$amp_organ_id\'=\'null\', 1=1, i2.tenant_id =  \'$amp_organ_id\')   and date_format(cast(i2.c