INSERT INTO `dashboard_version` VALUES (337, 32, 44, 0, 45, '2023-11-24 14:31:47', 1, '', '{\"annotations\":{\"list\":[{\"builtIn\":1,\"datasource\":{\"type\":\"grafana\",\"uid\":\"-- Grafana --\"},\"enable\":true,\"hide\":true,\"iconColor\":\"rgba(0, 211, 255, 1)\",\"name\":\"Annotations \\u0026 Alerts\",\"target\":{\"limit\":100,\"matchAny\":false,\"tags\":[],\"type\":\"dashboard\"},\"type\":\"dashboard\"}]},\"editable\":true,\"fiscalYearStartMonth\":0,\"graphTooltip\":0,\"id\":32,\"links\":[],\"liveNow\":false,\"panels\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":4,\"w\":20,\"x\":0,\"y\":0},\"id\":2,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"auto\",\"orientation\":\"auto\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"/^count$/\",\"values\":true},\"textMode\":\"auto\"},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select  \'待处理需求\' as name,concat(count(1), \'个\')  as count\\nfrom issues i left join issues_status s on i.status_id=s.id\\n where  issues_type_id=\'96\' and s.type = 0\\n and find_in_set(\'$userId\',i.assigned_ids)\\n and i.del_flag=0\\n and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\n\\n union\\n\\nselect  \'处理中需求\' as name,concat(count(1), \'个\')  as count\\nfrom issues i left join issues_status s on i.status_id=s.id\\n where  issues_type_id=\'96\' and s.type = 1\\n and find_in_set(\'$userId\',i.assigned_ids)\\n and i.del_flag=0\\n and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"hide\":false,\"rawQuery\":true,\"rawSql\":\" select \'逾期需求\' as name,concat(count(1),\'个\') as count\\nfrom issues i left join issues_status s on i.status_id=s.id\\n where  i.issues_type_id=\'96\' \\n  and find_in_set(\'$userId\',i.assigned_ids)\\n and i.del_flag=0\\n and i.end_date is not null and i.end_date != \'\' and now() \\u003e cast(i.end_date as date )and (s.type in(0,1) or cast(i.close_time as date) \\u003e cast(i.end_date as date))\\nand if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\')\",\"refId\":\"B\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"hide\":false,\"rawQuery\":true,\"rawSql\":\"select  \'待处理缺陷\' as name,concat(count(1), \'个\')  as count\\nfrom issues i left join issues_status s on i.status_id=s.id\\n where  issues_type_id=\'98\' and s.type = 0\\n and find_in_set(\'$userId\',i.assigned_ids)\\n and i.del_flag=0\\n and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\n\\n union\\n\\nselect  \'处理中缺陷\' as name,concat(count(1), \'个\')  as count\\nfrom issues i left join issues_status s on i.status_id=s.id\\n where  issues_type_id=\'98\' and s.type = 1\\n and i.assigned_ids like concat(\'%\',\'$userId\',\'%\')\\n and i.del_flag=0\\n and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\n\",\"refId\":\"C\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"hide\":false,\"rawQuery\":true,\"rawS