ults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"bars\",\"fillOpacity\":100,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"normal\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"耗时1周内\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#6a6df6\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"耗时1-2周\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#81d4cf\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"耗时2-4周\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#edd759\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"耗时4周以上\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#e55731\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":9,\"w\":12,\"x\":12,\"y\":12},\"id\":14,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"rawQuery\":true,\"rawSql\":\"select $__timeGroupAlias(i.create_time,1d),\\ncase when UNIX_TIMESTAMP(cast(i.close_time as datetime)) - UNIX_TIMESTAMP(cast(i.real_start_time as datetime)) \\u003c= 604800 then \'耗时1周内\'\\nwhen UNIX_TIMESTAMP(cast(i.close_time as datetime)) - UNIX_TIMESTAMP(cast(i.real_start_time as datetime)) \\u003c= 1209600 then \'耗时1-2周\'\\nwhen UNIX_TIMESTAMP(cast(i.close_time as datetime)) - UNIX_TIMESTAMP(cast(i.real_start_time as datetime)) \\u003c= 2419200 then \'耗时2-4周\'\\nelse \'耗时4周以上\' end as metric,count(1)\\n\\n\\n\\n from issues i left join issues_status s on i.status_id=s.id  where  i.issues_type_id=\'98\' and i.del_flag=0 and i.real_start_time is not null and i.close_time is not null and i.del_flag=0 and s.type in(2,3)\\n and $__timeFilter(i.create_time)\\n group by date_format(i.create_time, \'%Y%m%d\'),metric\\n\\n\\n\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"缺陷修复吞吐量\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"auto\",\"displayMode\":\"auto\",\"inspect\":false},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":21},\"id\":7,\"options\":{\"footer\":{\"countRows\":false,\"fields\":\"\",\"reducer\":[\"sum\"],\"show\":false},\"showHeader\":true},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select  i.title as \'标题\', s.name as \'状态\', i.start_date as \'计划开始日期\',i.end_date as \'计划完成日期\'\\nfrom issues i left join issues_status s on i.status_id=s.id\\n where  issues_type_id=\'96\' and s.type in (\'0\',\'1\')\\n and find_in_set(\'$userId\',i.assigned_ids)\\n and i.del_flag=0\\n and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\n order by s.type,i.create_time\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"未开始和进行中的需求列表\",\"type\":\"table\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"auto\",\"displayMode\":\"auto\",\"inspect\":false},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":21},\"id\":9,\"options\":{\"footer\":{\"countRows\":false,\"fields\":\"\",\"reducer\":[\"sum\"],\"show\":false},\"showHeader\":true},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select  i.title as \'标题\', s.name as \'状态\', i.start_date as \'计划开始日期\',i.end_date as \'计划完成日期\'\\nfrom issues i left join issues_status s on i.status_id=s.id\\n where  issues_type_id=\'98\' and s.type in (\'0\',\'1\')\\n and find_in_set(\'$userId\',i.assigned_ids)\\n and i.del_flag=0\\n and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\n order by s.type,i.create_time\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"未开始和进行中的缺陷列表\",\"type\":\"table\"}],\"schemaVersion\":37,\"style\":\"dark\",\"tags\":[],\"templating\":{\"list\":[{\"current\":{\"selected\":false,\"text\":\"超级管理员\",\"value\":\"超级管理员\"},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select name from sys_user \\nwhere \\nis_deleted=0\\nand if(\'$amp_organ_id\'=\'null\', 1=1,id in(select user_id from sys_user_organization  where organ_id =\'$amp_organ_id\' and resource_id=0)) \\n\\n\\n\",\"hide\":0,\"includeAll\":false,\"label\":\"成员名称\",\"multi\":false,\"name\":\"username\",\"options\":[],\"query\":\"select name from sys_user \\nwhere \\nis_deleted=0\\nand if(\'$amp_organ_id\'=\'null\', 1=1,id in(select user_id from sys_user_organization  where organ_id =\'$amp_organ_id\' and resource_id=0)) \\n\\n\\n\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"},{\"current\":{\"selected\":false,\"text\":\"null\",\"value\":\"null\"},\"hide\":2,\"label\":\"amp_organ_id\",\"name\":\"amp_organ_id\",\"options\":[{\"selected\":true,\"text\":\"null\",\"value\":\"null\"}],\"query\":\"null\",\"skipUrlSync\":false,\"type\":\"textbox\"},{\"current\":{\"selected\":false,\"text\":\"1\",\"value\":\"1\"},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select concat(id,\'\') from sys_user where name = \'$username\' and is_deleted=0\",\"hide\":0,\"includeAll\":false,\"multi\":false,\"name\":\"userId\",\"options\":[],\"query\":\"select concat(id,\'\') from sys_user where name = \'$username\' and is_deleted=0\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"},{\"current\":{\"selected\":false,\"text\":\"admin\",\"value\":\"admin\"},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select username from sys_user where name = \'$username\' and is_deleted=0\",\"hide\":0,\"includeAll\":false,\"multi\":false,\"name\":\"userLoginName\",\"options\":[],\"query\":\"select username from sys_user where name = \'$username\' and is_deleted=0\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"}]},\"time\":{\"from\":\"now-30d\",\"to\":\"now\"},\"timepicker\":{},\"timezone\":\"\",\"title\":\"个人维度\",\"uid\":\"gI8YLVSIk\",\"version\":45,\"weekStart\":\"\"}');
