INSERT INTO `dashboard_version` VALUES (347, 35, 11, 0, 12, '2023-11-24 15:20:10', 1, '', '{\"annotations\":{\"list\":[{\"builtIn\":1,\"datasource\":{\"type\":\"grafana\",\"uid\":\"-- Grafana --\"},\"enable\":true,\"hide\":true,\"iconColor\":\"rgba(0, 211, 255, 1)\",\"name\":\"Annotations \\u0026 Alerts\",\"target\":{\"limit\":100,\"matchAny\":false,\"tags\":[],\"type\":\"dashboard\"},\"type\":\"dashboard\"}]},\"editable\":true,\"fiscalYearStartMonth\":0,\"graphTooltip\":0,\"id\":35,\"links\":[],\"liveNow\":false,\"panels\":[{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"If5u9w-Vz\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[]},\"gridPos\":{\"h\":5,\"w\":6,\"x\":0,\"y\":0},\"id\":2,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"auto\",\"orientation\":\"auto\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"\",\"values\":false},\"textMode\":\"auto\"},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"cacheDurationSeconds\":0,\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"If5u9w-Vz\"},\"fields\":[{\"jsonPath\":\"$.data.commitCount\",\"name\":\"代码提交次数\"},{\"jsonPath\":\"$.data.branchCount\",\"language\":\"jsonpath\",\"name\":\"代码分支数\"}],\"method\":\"GET\",\"queryParams\":\"\",\"refId\":\"A\",\"urlPath\":\"/dashboard/getCommitCount?from=$__from\\u0026to=$__to\\u0026projectName=cna/app-manager/track-issues\"}],\"title\":\"代码库概览\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"If5u9w-Vz\"},\"gridPos\":{\"h\":8,\"w\":24,\"x\":0,\"y\":5},\"id\":4,\"options\":{\"followTheme\":false,\"getOption\":\"console.log(data);\\n\\nif(data.series[0].length ==0) {\\n  return;\\n}\\nconst buffer = data.series[0].fields[0].values.buffer[0];\\nconst obj = JSON.parse(buffer);\\nconsole.log(obj)\\nconst itemArr = obj.items;\\n      \\nconst result = {}\\nfor(let i =0;i\\u003c itemArr.length;i++) {\\n    result[itemArr[i].date] = itemArr[i].count;\\n}\\nlet today = new Date();\\n// 获取一年前的今天\\nvar date = new Date(today.getFullYear()-1+\'/\'+(today.getMonth()+1)+\'/\'+today.getDate()).getTime();\\nvar end = new Date().getTime();\\nfunction getFormatDate(timeStamp) {\\n    let d = new Date(timeStamp);\\n     let curr_date = d.getDate();\\n    let curr_month = d.getMonth() + 1; \\n    let curr_year = d.getFullYear();\\n    String(curr_month).length \\u003c 2 ? (curr_month = \\\"0\\\" + curr_month): curr_month;\\n    String(curr_date).length \\u003c 2 ? (curr_date = \\\"0\\\" + curr_date): curr_date;\\n    return curr_year + \\\"-\\\" + curr_month +\\\"-\\\"+ curr_date;\\n}\\nvar dayTime = 3600 * 24 * 1000; // 一天\\nvar mockData = [];\\nfor (var time = date; time \\u003c end; time += dayTime) {\\n  let _day = getFormatDate(time);\\n  let count = 0;\\n  if(result[_day]) {\\n    count = result[_day];\\n  }  \\n  mockData.push([\\n        _day,\\n        count\\n        ]);\\n}\\nconsole.log(mockData)\\nconst color1 = \'#ededed\'\\nconst color2 = \'#aad5f1\'\\nconst color3 = \'#7ea8c9\'\\nconst color4 = \'#527ba1\'\\nconst color5 = \'#254e77\'\\nreturn {\\n    title: {\\n        top: 30,\\n        left: \'center\',\\n        \\u003c!-- text: `某人${getFormatDate(date)}至${getFormatDate(end)}每天的工作量`\\n    },\\n    legend: {\\n        left: 25,\\n        bottom: 5,\\n        tooltip: {\\n            show: true,\\n            position: \'top\',\\n            formatter: (el) =\\u003e {\\n                return el.name;\\n            } \\n        },\\n        itemGap: -3,\\n        itemWidth: 15,\\n        itemHeight: 15,\\n        icon: \'rect\',\\n        formatter: () =\\u003e {\\n            return \'\';\\n        }\\n    },\\n    tooltip: {\\n        position: \'top\',\\n        formatter: function (p) {\\n            var format = echarts.format.formatTime(\'yyyy-MM-dd\', p.data[0]);\\n            // return format + \': \' + p.data[1];\\n            return `${p.data[1]} 个贡献\\u003cbr /\\u003e${echarts.format.formatTime(\'yyyy-MM-dd\', p.data[0])}`;\\n        }\\n    },\\n    visualMap: {\\n        type: \'piecewise\',\\n        show: false,\\n        pieces: [\\n        {min: 0, max: 0, label: \'0\', color: color1},\\n        {min: 1, max: 9, label: \'1-9\', color: color2},\\n        {min: 10, max: 19, label: \'0-19\', color: color3},\\n        {min: 20, max: 29, label: \'20-29\', color: color4},\\n        {min: 30, label: \'30+\', color: color5}\\n        ]\\n    },\\n    calendar: {\\n        top: 50,\\n        left: 30,\\n        right: 30,\\n        cellSize: 17,\\n        // 设置月份轴的样式\\n        monthLabel: {\\n            nameMap: \'cn\',\\n            borderWidth: 0\\n        },\\n        range: [date, end],\\n        // 设置日历格的样式\\n        itemStyle: {\\n            borderWidth: 2,\\n            borderColor: \'#fff\'\\n        },\\n        // 设置星期轴的样式\\n        dayLabel: {\\n          nameMap: \'cn\',\\n          firstDay: 1\\n      },\\n      yearLabel: {show: false},\\n        // 设置分隔线样式\\n        splitLine: {\\n            lineStyle: {\\n                color: \'#fff\',\\n                width: 1.4\\n            }\\n        }\\n    },\\n    series: [\\n    {\\n        name: \'没有贡献\',\\n        type: \'heatmap\',\\n        coordinateSystem: \'calendar\',\\n        data: mockData.filter(item=\\u003eitem[1]==0),\\n        itemStyle: {\\n            color: color1\\n        },\\n        emphasis: {\\n            itemStyle: {\\n                borderColor: \'#333\'\\n            }\\n        }\\n    },{\\n        name: \'1～9 贡献\',\\n        type: \'heatmap\',\\n        coordinateSystem: \'calendar\',\\n        data: mockData.filter(item=\\u003eitem[1]\\u003e=1 \\u0026\\u0026 item[1]\\u003c=9),\\n        itemStyle: {\\n            color: color2\\n        },\\n        emphasis: {\\n            itemStyle: {\\n                borderColor: \'#333\'\\n            }\\n        }\\n    },{\\n        name: \'10～19 贡献\',\\n        type: \'heatmap\',\\n        coordinateSystem: \'calendar\',\\n        data: mockData.filter(item=\\u003eitem[1]\\u003e=10 \\u0026\\u0026 item[1]\\u003c=19),\\n        itemStyle: {\\n            color: color3\\n        },\\n        emphasis: {\\n            itemStyle: {\\n                borderColor: \'#333\'\\n            }\\n        }\\n    },{\\n        name: \'20～29 贡献\',\\n        type: \'heatmap\',\\n        coordinateSystem: \'calendar\',\\n        data: mockData.filter(item=\\u003eitem[1]\\u003e=20\\u0026\\u0026 item[1]\\u003c=29),\\n        itemStyle: {\\n            color: color4\\n        },\\n        emphasis: {\\n            itemStyle: {\\n                borderColor: \'#333\'\\n            }\\n        }\\n    },{\\n        name: \'30+ 贡献\',\\n        type: \'heatmap\',\\n        coordinateSystem: \'calendar\',\\n        data: mockData.filter(item=\\u003eitem[1]\\u003e=30),\\n        itemStyle: {\\n            color: color5\\n        },\\n        emphasis: {\\n            itemStyle: {\\n                borderColor: \'#333\'\\n            }\\n        }\\n    }],\\n    textStyle: {\\n        fontSize: 12\\n    },\\n    backgroundColor: \'#fff\'\\n};\\n\"},\"targets\":[{\"cacheDurationSeconds\":0,\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"If5u9w-Vz\"},\"fields\":[{\"jsonPath\":\"$.data\"}],\"method\":\"GET\",\"queryParams\":\"\",\"refId\":\"A\",\"urlPath\":\"/dashboard/getCommitWorkLoads?username=$gitlabMemberName\\u0026projectName=$gitlabProjectName\\u0026from=$__from\\u0026to=$__to\"}],\"title\":\"代码提交工作量$gitlabProjectName\",\"type\":\"bilibala-echarts-panel\"},{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"If5u9w-Vz\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillO