itorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select round(avg(m.count),0) from (\\nselect count(1) as count from \\n(select * from issues where issues_type_id=98 and del_flag=0 and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\nand if(\\\"$userNames\\\" = \\\"\'all\'\\\", 1=1, assigned_ids regexp concat(\'(^|,)(\',replace(replace(\\\"$userIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\n and $__timeFilter(create_time) ) i left join issues_type_ext_pm_bug ext on i.id=ext.issues_id \\nleft join issues_status s on i.status_id = s.id\\nwhere \\nif(\\\"$projectName\\\" = \\\"\'all\'\\\", 1=1  ,ext.belong_to_project in($projectIds))\\nand if(\\\"$sprintName\\\" = \\\"\'all\'\\\", 1=1  ,ext.sprint in($sprintIds))\\nand if(\\\"$bugSolutionName\\\" = \\\"\'all\'\\\", 1=1  ,ext.bug_type in ($bugSolutionName))\\nand  if(\\\"$tagName\\\" =\\\"\'all\'\\\",1=1,i.id in(select issues_id from issues_tag where tag_ids in ($tagIds)))\\nand s.type in (\'2\',\'3\')\\nand real_start_time is not null and real_start_time != \'\'\\nand close_time is not null and close_time != \'\'\\ngroup by date_format(close_time, \'%Y%m%d\')\\n)m\\n\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"日均修复数\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false}},\"mappings\":[]},\"overrides\":[]},\"gridPos\":{\"h\":7,\"w\":8,\"x\":0,\"y\":4},\"id\":24,\"options\":{\"legend\":{\"displayMode\":\"list\",\"placement\":\"right\",\"showLegend\":true,\"values\":[\"percent\"]},\"pieType\":\"pie\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"/^数量$/\",\"values\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"desc\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \\nsubstring(\\\"$tagIdAndName\\\", locate(\',\', \\\"$tagIdAndName\\\",locate(concat(\\\"\'\\\", tag_ids,\\\",\\\"),\\\"$tagIdAndName\\\"))+1,locate(\\\"\'\\\",\\\"$tagIdAndName\\\",locate(\\\",\\\", \\\"$tagIdAndName\\\",locate(concat(\\\"\'\\\", tag_ids,\\\",\\\"),\\\"$tagIdAndName\\\"))+1) - locate(\',\', \\\"$tagIdAndName\\\",locate(concat(\\\"\'\\\", tag_ids,\\\",\\\"),\\\"$tagIdAndName\\\"))-1) as name,\\n\\n\\ncount(1) as \'数量\'\\nfrom issues_type_ext_pm_bug b left join issues_tag t on b.issues_id=t.issues_id \\nwhere b.issues_id in(\\nselect id from issues where issues_type_id = 98 and del_flag=0 and  if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\nand if(\\\"$userNames\\\" = \\\"\'all\'\\\", 1=1, assigned_ids regexp concat(\'(^|,)(\',replace(replace(\\\"$userIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\nand $__timeFilter(create_time) \\n)\\n\\nand if(\\\"$projectName\\\" = \\\"\'all\'\\\", 1=1  ,belong_to_project in($projectIds))\\nand if(\\\"$sprintName\\\" = \\\"\'all\'\\\", 1=1  ,sprint in($sprintIds))\\nand if(\\\"$bugSolutionName\\\" = \\\"\'all\'\\\", 1=1  ,bug_type in ($bugSolutionName))\\nand if(\\\"$tagName\\\" =\\\"\'all\'\\\",1=1,t.tag_ids in ($tagIds))\\nand tag_ids is not null\\nand substring(\\\"$tagIdAndName\\\", locate(\',\', \\\"$tagIdAndName\\\",locate(concat(\\\"\'\\\", tag_ids,\\\",\\\"),\\\"$tagIdAndName\\\"))+1,locate(\\\"\'\\\",\\\"$tagIdAndName\\\",locate(\\\",\\\", \\\"$tagIdAndName\\\",locate(concat(\\\"\'\\\", tag_ids,\\\",\\\"),\\\"$tagIdAndName\\\"))+1) - locate(\',\', \\\"$tagIdAndName\\\",locate(concat(\\\"\'\\\", tag_ids,\\\",\\\"),\\\"$tagIdAndName\\\"))-1) \\n !=\'\'\\n\\ngroup by tag_ids\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":