arr2 = [];\\nconst arr3 = [];\\nconst arr4 = [];\\nconst arr5 = [];\\nArray.from(new Set(memberNameArr)).forEach(item =\\u003e {\\n  arr1.push(resultObj[item][\'未开始\']);\\n  arr2.push(resultObj[item][\'已确认\']);\\n  arr3.push(resultObj[item][\'已解决\']);\\n  arr4.push(resultObj[item][\'重新打开\']);\\n  arr5.push(resultObj[item][\'已关闭\']);\\n})\\n\\nreturn {\\n  tooltip: {\\n    trigger: \'axis\',\\n    axisPointer: {\\n      // Use axis to trigger tooltip\\n      type: \'shadow\' // \'shadow\' as default; can also be \'line\' or \'shadow\'\\n    }\\n  },\\n  legend: {},\\n  grid: {\\n    left: \'3%\',\\n    right: \'4%\',\\n    bottom: \'3%\',\\n    containLabel: true\\n  },\\n  xAxis: {\\n    type: \'value\'\\n  },\\n  yAxis: {\\n    type: \'category\',\\n    data: Array.from(new Set(memberNameArr))\\n  },\\n  series: [\\n    {\\n      name: \'未开始\',\\n      type: \'bar\',\\n      stack: \'total\',\\n      label: {\\n        show: true\\n      },\\n      emphasis: {\\n        focus: \'series\'\\n      },\\n      data: arr1\\n    },\\n    {\\n      name: \'已确认\',\\n      type: \'bar\',\\n      stack: \'total\',\\n      label: {\\n        show: true\\n      },\\n      emphasis: {\\n        focus: \'series\'\\n      },\\n      data: arr2\\n    },\\n    {\\n      name: \'已解决\',\\n      type: \'bar\',\\n      stack: \'total\',\\n      label: {\\n        show: true\\n      },\\n      emphasis: {\\n        focus: \'series\'\\n      },\\n      data: arr3\\n    },\\n    {\\n      name: \'重新打开\',\\n      type: \'bar\',\\n      stack: \'total\',\\n      label: {\\n        show: true\\n      },\\n      emphasis: {\\n        focus: \'series\'\\n      },\\n      data: arr4\\n    },\\n    {\\n      name: \'已关闭\',\\n      type: \'bar\',\\n      stack: \'total\',\\n      label: {\\n        show: true\\n      },\\n      emphasis: {\\n        focus: \'series\'\\n      },\\n      data: arr5\\n    }\\n  ]\\n};\"},\"targets\":[{\"cacheDurationSeconds\":0,\"datasource\":{\"type\":\"harmonyclou