le\\nWHERE\\n  $__timeFilter(middle.update_time)\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"devops_job_build_info\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"流水线构建平均时长\",\"transformations\":[],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"每日流水线根据状态分类\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"个数\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"bars\",\"fillOpacity\":100,\"gradientMode\":\"hue\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"normal\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"成功\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"NOT_EXECUTED\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"yellow\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"中止\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"purple\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"失败\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"red\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"