\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"流水线构建次数\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":100,\"gradientMode\":\"opacity\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"失败\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"red\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"成功\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":14},\"id\":14,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\',\\n  middle.status_name as \'metric\'\\nFROM ( \\nselect count(1) as count, i.update_time ,\\n(case \\n  when i.status=\'SUCCESS\' then \'成功\'\\n  when i.status=\'FAILURE\' then \'失败\'\\n  when i.status=\'FAILED\' then \'失败\'\\n  else i.status\\nend) as status_name\\nfrom devops_job_build_info i\\nwhere i.del_flag=0 and status in(\'SUCCESS\',\'FAILURE\',\'FAILED\') and job_id in(select id from devops_jenkins_job where del_flag=0 and tenant = if(\'$amp_organ_id\'=\'null\', tenant,\'$amp_organ_id\') and  if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')))\\ngroup by date_format(i.update_time,\'%Y%m%d\'), i.status\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"每日构建统计\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"gridPos\":{\"h\":12,\"w\":24,\"x\":0,\"y\":22},\"id\":20,\"options\":{\"followTheme\":false,\"getOption\":\"\\nfunction convertDate(ms) {\\n  ms = Number(ms);\\n  let date = new Date(ms);\\n  let year = date.getFullYear();\\n  let month = String(date.getMonth() + 1).padStart(2, \'0\');\\n  let day = String(date.getDate()).padStart(2, \'0\');\\n  return `${year}-${month}-${day}`;\\n}\\n\\n\\nconsole.log(data);\\n\\nif(data.series[0].length ==0) {\\n  return;\\n}\\nconst bufferA1 = data.series[0].fields[0].values.buffer;\\nconst bufferA2 = data.series[0].fields[1].values.buffer;\\nconst bufferB1 = data.series[1].fields[0].values.buffer;\\nconst bufferB2 = data.series[1].fields[1].values.buffer;\\nconst bufferB3 = data.series[1].fields[2].values.buffer;\\n\\n\\nconst dataMap = {};\\nfor(let i = 0;i\\u003cbufferA1.length;i++) {\\n  let date = bufferA1[i];\\n  let total = bufferA2[i];\\n  dataMap[date] = {\\n   total: total,\\n   successCount: 0,\\n   failedCount: 0\\n  };\\n}\\n\\nfor(let i = 0;i\\u003cbufferB1.length;i++) {\\n  let date = bufferB1[i];\\n  let metricCount = bufferB2[i];\\n  let metric = bufferB3[i];\\n  let dataObj = dataMap[date];\\n  if(!dataObj) {\\n    continue;\\n  }\\n  if(metric == \'成功\') {\\n    dataObj.successCount = metricCount;\\n  }else if(metric == \'失败\') {\\n    dataObj.failedCount = metricCount;\\n  }\\n}\\nconsole.log(dataMap);\\nconst dataMapKeys = Object.keys(dataMap);\\nconst dateArr = [];\\nconst totalArr = [];\\nconst successArr = [];\\nconst failedArr = [];\\nfor(let i=0;i\\u003cdataMapKeys.length;i++) {\\n  let date = dataMapKeys[i];\\n  let total = dataMap[date].total;\\n  let success = dataMap[date].successCount;\\n  let failed = dataMap[date].failedCount;\\n  dateArr.push(convertDate(date));\\n  totalArr.push(total);\\n  successArr.push(success);\\n  failedArr.push(failed);\\n}\\nconsole.log(dateArr)\\n\\nreturn {\\n    color: [\'#56A64B\', \'#E02F44\', \'#9CD3FB\'],\\n  tooltip: {\\n    trigger: \'axis\',\\n    axisPointer: {\\n      type: \'cross\',\\n      crossStyle: {\\n        color: \'#667C89\'\\n      }\\n    }\\n  },\\n  legend: {\\n    data: [\'成功\',\'失败\',\'构建次数\']\\n  },\\n  xAxis: [\\n    {\\n      type: \'category\',\\n      data: dateArr,\\n      axisPointer: {\\n        type: \'shadow\'\\n      }\\n    }\\n  ],\\n  yAxis: [\\n    {\\n      type: \'value\',\\n      name: \'成功\',\\n      min: 0,\\n      interval: 5,\\n      axisLabel: {\\n        formatter: \'{value} 次\'\\n      } \\n    },\\n    {\\n      type: \'value\',\\n      name: \'构建次数\',\\n      min: 0,\\n      interval: 5,\\n      splitLine: {show: false},\\n      axisLabel: {\\n        formatter: \'{value} 次\'\\n      }\\n    }\\n  ],\\n  series: [\\n    {\\n      name: \'成功\',\\n      type: \'bar\',\\n      tooltip: {\\n        valueFormatter: function (value) {\\n          return value + \' 次\';\\n        }\\n      },\\n      data: successArr\\n    },\\n    {\\n      name: \'失败\',\\n      type: \'bar\',\\n      tooltip: {\\n        valueFormatter: function (value) {\\n          return value + \' 行\';\\n        }\\n      },\\n      data: failedArr\\n    },\\n    {\\n      name: \'构建次数\',\\n      type: \'line\',\\n      yAxisIndex: 1,\\n      tooltip: {\\n        valueFormatter: function (value) {\\n          return value + \' 次\';\\n        }\\n      },\\n      data: totalArr\\n    }\\n  ]\\n}; \\n\\n\\n\\n\\n\\n\\n\"},\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"fields\":[{\"jsonPath\":\"\"}],\"format\":\"table\",\"method\":\"GET\",\"queryParams\":\"\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\'\\nFROM ( select count(1) as count, i.update_time \\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\n where i.del_flag=0 \\n and if(\'$amp_organ_id\'=\'null\', 1=1, j.tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, j.label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\ngroup by date_format(i.update_time,\'%Y%m%d\')\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\n  group by 1\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"urlPath\":\"\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"hide\":false,\"rawQuery\":true,\"rawSql\":\"\\nSELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\',\\n  middle.status_name as \'metric\'\\nFROM ( \\nselect count(1) as count, i.update_time ,\\n(case \\n  when i.status=\'SUCCESS\' then \'成功\'\\n  when i.status=\'FAILURE\' then \'失败\'\\n  when i.status=\'FAILED\' then \'失败\'\\n  else i.status\\nend) as status_name\\nfrom devops_job_build_info i\\nwhere i.del_flag=0 and status in(\'SUCCESS\',\'FAILURE\',\'FAILED\') and job_id in(select id from devops_jenkins_job where del_flag=0 and tenant = if(\'$amp_organ_id\'=\'null\', tenant,\'$amp_organ_id\') and  if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')))\\ngroup by date_format(i.update_time,\'%Y%m%d\'), i.status\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"B\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"代码提交情况\",\"type\":\"bilibala-echarts-panel\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\",\"seriesBy\":\"last\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisGridShow\":true,\"axisLabel\":\"分钟\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"bars\",\"fillOpacity\":100,\"gradientMode\":\"scheme\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"smooth\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"dashed\"}},\"decimals\":1,\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":5}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":34},\"id\":16,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.avg_time as \'时长\'\\nFROM ( \\n\\nselect _m.update_time,avg(duration) / 60 as avg_time\\nfrom (select i.update_time,(unix_timestamp(i.end_time) - unix_timestamp(i.start_time)) as duration\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\nwhere\\ni.update_time is not null and i.status=\'SUCCESS\' and i.del_flag=0 and j.tenant = if(\'$amp_organ_id\'=\'null\', j.tenant,\'$amp_organ_id\') and if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, j.label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\norder by update_time asc\\n) as _m\\ngroup by date_format(update_time,\'%Y%m%d\')\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nGROUP BY 1,2\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"devops_job_build_info\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"流水线构建平均时长\",\"transformations\":[],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":34},\"id\":18,\"options\":{\"content\":\"\\u003cdiv style=\\\"display: flex; margin-top: -0.8rem\\\"\\u003e\\n  \\u003cdiv style=\\\"width: 30px\\\"\\u003e\\n    {{#if (eq status \\\"SUCCESS\\\")}}\\n    \\u003cimg\\n      style=\\\"height: 1.2em; width: 1.2em; margin-left: 3px\\\"\\n      src=\\\"data:image/svg+xml;base64,\\\"\\n    /\\u003e\\n    {{else if (eq status \\\"FAILED\\\")}}\\n    \\u003cimg\\n      style=\\\"height: 1.45em; width: 1.45em; margin-left: 1px\\\"\\n      src=\\\"data:image/svg+xml;base64,\\\"\\n    /\\u003e\\n    {{else if (eq status \\\"IN_PROGRESS\\\")}}\\n    \\u003cimg\\n      style=\\\"height: 1.4em; width: 1.4em; margin-left: 3px\\\"\\n      src=\\\"data:image/png;base64,\\\"\\n    /\\u003e\\n    {{else}}\\n    \\u003cimg\\n      style=\\\"height: 1.5em; width: 1.5em; margin-left: 1px\\\"\\n      src=\\\"data:image/png;base64,\\\"\\n    /\\u003e\\n    {{/if}}\\n  \\u003c/div\\u003e\\n  \\u003cdiv style=\\\"width: calc(100% - 105px)\\\"\\u003e{{job_name}}\\u003c/div\\u003e\\n  \\u003cdiv style=\\\"width: 70px; color: rgba(0, 0, 0, 0.4);text-align: right\\\"\\u003e{{time_str}}\\u003c/div\\u003e\\n  \\u003cdiv style=\\\"margin-left: 20px\\\"\\u003e\\n    \\u003ca href=\\\"/efficiency/pipeline/{{id}}/detail/recent_run\\\" target=\\\"_blank\\\"\\u003e\\n      \\u003cimg\\n        style=\\\"height: 1em; width: 1em\\\"\\n        src=\\\"data:image/svg+xml;base64,\\\"\\n      /\\u003e\\n    \\u003c/a\\u003e\\n  \\u003c/div\\u003e\\n\\u003c/div\\u003e\",\"defaultContent\":\"The query didn\'t return any results.\",\"editor\":{\"format\":\"auto\",\"height\":200,\"language\":\"markdown\"},\"editors\":[],\"everyRow\":true,\"helpers\":\"\",\"styles\":\"\"},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \\n job.job_name,\\n status,\\ncase \\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 345600 THEN date_format(info.start_time, \'%m-%d\')\\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 86400 THEN concat( TIMESTAMPDIFF( DAY, info.start_time, NOW()) ,\'d ago\')\\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 3600 THEN concat(TIMESTAMPDIFF(HOUR,info.start_time,NOW()), \'h ago\')\\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 60 THEN concat(TIMESTAMPDIFF(MINUTE,info.start_time,NOW()), \'m ago\')\\n\\t\\tELSE \'刚刚\'\\nend as time_str,\\nstart_time,\\nconvert(job.id,char) as id\\n       \\n        \\nfrom devops_job_build_info info left join devops_jenkins_job job on job.id=info.job_id\\nwhere\\njob.job_name is not null and info.id in(select max(id) from devops_job_build_info group by job_id) and job.del_flag=0\\nand job.tenant = if(\'$amp_organ_id\'=\'null\', job.tenant,\'$amp_organ_id\') and if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, job.label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\ngroup by job_id\\norder by info.update_time desc\\nlimit 20\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"最近构建情况\",\"type\":\"harmonycloud-dynamictext-panel\"}],\"schemaVersion\":37,\"style\":\"dark\",\"tags\":[],\"templating\":{\"list\":[{\"allValue\":\"\'all\'\",\"current\":{\"selected\":true,\"text\":[\"All\"],\"value\":[\"$__all\"]},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select name from sys_tag where classification_id= 2428931245089341440 and if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope = 1)) and is_deleted=0\\nunion\\nselect \'\'\",\"description\":\"\",\"hide\":0,\"includeAll\":true,\"label\":\"标签\",\"multi\":true,\"name\":\"tagNames\",\"options\":[],\"query\":\"select name from sys_tag where classification_id= 2428931245089341440 and if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope = 1)) and is_deleted=0\\nunion\\nselect \'\'\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"},{\"current\":{\"selected\":true,\"text\":\"null\",\"value\":\"null\"},\"hide\":2,\"label\":\"amp_organ_id\",\"name\":\"amp_organ_id\",\"options\":[{\"selected\":true,\"text\":\"null\",\"value\":\"null\"}],\"query\":\"null\",\"skipUrlSync\":false,\"type\":\"textbox\"},{\"current\":{\"selected\":true,\"text\":[\"All\"],\"value\":[\"$__all\"]},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select concat(id,\'\') from sys_tag where classification_id = \'2428931245089341440\' and \\nif(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=2  ,name in ($tagNames)) and is_deleted=0\\nand  if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope=1))\\nunion\\nselect -9999999\",\"description\":\"如果tagName是all那么就不查出来\",\"hide\":2,\"includeAll\":true,\"multi\":true,\"name\":\"tagIds\",\"options\":[],\"query\":\"select concat(id,\'\') from sys_tag where classification_id = \'2428931245089341440\' and \\nif(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=2  ,name in ($tagNames)) and is_deleted=0\\nand  if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope=1))\\nunion\\nselect -9999999\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"}]},\"time\":{\"from\":\"now-30d\",\"to\":\"now\"},\"timepicker\":{},\"timezone\":\"\",\"title\":\"流水线维度\",\"uid\":\"sSo1HuISz\",\"version\":42,\"weekStart\":\"\"}');
INSERT INTO `dashboard_version` VALUES (380, 33, 42, 0, 43, '2023-11-28 16:09:38', 1, '', '{\"annotations\":{\"list\":[{\"builtIn\":1,\"datasource\":{\"type\":\"grafana\",\"uid\":\"-- Grafana --\"},\"enable\":true,\"hide\":true,\"iconColor\":\"rgba(0, 211, 255, 1)\",\"name\":\"Annotations \\u0026 Alerts\",\"target\":{\"limit\":100,\"matchAny\":false,\"tags\":[],\"type\":\"dashboard\"},\"type\":\"dashboard\"}]},\"description\":\"\",\"editable\":true,\"fiscalYearStartMonth\":0,\"graphTooltip\":0,\"id\":33,\"links\":[],\"liveNow\":false,\"panels\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[]},\"gridPos\":{\"h\":5,\"w\":12,\"x\":0,\"y\":0},\"id\":4,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"center\",\"orientation\":\"auto\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"\",\"values\":true},\"textMode\":\"auto\"},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select count(1) \\nfrom devops_jenkins_job job \\nwhere del_flag=0 and job_name is not null and  if(\'$amp_organ_id\'=\'null\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"流水线总数\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"最近一次构建成功的流水线 / 流水线总数\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":5,\"w\":12,\"x\":12,\"y\":0},\"id\":6,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"auto\",\"orientation\":\"auto\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"/^value$/\",\"values\":false},\"textMode\":\"auto\"},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select name, if(value is null, 0, value) value from (\\nselect \'流水线构建成功率\' as name, concat(ROUND((select count(1) from devops_job_build_info where status = \'SUCCESS\' and $__timeFilter(start_time) and id in(select max(id) from devops_job_build_info where  job_id in (select id from devops_jenkins_job where   if(\'$amp_organ_id\'=\'null\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')) and del_flag=0) group by job_id)) \\n/\\n (select count(1) from devops_job_build_info where  $__timeFilter(start_time) and id in(select max(id) from devops_job_build_info where  job_id in (select id from devops_jenkins_job where   if(\'$amp_organ_id\'=\'null\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')) and del_flag=0) group by job_id)) * 100,2),\'%\') as value) a\\n \\n \\n\\n \\n \\n \\n \\n \",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"流水线成功率\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"统计每日成功执行的流水线构建时长，单位：分钟\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\",\"seriesBy\":\"last\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisGridShow\":true,\"axisLabel\":\"分钟\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"bars\",\"fillOpacity\":100,\"gradientMode\":\"scheme\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"smooth\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"normal\"},\"thresholdsStyle\":{\"mode\":\"dashed\"}},\"decimals\":1,\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":5}]}},\"overrides\":[]},\"gridPos\":{\"h\":9,\"w\":12,\"x\":0,\"y\":5},\"id\":8,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.avg_time as \'时长\'\\nFROM ( \\n\\nselect _m.update_time,avg(duration) / 60 as avg_time\\nfrom (select i.update_time,(unix_timestamp(i.end_time) - unix_timestamp(i.start_time)) as duration\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\nwhere\\ni.update_time is not null and i.status=\'SUCCESS\' and i.del_flag=0\\nand job_id in(select id from devops_jenkins_job where del_flag=0 and if(\'$amp_organ_id\'=\'null\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')))\\norder by update_time asc\\n) as _m\\ngroup by date_format(update_time,\'%Y%m%d\')\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"devops_job_build_info\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"流水线构建平均时长\",\"transformations\":[],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"每日流水线根据状态分类\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"个数\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"bars\",\"fillOpacity\":100,\"gradientMode\":\"hue\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"normal\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"成功\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"NOT_EXECUTED\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"yellow\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"中止\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"purple\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"失败\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"red\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":9,\"w\":12,\"x\":12,\"y\":5},\"id\":10,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count,\\n  middle.status_name as \'metric\'\\nFROM (select count(1) as count, i.update_time,\\n(case \\n\\twhen i.status=\'SUCCESS\' then \'成功\'\\n\\twhen i.status=\'FAILURE\' then \'失败\'\\n\\twhen i.status=\'ABORTED\' then \'中止\'\\n\\telse i.status\\nend) as status_name\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\nwhere\\ni.update_time is not null \\nand i.del_flag=0 and i.job_id in (select id from devops_jenkins_job where if(\'$amp_organ_id\'=\'null\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')) and del_flag=0)\\ngroup by date_format(i.update_time,\'%Y%m%d\'),i.status\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\n  \\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"devops_job_build_info\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"流水线状态分布\",\"transformations\":[],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"每日流水线构建次数\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"构建次数\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":0,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"smooth\",\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":14},\"id\":12,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\'\\nFROM ( select count(1) as count, i.update_time \\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\n where i.del_flag=0 \\n and if(\'$amp_organ_id\'=\'null\', 1=1, j.tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, j.label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\ngroup by date_format(i.update_time,\'%Y%m%d\')\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"devops_job_build_info\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"流水线构建次数\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":100,\"gradientMode\":\"opacity\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"失败\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"red\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"成功\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":14},\"id\":14,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\',\\n  middle.status_name as \'metric\'\\nFROM ( \\nselect count(1) as count, i.update_time ,\\n(case \\n  when i.status=\'SUCCESS\' then \'成功\'\\n  when i.status=\'FAILURE\' then \'失败\'\\n  when i.status=\'FAILED\' then \'失败\'\\n  else i.status\\nend) as status_name\\nfrom devops_job_build_info i\\nwhere i.del_flag=0 and status in(\'SUCCESS\',\'FAILURE\',\'FAILED\') and job_id in(select id from devops_jenkins_job where del_flag=0 and tenant = if(\'$amp_organ_id\'=\'null\', tenant,\'$amp_organ_id\') and  if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')))\\ngroup by date_format(i.update_time,\'%Y%m%d\'), i.status\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"每日构建统计\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"gridPos\":{\"h\":13,\"w\":24,\"x\":0,\"y\":22},\"id\":20,\"options\":{\"followTheme\":false,\"getOption\":\"\\nfunction convertDate(ms) {\\n  ms = Number(ms);\\n  let date = new Date(ms);\\n  let year = date.getFullYear();\\n  let month = String(date.getMonth() + 1).padStart(2, \'0\');\\n  let day = String(date.getDate()).padStart(2, \'0\');\\n  return `${year}-${month}-${day}`;\\n}\\n\\n\\nconsole.log(data);\\n\\nif(data.series[0].length ==0) {\\n  return;\\n}\\nconst bufferA1 = data.series[0].fields[0].values.buffer;\\nconst bufferA2 = data.series[0].fields[1].values.buffer;\\nconst bufferB1 = data.series[1].fields[0].values.buffer;\\nconst bufferB2 = data.series[1].fields[1].values.buffer;\\nconst bufferB3 = data.series[1].fields[2].values.buffer;\\n\\n\\nconst dataMap = {};\\nfor(let i = 0;i\\u003cbufferA1.length;i++) {\\n  let date = bufferA1[i];\\n  let total = bufferA2[i];\\n  dataMap[date] = {\\n   total: total,\\n   successCount: 0,\\n   failedCount: 0\\n  };\\n}\\n\\nfor(let i = 0;i\\u003cbufferB1.length;i++) {\\n  let date = bufferB1[i];\\n  let metricCount = bufferB2[i];\\n  let metric = bufferB3[i];\\n  let dataObj = dataMap[date];\\n  if(!dataObj) {\\n    continue;\\n  }\\n  if(metric == \'成功\') {\\n    dataObj.successCount = metricCount;\\n  }else if(metric == \'失败\') {\\n    dataObj.failedCount = metricCount;\\n  }\\n}\\nconsole.log(dataMap);\\nconst dataMapKeys = Object.keys(dataMap);\\nconst dateArr = [];\\nconst totalArr = [];\\nconst successArr = [];\\nconst failedArr = [];\\nfor(let i=0;i\\u003cdataMapKeys.length;i++) {\\n  let date = dataMapKeys[i];\\n  let total = dataMap[date].total;\\n  let success = dataMap[date].successCount;\\n  let failed = dataMap[date].failedCount;\\n  dateArr.push(convertDate(date));\\n  totalArr.push(total);\\n  successArr.push(success);\\n  failedArr.push(failed);\\n}\\nconsole.log(dateArr)\\n\\nreturn {\\n    color: [\'#56A64B\', \'#E02F44\', \'#6CA9F5\'],\\n  tooltip: {\\n    trigger: \'axis\',\\n    axisPointer: {\\n      type: \'cross\',\\n      crossStyle: {\\n        color: \'#667C89\'\\n      }\\n    }\\n  },\\n  legend: {\\n    data: [\'成功\',\'失败\',\'构建次数\']\\n  },\\n  xAxis: [\\n    {\\n      type: \'category\',\\n      data: dateArr,\\n      axisPointer: {\\n        type: \'shadow\'\\n      }\\n    }\\n  ],\\n  yAxis: [\\n    {\\n      type: \'value\',\\n      name: \'成功\',\\n      min: 0,\\n      interval: 5,\\n      axisLabel: {\\n        formatter: \'{value} 次\'\\n      } \\n    },\\n    {\\n      type: \'value\',\\n      name: \'构建次数\',\\n      min: 0,\\n      interval: 5,\\n      splitLine: {show: false},\\n      axisLabel: {\\n        formatter: \'{value} 次\'\\n      }\\n    }\\n  ],\\n  series: [\\n    {\\n      name: \'成功\',\\n      type: \'bar\',\\n      tooltip: {\\n        valueFormatter: function (value) {\\n          return value + \' 次\';\\n        }\\n      },\\n      data: successArr\\n    },\\n    {\\n      name: \'失败\',\\n      type: \'bar\',\\n      tooltip: {\\n        valueFormatter: function (value) {\\n          return value + \' 行\';\\n        }\\n      },\\n      data: failedArr\\n    },\\n    {\\n      name: \'构建次数\',\\n      type: \'line\',\\n      yAxisIndex: 1,\\n      tooltip: {\\n        valueFormatter: function (value) {\\n          return value + \' 次\';\\n        }\\n      },\\n      data: totalArr\\n    }\\n  ]\\n}; \\n\\n\\n\\n\\n\\n\\n\"},\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"fields\":[{\"jsonPath\":\"\"}],\"format\":\"table\",\"method\":\"GET\",\"queryParams\":\"\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\'\\nFROM ( select count(1) as count, i.update_time \\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\n where i.del_flag=0 \\n and if(\'$amp_organ_id\'=\'null\', 1=1, j.tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, j.label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\ngroup by date_format(i.update_time,\'%Y%m%d\')\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\n  group by 1\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"urlPath\":\"\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"hide\":false,\"rawQuery\":true,\"rawSql\":\"\\nSELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\',\\n  middle.status_name as \'metric\'\\nFROM ( \\nselect count(1) as count, i.update_time ,\\n(case \\n  when i.status=\'SUCCESS\' then \'成功\'\\n  when i.status=\'FAILURE\' then \'失败\'\\n  when i.status=\'FAILED\' then \'失败\'\\n  else i.status\\nend) as status_name\\nfrom devops_job_build_info i\\nwhere i.del_flag=0 and status in(\'SUCCESS\',\'FAILURE\',\'FAILED\') and job_id in(select id from devops_jenkins_job where del_flag=0 and tenant = if(\'$amp_organ_id\'=\'null\', tenant,\'$amp_organ_id\') and  if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')))\\ngroup by date_format(i.update_time,\'%Y%m%d\'), i.status\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"B\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"代码提交情况\",\"type\":\"bilibala-echarts-panel\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\",\"seriesBy\":\"last\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisGridShow\":true,\"axisLabel\":\"分钟\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"bars\",\"fillOpacity\":100,\"gradientMode\":\"scheme\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"smooth\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"dashed\"}},\"decimals\":1,\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":5}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":35},\"id\":16,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.avg_time as \'时长\'\\nFROM ( \\n\\nselect _m.update_time,avg(duration) / 60 as avg_time\\nfrom (select i.update_time,(unix_timestamp(i.end_time) - unix_timestamp(i.start_time)) as duration\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\nwhere\\ni.update_time is not null and i.status=\'SUCCESS\' and i.del_flag=0 and j.tenant = if(\'$amp_organ_id\'=\'null\', j.tenant,\'$amp_organ_id\') and if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, j.label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\norder by update_time asc\\n) as _m\\ngroup by date_format(update_time,\'%Y%m%d\')\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nGROUP BY 1,2\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"devops_job_build_info\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"流水线构建平均时长\",\"transformations\":[],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":35},\"id\":18,\"options\":{\"content\":\"\\u003cdiv style=\\\"display: flex; margin-top: -0.8rem\\\"\\u003e\\n  \\u003cdiv style=\\\"width: 30px\\\"\\u003e\\n    {{#if (eq status \\\"SUCCESS\\\")}}\\n    \\u003cimg\\n      style=\\\"height: 1.2em; width: 1.2em; margin-left: 3px\\\"\\n      src=\\\"data:image/svg+xml;base64,\\\"\\n    /\\u003e\\n    {{else if (eq status \\\"FAILED\\\")}}\\n    \\u003cimg\\n      style=\\\"height: 1.45em; width: 1.45em; margin-left: 1px\\\"\\n      src=\\\"data:image/svg+xml;base64,\\\"\\n    /\\u003e\\n    {{else if (eq status \\\"IN_PROGRESS\\\")}}\\n    \\u003cimg\\n      style=\\\"height: 1.4em; width: 1.4em; margin-left: 3px\\\"\\n      src=\\\"data:image/png;base64,\\\"\\n    /\\u003e\\n    {{else}}\\n    \\u003cimg\\n      style=\\\"height: 1.5em; width: 1.5em; margin-left: 1px\\\"\\n      src=\\\"data:image/png;base64,\\\"\\n    /\\u003e\\n    {{/if}}\\n  \\u003c/div\\u003e\\n  \\u003cdiv style=\\\"width: calc(100% - 105px)\\\"\\u003e{{job_name}}\\u003c/div\\u003e\\n  \\u003cdiv style=\\\"width: 70px; color: rgba(0, 0, 0, 0.4);text-align: right\\\"\\u003e{{time_str}}\\u003c/div\\u003e\\n  \\u003cdiv style=\\\"margin-left: 20px\\\"\\u003e\\n    \\u003ca href=\\\"/efficiency/pipeline/{{id}}/detail/recent_run\\\" target=\\\"_blank\\\"\\u003e\\n      \\u003cimg\\n        style=\\\"height: 1em; width: 1em\\\"\\n        src=\\\"data:image/svg+xml;base64,\\\"\\n      /\\u003e\\n    \\u003c/a\\u003e\\n  \\u003c/div\\u003e\\n\\u003c/div\\u003e\",\"defaultContent\":\"The query didn\'t return any results.\",\"editor\":{\"format\":\"auto\",\"height\":200,\"language\":\"markdown\"},\"editors\":[],\"everyRow\":true,\"helpers\":\"\",\"styles\":\"\"},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \\n job.job_name,\\n status,\\ncase \\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 345600 THEN date_format(info.start_time, \'%m-%d\')\\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 86400 THEN concat( TIMESTAMPDIFF( DAY, info.start_time, NOW()) ,\'d ago\')\\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 3600 THEN concat(TIMESTAMPDIFF(HOUR,info.start_time,NOW()), \'h ago\')\\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 60 THEN concat(TIMESTAMPDIFF(MINUTE,info.start_time,NOW()), \'m ago\')\\n\\t\\tELSE \'刚刚\'\\nend as time_str,\\nstart_time,\\nconvert(job.id,char) as id\\n       \\n        \\nfrom devops_job_build_info info left join devops_jenkins_job job on job.id=info.job_id\\nwhere\\njob.job_name is not null and info.id in(select max(id) from devops_job_build_info group by job_id) and job.del_flag=0\\nand job.tenant = if(\'$amp_organ_id\'=\'null\', job.tenant,\'$amp_organ_id\') and if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, job.label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\ngroup by job_id\\norder by info.update_time desc\\nlimit 20\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"最近构建情况\",\"type\":\"harmonycloud-dynamictext-panel\"}],\"schemaVersion\":37,\"style\":\"dark\",\"tags\":[],\"templating\":{\"list\":[{\"allValue\":\"\'all\'\",\"current\":{\"selected\":true,\"text\":[\"All\"],\"value\":[\"$__all\"]},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select name from sys_tag where classification_id= 2428931245089341440 and if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope = 1)) and is_deleted=0\\nunion\\nselect \'\'\",\"description\":\"\",\"hide\":0,\"includeAll\":true,\"label\":\"标签\",\"multi\":true,\"name\":\"tagNames\",\"options\":[],\"query\":\"select name from sys_tag where classification_id= 2428931245089341440 and if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope = 1)) and is_deleted=0\\nunion\\nselect \'\'\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"},{\"current\":{\"selected\":true,\"text\":\"null\",\"value\":\"null\"},\"hide\":2,\"label\":\"amp_organ_id\",\"name\":\"amp_organ_id\",\"options\":[{\"selected\":true,\"text\":\"null\",\"value\":\"null\"}],\"query\":\"null\",\"skipUrlSync\":false,\"type\":\"textbox\"},{\"current\":{\"selected\":true,\"text\":[\"All\"],\"value\":[\"$__all\"]},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select concat(id,\'\') from sys_tag where classification_id = \'2428931245089341440\' and \\nif(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=2  ,name in ($tagNames)) and is_deleted=0\\nand  if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope=1))\\nunion\\nselect -9999999\",\"description\":\"如果tagName是all那么就不查出来\",\"hide\":2,\"includeAll\":true,\"multi\":true,\"name\":\"tagIds\",\"options\":[],\"query\":\"select concat(id,\'\') from sys_tag where classification_id = \'2428931245089341440\' and \\nif(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=2  ,name in ($tagNames)) and is_deleted=0\\nand  if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope=1))\\nunion\\nselect -9999999\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"}]},\"time\":{\"from\":\"now-30d\",\"to\":\"now\"},\"timepicker\":{},\"timezone\":\"\",\"title\":\"流水线维度\",\"uid\":\"sSo1HuISz\",\"version\":43,\"weekStart\":\"\"}');
