INSERT INTO `dashboard_version` VALUES (386, 33, 43, 0, 44, '2023-11-28 20:19:08', 1, '', '{\"annotations\":{\"list\":[{\"builtIn\":1,\"datasource\":{\"type\":\"grafana\",\"uid\":\"-- Grafana --\"},\"enable\":true,\"hide\":true,\"iconColor\":\"rgba(0, 211, 255, 1)\",\"name\":\"Annotations \\u0026 Alerts\",\"target\":{\"limit\":100,\"matchAny\":false,\"tags\":[],\"type\":\"dashboard\"},\"type\":\"dashboard\"}]},\"description\":\"\",\"editable\":true,\"fiscalYearStartMonth\":0,\"graphTooltip\":0,\"id\":33,\"links\":[],\"liveNow\":false,\"panels\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[]},\"gridPos\":{\"h\":5,\"w\":12,\"x\":0,\"y\":0},\"id\":4,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"center\",\"orientation\":\"auto\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"\",\"values\":true},\"textMode\":\"auto\"},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select count(1) \\nfrom devops_jenkins_job job \\nwhere del_flag=0 and job_name is not null and  if(\'$amp_organ_id\'=\'null\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"流水线总数\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"最近一次构建成功的流水线 / 流水线总数\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":5,\"w\":12,\"x\":12,\"y\":0},\"id\":6,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"auto\",\"orientation\":\"auto\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"/^value$/\",\"values\":false},\"textMode\":\"auto\"},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select name, if(value is null, 0, value) value from (\\nselect \'流水线构建成功率\' as name, concat(ROUND((select count(1) from devops_job_build_info where status = \'SUCCESS\' and $__timeFilter(start_time) and id in(select max(id) from devops_job_build_info where  job_id in (select id from devops_jenkins_job where   if(\'$amp_organ_id\'=\'null\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')) and del_flag=0) group by job_id)) \\n/\\n (select count(1) from devops_job_build_info where  $__timeFilter(start_time) and id in(select max(id) from devops_job_build_info where  job_id in (select id from devops_jenkins_job where   if(\'$amp_organ_id\'=\'null\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')) and del_flag=0) group by job_id)) * 100,2),\'%\') as value) a\\n \\n \\n\\n \\n \\n \\n \\n \",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"流水线成功率\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"统计每日成功执行的流水线构建时长，单位：分钟\",\"fieldConfig\":{\"defaults\":{\"color\":