ull\', 1=1, tenant_id =  \'$amp_organ_id\') \\nand if(\\\"$userNames\\\" = \\\"\'all\'\\\", 1=1, assigned_ids regexp concat(\'(^|,)(\',replace(replace(\\\"$userIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\n and status_id not in (3,4,7855) \\n and del_flag=0 \\n and $__timeFilter(create_time) \\ngroup by priority_id \",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"artifacts_repositories\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"timestamp\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"存量缺陷占比\",\"transformations\":[],\"type\":\"piechart\"},{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"CfuKN5mIk\"},\"description\":\"\",\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":11},\"id\":22,\"options\":{\"followTheme\":true,\"getOption\":\"console.log(data)\\nif(data.series.length == 0) {\\n  return;\\n}\\nconst memberNameArr = [];\\nconst classicNameArr = []\\nconst countArr = []\\n\\nconst json = data.series[0].first.buffer;\\nconst jsonData = JSON.parse(json);\\nconsole.log(jsonData)\\njsonData.forEach(item =\\u003e {\\n    classicNameArr.push(item.metric);\\nmemberNameArr.push(item.name);\\ncountArr.push(item.count)\\n  });\\n\\n\\n\\n\\n\\n\\n\\nconst result = [];\\nfor(let i =0;i\\u003c memberNameArr.length;i++) {\\n  result.push({\\n    memberName: memberNameArr[i],\\n    classicName: classicNameArr[i],\\n    count: countArr[i],\\n  });\\n}\\nconst resultObj = {};\\nresult.forEach(item =\\u003e{\\n  let obj = resultObj[item.memberName] || {\\n    \'未开始\': null,\\n    \'已确认\': null,\\n    \'已解决\': null,\\n    \'重新打开\': null,\\n    \'已关闭\': null\\n  };\\n  obj[item.classicName] = item.count;\\n  resultObj[item.memberName] = obj;\\n});\\nconsole.log(resultObj);\\n\\n\\nconst arr1 = [];\\nconst arr2 = [];\\nconst arr3 = [];\\nconst arr4 = [];\\nconst arr5 = [];\\nArray.from(new Set(memberNameArr)).forEach(item =\\u003e {\\n  arr1.push(resultObj[item][\'未开始\']);\\n  arr2.push(resultObj[item][\'已确认\']);\\n  arr3.push(resultObj[item][\'已解决\']);\\n  arr4.push(resultObj[item][\'重新打开\']);\\n  arr5.push(resultObj[item][\'已关闭\']);\\n})\\n\\nreturn {\\n  tooltip: {\\n    trigger: \'axis\',\\n    axisPointer: {\\n      // Use axis to trigger tooltip\\n      type: \'shadow\' // \'shadow\' as default; can also be \'line\' or \'shadow\'\\n    }\\n  },\\n  legend: {},\\n  grid: {\\n    left: \'3%\',\\n    right: \'4%\',\\n    bottom: \'3%\',\\n    containLabel: true\\n  },\\n  xAxis: {\\n    type: \'value\'\\n  },\\n  yAxis: {\\n    type: \'category\',\\n    data: Array.from(new Set(memberNameArr))\\n  },\\n  series: [\\n    {\\n      name: \'未开始\',\\n      type: \'bar\',\\n      stack: \'total\',\\n      label: {\\n        show: true\\n      },\\n      emphasis: {\\n        focus: \'series\'\\n      },\\n      data: arr1\\n    },\\n    {\\n      name: \'已确认\',\\n      type: \'bar\',\\n      stack: \'total\',\\n      label: {\\n        show: true\\n      },\\n      emphasis: {\\n        focus: \'series\'\\n      },\\n      data: arr2\\n    },\\n    {\\n      name: \'已解决\',\\n      type: \'bar\',\\n      stack: \'total\',\\n      label: {\\n        show: true\\n      },\\n      emphasis: {\\n        focus: \'series\'\\n      },\\n      data: arr3\\n    },\\n    {\\n      name: \'重新打开\',\\n      type: \'bar\',\\n      stack: \'total\',\\n      label: {\\n        show: true\\n      },\\n      emphasis: {\\n        focus: \'series\'\\n      },\\n      data: arr4\\n    },\\n    {\\n      name: \'已关闭\',\\n      type: \'bar\',\\n      stack: \'total\',\\n      label: {\\n        show: true\\n      },\\n      emphasis: {\\n        focus: \'series\'\\n      },\\n      data: arr5\\n    }\\n  ]\\n};\"},\"targets\":[{\"cacheDurationSeconds\":0,\"datasource\":{\"type\":\"harmonycloud-json-datasource