emberName] || {\\n    \'紧急\': null,\\n    \'高\': null,\\n    \'中\': null,\\n    \'低\': null,\\n  };\\n  obj[item.classicName] = item.count;\\n  resultObj[item.memberName] = obj;\\n});\\nconsole.log(resultObj);\\n\\n\\nconst jinji = [];\\nArray.from(new Set(memberNameArr)).forEach(item =\\u003e {\\n  jinji.push(resultObj[item][\'紧急\']);\\n})\\n\\nconst gao = [];\\nArray.from(new Set(memberNameArr)).forEach(item =\\u003e {\\n  gao.push(resultObj[item][\'高\']);\\n})\\n\\nconst zhong = [];\\nArray.from(new Set(memberNameArr)).forEach(item =\\u003e {\\n  zhong.push(resultObj[item][\'中\']);\\n})\\n\\nconst di = [];\\nArray.from(new Set(memberNameArr)).forEach(item =\\u003e {\\n  di.push(resultObj[item][\'低\']);\\n})\\n\\nreturn {\\n  tooltip: {\\n    trigger: \'axis\',\\n    axisPointer: {\\n      // Use axis to trigger tooltip\\n      type: \'shadow\' // \'shadow\' as default; can also be \'line\' or \'shadow\'\\n    }\\n  },\\n  legend: {},\\n  grid: {\\n    left: \'3%\',\\n    right: \'4%\',\\n    bottom: \'3%\',\\n    containLabel: true\\n  },\\n  xAxis: {\\n    type: \'value\'\\n  },\\n  yAxis: {\\n    type: \'category\',\\n    data: Array.from(new Set(memberNameArr))\\n  },\\n  series: [\\n    {\\n      name: \'紧急\',\\n      type: \'bar\',\\n      stack: \'total\',\\n      label: {\\n        show: true\\n      },\\n      emphasis: {\\n        focus: \'series\'\\n      },\\n      data: jinji\\n    },\\n    {\\n      name: \' 高\',\\n      type: \'bar\',\\n      stack: \'total\',\\n      label: {\\n        show: true\\n      },\\n      emphasis: {\\n        focus: \'series\'\\n      },\\n      data: gao\\n    },\\n    {\\n      name: \'中\',\\n      type: \'bar\',\\n      stack: \'total\',\\n      label: {\\n        show: true\\n      },\\n      emphasis: {\\n        focus: \'series\'\\n      },\\n      data: zhong\\n    },\\n    {\\n      name: \'低\',\\n      type: \'bar\',\\n      stack: \'total\',\\n      label: {\\n        show: true\\n      },\\n      emphasis: {\\