null\', 1=1, tenant_id =  \'$amp_organ_id\') \\n order by s.type,i.create_time\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"未开始和进行中的缺陷列表\",\"type\":\"table\"}],\"schemaVersion\":37,\"style\":\"dark\",\"tags\":[],\"templating\":{\"list\":[{\"current\":{\"selected\":false,\"text\":\"超级管理员\",\"value\":\"超级管理员\"},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select name from sys_user \\nwhere \\nis_deleted=0\\nand if(\'$amp_organ_id\'=\'null\', 1=1,id in(select user_id from sys_user_organization  where organ_id =\'$amp_organ_id\' and resource_id=0)) \\n\\n\\n\",\"hide\":0,\"includeAll\":false,\"label\":\"成员名称\",\"multi\":false,\"name\":\"username\",\"options\":[],\"query\":\"select name from sys_user \\nwhere \\nis_deleted=0\\nand if(\'$amp_organ_id\'=\'null\', 1=1,id in(select user_id from sys_user_organization  where organ_id =\'$amp_organ_id\' and resource_id=0)) \\n\\n\\n\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"},{\"current\":{\"selected\":false,\"text\":\"null\",\"value\":\"null\"},\"hide\":2,\"label\":\"amp_organ_id\",\"name\":\"amp_organ_id\",\"options\":[{\"selected\":false,\"text\":\"null\",\"value\":\"null\"}],\"query\":\"null\",\"skipUrlSync\":false,\"type\":\"textbox\"},{\"current\":{\"selected\":false,\"text\":\"1\",\"value\":\"1\"},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select concat(id,\'\') from sys_user where name = \'$username\' and is_deleted=0\",\"hide\":2,\"includeAll\":false,\"multi\":false,\"name\":\"userId\",\"options\":[],\"query\":\"select concat(id,\'\') from sys_user where name = \'$username\' and is_deleted=0\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"},{\"current\":{\"selected\":false,\"text\":\"admin\",\"value\":\"admin\"},\"datasource\":{\"type\":\"mysql\",