m issues where issues_type_id = 98 and del_flag=0 and  if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\nand if(\\\"$userNames\\\" = \\\"\'all\'\\\", 1=1, assigned_ids regexp concat(\'(^|,)(\',replace(replace(\\\"$userIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\nand $__timeFilter(create_time) \\n)\\nand if(\\\"$projectName\\\" = \\\"\'all\'\\\", 1=1  ,belong_to_project in($projectIds))\\nand if(\\\"$sprintName\\\" = \\\"\'all\'\\\", 1=1  ,sprint in($sprintIds))\\nand if(\\\"$bugSolutionName\\\" = \\\"\'all\'\\\", 1=1  ,bug_solution in ($bugSolutionName))\\nand if(\\\"$tagName\\\" =\\\"\'all\'\\\",1=1,t.tag_ids in ($tagIds))\\n\\nand bug_type is not null\\n\\ngroup by bug_type\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"缺陷类型统计图\",\"type\":\"piechart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"description\":\"当前时刻尚未完成的缺陷按严重程度、优先级、状态、阶段的分布占比\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false}},\"mappings\":[],\"min\":-3},\"overrides\":[]},\"gridPos\":{\"h\":7,\"w\":8,\"x\":16,\"y\":4},\"id\":10,\"options\":{\"displayLabels\":[],\"legend\":{\"displayMode\":\"list\",\"placement\":\"right\",\"showLegend\":true,\"values\":[\"percent\",\"value\"]},\"pieType\":\"donut\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"/^value$/\",\"values\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"\\n\\nselect (case priority_id\\nwhen 1 then\'低\'\\nwhen 2 then\'中\'\\nwhen 3 then\'高\'\\nwhen 4 then\'紧急\' end) as name,count(1) as value from issues where issues_type_id = 98 and  if(\'$amp_organ_id\'=\'