600 then \'耗时1-2周\'\\nwhen UNIX_TIMESTAMP(cast(i.close_time as datetime)) - UNIX_TIMESTAMP(cast(i.real_start_time as datetime)) \\u003c= 2419200 then \'耗时2-4周\'\\nelse \'耗时4周以上\' end as metric,count(1)\\n\\n\\n\\n from issues i left join issues_status s on i.status_id=s.id  where  i.issues_type_id=\'98\' and i.del_flag=0 and i.real_start_time is not null and i.close_time is not null and i.del_flag=0 and s.type in(2,3)\\n and $__timeFilter(i.create_time)\\n group by date_format(i.create_time, \'%Y%m%d\'),metric\\n\\n\\n\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"缺陷修复吞吐量\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"If5u9w-Vz\"},\"gridPos\":{\"h\":8,\"w\":24,\"x\":0,\"y\":21},\"id\":18,\"options\":{\"followTheme\":true,\"getOption\":\"\\nconsole.log(data);\\n\\nif(data.series[0].length ==0) {\\n  return;\\n}\\nconst buffer = data.series[0].fields[0].values.buffer[0];\\nconst obj = JSON.parse(buffer);\\nif(!obj) {\\n  return;\\n}\\nconsole.log(obj)\\nconst itemArr = obj.items;\\nconst date = [];\\nconst count = [];\\nconst lineCount= [];\\nitemArr.forEach(item =\\u003e {\\n  date.push(item.date);\\n   count.push(item.count);\\n   lineCount.push(item.lineCount);\\n});\\nreturn {\\n  tooltip: {\\n    trigger: \'axis\',\\n    axisPointer: {\\n      type: \'cross\',\\n      crossStyle: {\\n        color: \'#667C89\'\\n      }\\n    }\\n  },\\n  legend: {\\n    data: [\'代码行数\',\'代码提交次数\']\\n  },\\n  xAxis: [\\n    {\\n      type: \'category\',\\n      data: date,\\n      axisPointer: {\\n        type: \'shadow\'\\n      }\\n    }\\n  ],\\n  yAxis: [\\n    {\\n      type: \'value\',\\n      name: \'代码行数\',\\n      min: 0,\\n      interval: 200,\\n      axisLabel: {\\n        formatter: \'{value} 行\'\\n      }\\n    },\\n    {\\n      type: \'value\',\\n      name: \'代码提交次数\',\\n      min: 0,\\n      max: 20,\\n      splitLine: {show: false},\\n      axisLabel: {\\n        formatter: \'{value} 次\'\\n      }\\n    }\\n  ],\\n  series: [\\n    {\\n      name: \'代码行数\',\\n      type: \'bar\',\\n      tooltip: {\\n        valueFormatter: function (value) {\\n          return value + \' 行\';\\n        }\\n      },\\n      data: lineCount\\n    },\\n    {\\n      name: \'代码提交次数\',\\n      type: \'line\',\\n      yAxisIndex: 1,\\n      tooltip: {\\n        valueFormatter: function (value) {\\n          return value + \' 次\';\\n        }\\n      },\\n      data: count\\n    }\\n  ]\\n}; \"},\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"If5u9w-Vz\"},\"fields\":[{\"jsonPath\":\"$.data\"}],\"method\":\"GET\",\"queryParams\":\"\",\"refId\":\"A\",\"urlPath\":\"/dashboard/getCommitWorkLoads?username=$userLoginName\\u0026from=$__from\\u0026to=$__to\"}],\"title\":\"代码提交情况\",\"type\":\"bilibala-echarts-panel\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"auto\",\"displayMode\":\"auto\",\"inspect\":false},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":29},\"id\":7,\"options\":{\"footer\":{\"countRows\":false,\"fields\":\"\",\"reducer\":[\"sum\"],\"show\":false},\"showHeader\":true},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select  i.title as \'标题\', s.name as \'状态\', \\nsubstring(\\\"$userIdAndName\\\", locate(\',\', \\\"$userIdAndName\\\",locate(i.create_by,\\\"$userIdAndName\\\"))+1,locate(\\\"\'\\\",\\\"$userIdAndName\\\",locate(\\\",\\\", \\\"$userIdAndName\\\",locate(i.create_by,\\\"$userIdAndName\\\"))+1) - locate(\',\', \\\"$userIdAndName\\\",locate(i.create_by,\\\"$userIdAndName\\\"))-1)  as \'提出人\'\\n,i.end_date as \'计划完成日期\'\\nfrom issues i left join issues_status s on i.status_id=s.id\\n where  issues_type_id=\'96\' and s.type in (\'0\',\'1\')\\n and find_in_set(\'$userId\',i.assigned_ids)\\n and i.del_flag=0\\n and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\n order by s.type,i.create_time\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"未开始和进行中的需求列表\",\"type\":\"table\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"auto\",\"displayMode\":\"auto\",\"inspect\":false},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":29},\"id\":9,\"options\":{\"footer\":{\"countRows\":false,\"fields\":\"\",\"reducer\":[\"sum\"],\"show\":false},\"showHeader\":true},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select  i.title as \'标题\', s.name as \'状态\', \\nsubstring(\\\"$userIdAndName\\\", locate(\',\', \\\"$userIdAndName\\\",locate(i.create_by,\\\"$userIdAndName\\\"))+1,locate(\\\"\'\\\",\\\"$userIdAndName\\\",locate(\\\",\\\", \\\"$userIdAndName\\\",locate(i.create_by,\\\"$userIdAndName\\\"))+1) - locate(\',\', \\\"$userIdAndName\\\",locate(i.create_by,\\\"$userIdAndName\\\"))-1)  as \'提出人\',\\ni.end_date as \'计划完成日期\'\\nfrom issues i left join issues_status s on i.status_id=s.id\\n where  issues_type_id=\'98\' and s.type in (\'0\',\'1\')\\n and find_in_set(\'$userId\',i.assigned_ids)\\n and i.del_flag=0\\n and if(\'$amp_organ_id\'=\'n