},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"严重\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#AD0317\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"高危\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#f5252f\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"中危\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"orange\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"低位\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"yellow\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"低危\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"yellow\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":6,\"w\":5,\"x\":7,\"y\":29},\"id\":29,\"options\":{\"displayLabels\":[],\"legend\":{\"displayMode\":\"table\",\"placement\":\"right\",\"showLegend\":true,\"values\":[\"value\"]},\"pieType\":\"donut\",\"reduceOptions\":{\"calcs\":[],\"fields\":\"/^num$/\",\"values\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"J2rj6S-4z\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \\n(CASE\\n   WHEN severity = \\\"CRITICAL\\\" THEN \'严重\'\\n   WHEN severity = \\\"HIGH\\\" THEN \'高危\'\\n   WHEN severity = \\\"MEDIUM\\\" THEN \'中危\'\\n   WHEN severity = \\\"LOW\\\" THEN \'低危\'\\n   WHEN severity = \\\"可信\\\" THEN \'可信\'\\n\\n   end) as s,\\n   num\\n  from (\\nSELECT\\n        (CASE\\n        WHEN LEAK_SEVERITY_V3 = \\\"CRITICAL\\\" THEN \\\"CRITICAL\\\"\\n        WHEN LEAK_SEVERITY_V3 = \\\"HIGH\\\" THEN \\\"HIGH\\\"\\n        WHEN LEAK_SEVERITY_V3 = \\\"MEDIUM\\\" THEN \\\"MEDIUM\\\"\\n        ELSE \\\"LOW\\\"\\n        END) AS severity,\\n        COUNT(*) AS num\\n        FROM `devops_leak`\\n        WHERE\\n        ID IN (SELECT DISTINCT 