[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select * from\\n(\\nselect count(1) as \\\"今日\\\"\\nfrom devops_job_build_info\\nwhere \\nDATE_FORMAT(update_time,\'%Y%m%d\') = DATE_FORMAT(now(),\'%Y%m%d\') and job_id in(select id from devops_jenkins_job where del_flag=0 and tenant = if(\'$amp_organ_id\'=\'null\', tenant,\'$amp_organ_id\'))) m3,\\n(\\nselect count(1) as \\\"7天内\\\"\\nfrom devops_job_build_info\\nwhere \\nupdate_time between ( SELECT now( ) - INTERVAL 7 day )  AND (SELECT now()) and job_id in(select id from devops_jenkins_job where del_flag=0 and tenant = if(\'$amp_organ_id\'=\'null\', tenant,\'$amp_organ_id\'))) m2,\\n(\\nselect count(1) as \\\"14天内\\\"\\nfrom devops_job_build_info\\nwhere \\nupdate_time between ( SELECT now( ) - INTERVAL 14 day )  AND (SELECT now()) and job_id in(select id from devops_jenkins_job where del_flag=0 and tenant = if(\'$amp_organ_id\'=\'null\', tenant,\'$amp_organ_id\'))) m1\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"流水线构建情况\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false}},\"mappings\":[]},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"延期项目\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"dark-red\",\"mode\":\"fixed\"}}]},{\"__systemRef\":\"hideSeriesFrom\",\"matcher\":{\"id\":\"byNames\",\"options\":{\"mode\":\"exclude\",\"names\":[\"count\"],\"prefix\":\"All except:\",\"readOnly\":true}},\"properties\":[{\"id\":\"custom.hideFrom\",\"value\":{\"legend\":false,\"tooltip\":false,\"viz\":true}}]}]},\"gridPos\":{\"h\":7,\"w\":7,\"x\":0,\"y\":3},\"id\":9,\"options\":{\"legend\":{\"displayMode\":\"list\",\"placement\":\"right\",\"showLegend\":true,\"values\":[\"value\"]},\"pieType\":\"pie\",\"reduceOptions\":{\"calcs\":[],\"fields\":\"\",\"values\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \'延期项目\' as name,\\ncount(1) as count\\nfrom project\\nwhere del_flag=0 and end_time is not null and end_time \\u003c now() and status in(1,2) and tenant_id = if(\'$amp_organ_id\'=\'null\', tenant_id,\'$amp_organ_id\')\\nunion\\nselect \'进行中项目\' as name,\\ncount(1) as count\\nfrom project\\nwhere del_flag=0 and status=\'1\' and (end_time is null or end_time \\u003e= now()) and tenant_id = if(\'$amp_organ_id\'=\'null\', tenant_id,\'$amp_organ_id\')\\nunion\\nselect \'未开始项目\' as name,\\ncount(1) as count\\nfrom project\\nwhere del_flag=0 and status=\'2\' and (end_time is null or end_time \\u003e= now()) and tenant_id = if(\'$amp_organ_id\'=\'null\', tenant_id,\'$amp_organ_id\')\\nunion\\nselect \'已完成项目\' as name,\\ncount(1) as count\\nfrom project\\nwhere del_flag=0 and status=3 and tenant_id = if(\'$amp_organ_id\'=\'null\', tenant_id,\'$amp_organ_id\')\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"项目状态\",\"type\":\"piechart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":100,\"gradientMode\":\"opacity\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"失败\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"red\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"成功\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":6,\"w\":7,\"x\":17,\"y\":4},\"id\":17,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\',\\n  middle.status_name as \'metric\'\\nFROM ( \\nselect count(1) as count, i.update_time ,\\n(case \\n  when i.status=\'SUCCESS\' then \'成功\'\\n  when i.status=\'FAILED\' then \'失败\'\\n  when i.status=\'ABORTED\' then \'中止\'\\n  else i.status\\nend) as status_name\\nfrom devops_job_build_info i\\nwhere i.del_flag=0 and status in(\'SUCCESS\',\'FAILED\') and job_id in(select id from devops_jenkins_job where del_flag=0 and tenant = if(\'$amp_organ_id\'=\'null\', tenant,\'$amp_organ_id\'))\\ngroup by date_format(i.update_time,\'%Y%m%d\'), i.status\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nGROUP BY 1,2\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"每日构建统计\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"If5u9w-Vz\"},\"fieldConfig