erty\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"代码仓库质量通过率\",\"transformations\":[],\"type\":\"gauge\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[]},\"gridPos\":{\"h\":4,\"w\":7,\"x\":0,\"y\":31},\"id\":36,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"center\",\"orientation\":\"vertical\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"\",\"values\":true},\"textMode\":\"auto\"},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select * from\\n(\\nselect count(1) as \\\"总数\\\"\\nfrom issues\\nwhere issues_type_id=98 and del_flag=0 and tenant_id = if(\'$amp_organ_id\'=\'null\', tenant_id,\'$amp_organ_id\')) m3,\\n(\\nselect count(1) as \\\"已修复\\\"\\nfrom issues\\nwhere issues_type_id=98 and status_id in(7855,4) and del_flag=0\\n and tenant_id = if(\'$amp_organ_id\'=\'null\', tenant_id,\'$amp_organ_id\') ) m2,\\n(\\nselect count(1) as \\\"未修复\\\"\\nfrom issues \\nwhere issues_type_id=98 and status_id not in(7855,4) and del_flag=0 and tenant_id = if(\'$amp_organ_id\'=\'null\', tenant_id,\'$amp_organ_id\')) m1\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"缺陷总数统计\",\"type\":\"stat\"}],\"refresh\":false,\"schemaVersion\":37,\"style\":\"dark\",\"tags\":[],\"templating\":{\"list\":[{\"current\":{\"selected\":false,\"text\":\"3267246491214659584\",\"value\":\"3267246491214659584\"},\"description\":\"默认为null，如果为null则不做租户隔离\",\"hide\":2,\"label\":\"amp_organ_id\",\"name\":\"amp_organ_id\",\"options\":[{\"selected\":false,\"text\":\"3267246491