"linear\"},\"showPoints\":\"auto\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"失败\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"red\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"成功\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":6,\"w\":7,\"x\":17,\"y\":4},\"id\":17,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\',\\n  middle.status_name as \'metric\'\\nFROM ( \\nselect count(1) as count, i.update_time ,\\n(case \\n  when i.status=\'SUCCESS\' then \'成功\'\\n  when i.status=\'FAILED\' then \'失败\'\\n  when i.status=\'ABORTED\' then \'中止\'\\n  else i.status\\nend) as status_name\\nfrom devops_job_build_info i\\nwhere i.del_flag=0 and status in(\'SUCCESS\',\'FAILED\') and job_id in(select id from devops_jenkins_job where del_flag=0  and if(\\\"$amp_organ_name\\\" = \'all\', 1=1, tenant in($amp_organ_id)))\\ngroup by date_format(i.update_time,\'%Y%m%d\'), i.status\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nGROUP BY 1,2\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"每日构建统计\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"