\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select * from\\n(\\nselect count(1) as \\\"今日\\\"\\nfrom devops_job_build_info\\nwhere \\nDATE_FORMAT(update_time,\'%Y%m%d\') = DATE_FORMAT(now(),\'%Y%m%d\') and job_id in(select id from devops_jenkins_job where del_flag=0 and if(\\\"$amp_organ_name\\\" = \'all\', 1=1, tenant in($amp_organ_id)))) m3,\\n(\\nselect count(1) as \\\"7天内\\\"\\nfrom devops_job_build_info\\nwhere \\nupdate_time between ( SELECT now( ) - INTERVAL 7 day )  AND (SELECT now()) and job_id in(select id from devops_jenkins_job where del_flag=0  and if(\\\"$amp_organ_name\\\" = \'all\', 1=1, tenant in($amp_organ_id)))) m2,\\n(\\nselect count(1) as \\\"14天内\\\"\\nfrom devops_job_build_info\\nwhere \\nupdate_time between ( SELECT now( ) - INTERVAL 14 day )  AND (SELECT now()) and job_id in(select id from devops_jenkins_job where del_flag=0  and if(\\\"$amp_organ_name\\\" = \'all\', 1=1, tenant in($amp_organ_id)))) m1\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"流水线构建情况\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false}},\"mappings\":[]},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"延期项目\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"dark-red\",\"mode\":\"fixed\"}}]},{\"__systemRef\":\"hideSeriesFrom\",\"matcher\":{\"id\":\"byNames\",\"options\":{\"mode\":\"exclude\",\"names\":[\"count\"],\"prefix\":\"All except:\",\"readOnly\":true}},\"properties\":[{\"id\":\"custom.hideFrom\",\"value\":{\"legend\":false,\"tooltip\":false,\"viz\":true}}]}]},\"gridPos\":{\"h\":7,\"w\":7,\"x\":0,\"y\":3},\"id\":9,\"options\":{\"