\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"延期处理\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"super-light-red\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":7,\"w\":7,\"x\":0,\"y\":16},\"id\":37,\"options\":{\"legend\":{\"displayMode\":\"list\",\"placement\":\"right\",\"showLegend\":true,\"values\":[\"value\"]},\"pieType\":\"pie\",\"reduceOptions\":{\"calcs\":[],\"fields\":\"\",\"values\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select  s.name, count(1) as count\\n\\nfrom issues i left join issues_status s on i.status_id = s.id\\nwhere \\ni.issues_type_id in (96,97,98) and\\ni.del_flag=0 and if(\\\"$amp_organ_name\\\" = \'all\', 1=1, tenant_id in($amp_organ_id))\\n\\ngroup by i.status_id\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"工作项状态统计\",\"type\":\"piechart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"gridPos\":{\"h\":19,\"w\":7,\"x\":17,\"y\":16},\"id\":31,\"options\":{\"content\":\"\\u003cdiv style=\\\"display: flex; margin-top: -0.8rem\\\"\\u003e\\n  \\u003cdiv style=\\\"width: 30px\\\"\\u003e\\n    {{#if (eq status \\\"SUCCESS\\\")}}\\n    \\u003cimg\\n      style=\\\"height: 1.2em; width: 1.2em; margin-left: 3px\\\"\\n      src=\\\"data:image/svg+xml;base64,\\\"\\n    /\\u003e\\n    {{else if (eq status \\\"FAILED\\\")}}\\n    \\u003cimg\\n      style=\\\"height: 1.45em; width: 1.45em; margin-left: 1px\\\"\\n      src=\\\"data:image/svg+xml;base64,\\\"\\n    /\\u003e\\n    {{else if (eq status \\\"IN_PROGRESS\\\")}}\\n    \\u003cimg\\n      style=\\\"height: 1.4em; width: 1.4em; margin-left: 3px\\\"\\n      src=\\\"data:image/png;base64,\\\"\\n    /\\u003e\\n    {{else}}\\n    \\u003cimg\\n      style=\\\"height: 1.5em; width: 1.5em; margin-left: 1px\\\"\\n      src=\\\"data:image/png;base64,\\\"\\n    /\\u003e\\n    {{/if}}\\n  \\u003c/div\\u003e\\n  \\u003cdiv style=\\\"width: calc(100% - 105px)\\\"\\u003e{{job_name}}\\u003c/div\\u003e\\n  \\u003cdiv style=\\\"width: 70px; color: rgba(0, 0, 0, 0.4);text-align: right\\\"\\u003e{{time_str}}\\u003c/div\\u003e\\n  \\u003cdiv style=\\\"margin-left: 20px\\\"\\u003e\\n    \\u003ca href=\\\"/efficiency/pipeline/{{id}}/detail/recent_run\\\" target=\\\"_blank\\\"\\u003e\\n      \\u003cimg\\n        style=\\\"height: 1em; width: 1em\\\"\\n        src=\\\"data:image/svg+xml;base64,\\\"\\n      /\\u003e\\n    \\u003c/a\\u003e\\n  \\u003c/div\\u003e\\n\\u003c/div\\u003e\",\"defaultContent\":\"The query didn\'t return any results.\",\"editor\":{\"format\":\"auto\",\"height\":200,\"language\":\"markdown\"},\"editors\":[],\"everyRow\":true,\"helpers\":\"\",\"styles\":\"\"},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \\n job.job_name,\\n status,\\ncase \\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 345600 THEN date_format(info.start_time, \'%m-%d\')\\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 86400 THEN concat( TIMESTAMPDIFF( DAY, info.start_time, NOW()) ,\'d ago\')\\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 3600 THEN concat(TIMESTAMPDIFF(HOUR,info.start_time,NOW()), \'h ago\')\\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 60 THEN concat(TIMESTAMPDIFF(MINUTE,info.start_time,NOW()), \'m ago\')\\n\\t\\tELSE \'刚刚\'\\nend as time_str,\\nstart_time,\\nconvert(job.id,char) as id\\n       \\n        \\nfrom devops_job_build_info info left join devops_jenkins_job job on job.id=info.job_id\\nwhere\\njob.job_name is not null and info.id in(select max(id) from devops_job_build_info group by job_id) and job.del_flag=0\\n and if(\\\"$amp_organ_name\\\" = \'all\', 1=1, job.tenant in($amp_organ_id))\\ngroup by job_id\\norder by info.update_time desc\\nlimit 20\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"最近构建情况\",\"type\":\"harmonycloud-dynamictext-panel\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[]},\"gridPos\":{\"h\":4,\"w\":10,\"x\":7,\"y\":19},\"id\":40,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"center\",\"orientation\":\"vertical\",\"reduceOptions\":{\"calcs\":[],\"fields\":\"\",\"values\":true},\"textMode\":\"auto\"},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"SELECT \'项目制品库\' as name, count(1) as count\\nFROM devops_repository \\nWHERE format = \'raw\' AND kind = 2 AND repository_type = \'hosted\' and if(\\\"$amp_organ_name\\\" = \'all\', 1=1, tenant_id in($amp_organ_id))\\nunion\\n\\n\\n\\nSELECT \'组件库\' as name, count(1) as count\\nFROM devops_repository \\nWHERE format != \'raw\' AND kind = 0 AND repository_type = \'hosted\' and if(\\\"$amp_organ_name\\\" = \'all\', 1=1, tenant_id in($amp_organ_id))\\n\\nunion\\n\\nSELECT \'公共依赖库\' as name, count(1) as count FROM devops_repository WHERE kind = 1 AND repository_type = \'group\' AND scope = 0  and if(\\\"$amp_organ_name\\\" = \'all\', 1=1, tenant_id in($amp_organ_id))\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"制品库统计\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"description\":\"所选时间区间内每日新增、修复以及存量(即尚未完成)缺陷的数量曲线\",\"gridPos\":{\"h\":8,\"w\":7,\"x\":0,\"y\":23},\"id\":33,\"options\":{\"followTheme\":false,\"getOption\":\"if(data.series.length == 0) {\\n  return;\\n}\\nfunction formatDate(date){\\n  var year = date.getFullYear();\\n  var month =(date.getMonth() + 1).toString();\\n  var day = (date.getDate()).toString();\\n  if (month.length == 1) {\\n    month = \\\"0\\\" + month;\\n  }\\n  if (day.length == 1) {\\n    day = \\\"0\\\" + day;\\n  }\\n  var dateTime = year + \\\"-\\\" + month + \\\"-\\\" + day;\\n  return dateTime;\\n}\\nconst timeArr = data.series[0].fields[0].values.buffer;\\nconst newCountArr = data.series[0].fields[1].values.buffer;\\nconst finishCountArr = data.series[0].fields[2].values.buffer;\\nconst remainCountArr = data.series[0].fields[3].values.buffer;\\nconst mockData = [];\\nfor(let i = 0;i\\u003ctimeArr.length;i++) {\\n  mockData.push({\\n    time: formatDate(new Date(timeArr[i])),\\n    new: newCountArr[i],\\n    fix: finishCountArr[i],\\n    stock: remainCountArr[i]\\n  })\\n}\\n\\n  const timeArray = mockData.map((item) =\\u003e item.time)\\n  const newArray = mockData.map((item) =\\u003e item.new)\\n  const fixArray = mockData.map((item) =\\u003e item.fix * -1)\\n  const stockArray = mockData.map((item) =\\u003e item.stock)\\n  const option = {\\n    color: [\'#FADF60\', \'#E27668\', \'#6BC07A\'],\\n    grid: {\\n      right: 0,\\n    },\\n    tooltip: {\\n      trigger: \'axis\',\\n      formatter: (params) =\\u003e {\\n        let res = `${params[0].name} \\u003cbr/\\u003e`\\n        for (const item of params) {\\n          res += `\\u003cspan style=\\\"background: ${\\n            item.color\\n          }; height:10px; width: 10px; border-radius: 50%;display: inline-block;margin-right:10px;margin-top: 5px\\\"\\u003e\\u003c/span\\u003e ${\\n            item.seriesName\\n          } ：${Math.abs(item.value)}\\u003cbr/\\u003e`\\n        }\\n        return res\\n      },\\n    },\\n    legend: {\\n      data: [\'存量\', \'新增\', \'修复\'],\\n      icon: \'circle\',\\n      itemHeight: 8,\\n      itemWidth: 8,\\n      right: 0,\\n    },\\n    xAxis: [\\n      {\\n        type: \'category\',\\n        data: timeArray,\\n        axisPointer: {\\n          type: \'shadow\',\\n        },\\n        axisTick: {\\n          show: false,\\n        },\\n        axisLine: {\\n          show: false,\\n        },\\n      },\\n    ],\\n    yAxis: [\\n      {\\n        type: \'value\',\\n        minInterval: 5,\\n        axisLabel: {\\n          formatter: (value) =\\u003e {\\n            return Math.abs(value)\\n          },\\n        },\\n      },\\n    ],\\n    series: [\\n      {\\n        name: \'存量\',\\n        type: \'line\',\\n        data: stockArray,\\n        smooth: true,\\n        areaStyle: {\\n          color: \'#FDFAEC\',\\n        },\\n        z: -1,\\n        symbol: \'none\',\\n      },\\n      {\\n        name: \'新增\',\\n        type: \'bar\',\\n        stack: \'stack\',\\n        data: newArray,\\n        barWidth: 20,\\n        itemStyle: {\\n          normal: {\\n            barBorderRadius: [5, 5, 0, 0],\\n          },\\n        },\\n      },\\n      {\\n        name: \'修复\',\\n        type: \'bar\',\\n        stack: \'stack\',\\n        data: fixArray,\\n        barWidth: 20,\\n        itemStyle: {\\n          normal: {\\n            barBorderRadius: [0, 0, 5, 5],\\n          },\\n        },\\n      },\\n    ],\\n  }\\n  echartsInstance.setOption(option)\"},\"pluginVersion\":\"8.4.4\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"hide\":false,\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"select \\n$__timeGroupAlias(i1.create_time,1d),\\ncount(1) as new_count,\\n(select count(1) from issues i2 where i2.del_flag=0 and i2.issues_type_id=98  and date_format(cast(i2.close_time as datetime), \'%Y%m%d\') = date_format(cast(i1.create_time as datetime), \'%Y%m%d\') and i2.status_id in (7855,4) and if(\\\"$amp_organ_name\\\" = \'all\', 1=1, i2.tenant_id in($amp_organ_id))) as finish_count,\\n\\n((select count(1) from issues i2 where if(\\\"$amp_organ_name\\\" = \'all\', 1=1, i2.tenant_id in($amp_organ_id)) and i2.del_flag=0 and i2.issues_type_id=98   and date_format(cast(i2.create_time as datetime), \'%Y%m%d\') \\u003c= date_format(cast(i1.create_time as datetime), \'%Y%m%d\')) - (select count(1) from issues i3 where i3.del_flag=0 and if(\\\"$amp_organ_name\\\" = \'all\', 1=1, i3.tenant_id in($amp_organ_id)) and i3.issues_type_id=98   and date_format(cast(i3.close_time as datetime), \'%Y%m%d\') \\u003c= date_format(cast(i1.create_time as datetime), \'%Y%m%d\') and i3.status_id in (7855,4))) as remain_count\\n\\n\\n\\n\\nfrom issues i1\\nwhere i1.del_flag = 0 and i1.issues_type_id=98 and if(\\\"$amp_organ_name\\\" = \'all\', 1=1, i1.tenant_id in($amp_organ_id))\\nand $__timeFilter(i1.create_time)\\ngroup by date_format(cast(i1.create_time as datetime), \'%Y%m%d\')\\n\\nORDER BY i1.create_time ASC\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"artifacts_repositories\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"timestamp\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"缺陷趋势\",\"transformations\":[],\"type\":\"bilibala-echarts-panel\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"left\",\"displayMode\":\"auto\",\"inspect\":false},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":6,\"w\":5,\"x\":7,\"y\":23},\"id\":27,\"options\":{\"footer\":{\"countRows\":false,\"enablePagination\":false,\"fields\":\"\",\"reducer\":[\"sum\"],\"show\":false},\"showHeader\":false},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \'代码覆盖率\' as name,avg(coverage) as count \\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \'all\', 1=1, t.tenant_id in($amp_organ_id))\\nunion\\n\\nselect \'代码重复率\' as name, avg(repetition) as count\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \'all\', 1=1, t.tenant_id in($amp_organ_id))\\n\\n\\nunion\\n\\nselect \'代码坏味道\' as name, avg(`code_smell`) as count\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \'all\', 1=1, t.tenant_id in($amp_organ_id))\\n\\n \\n union\\n select \'Bugs\' as name, avg(bug) as count \\n  from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \'all\', 1=1, t.tenant_id in($amp_organ_id))\\n\\n\\nunion\\n select \'代码得分\' as name, avg(score) as count \\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \'all\', 1=1, t.tenant_id in($amp_organ_id))\\n\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"代码扫描情况\",\"type\":\"table\"},{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"wT7CrQa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"left\",\"displayMode\":\"auto\",\"filterable\":false,\"inspect\":false},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"val\"},\"properties\":[{\"id\":\"mappings\",\"value\":[{\"options\":{\"BLOCKER\":{\"index\":0,\"text\":\"阻断\"},\"CRITICAL\":{\"index\":1,\"text\":\"严重\"},\"INFO\":{\"index\":4,\"text\":\"轻微\"},\"MAJOR\":{\"index\":2,\"text\":\"主要\"},\"MINOR\":{\"index\":3,\"text\":\"次要\"}},\"type\":\"value\"}]}]}]},\"gridPos\":{\"h\":6,\"w\":5,\"x\":12,\"y\":23},\"id\":24,\"options\":{\"footer\":{\"countRows\":false,\"enablePagination\":false,\"fields\":\"\",\"reducer\":[\"sum\"],\"show\":false},\"frameIndex\":1,\"showHeader\":false},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"wT7CrQa4k\"},\"fields\":[{\"jsonPath\":\"$.facets[0].values[*].val\"},{\"jsonPath\":\"$.facets[0].values[*].count\",\"language\":\"jsonpath\",\"name\":\"\"}],\"method\":\"GET\",\"queryParams\":\"\",\"refId\":\"A\",\"urlPath\":\"/api/issues/search?s=FILE_LINE\\u0026resolved=false\\u0026ps=1\\u0026facets=severities\\u0026additionalFields=_all\\u0026timeZone=Asia%2FShanghai\"}],\"title\":\"存量代码问题\",\"transformations\":[{\"id\":\"sortBy\",\"options\":{\"fields\":{},\"sort\":[{\"desc\":false,\"field\":\"val\"}]}}],\"type\":\"table\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"J2rj6S-4z\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false}},\"decimals\":0,\"mappings\":[],\"unit\":\"none\"},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"可信\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"严重\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#AD0317\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"高危\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#f5252f\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"中危\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"orange\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"低位\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"yellow\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"低危\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"yellow\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":6,\"w\":5,\"x\":7,\"y\":29},\"id\":29,\"options\":{\"displayLabels\":[],\"legend\":{\"displayMode\":\"table\",\"placement\":\"right\",\"showLegend\":true,\"values\":[\"value\"]},\"pieType\":\"donut\",\"reduceOptions\":{\"calcs\":[],\"fields\":\"/^num$/\",\"values\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"J2rj6S-4z\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \\n(CASE\\n   WHEN severity = \\\"CRITICAL\\\" THEN \'严重\'\\n   WHEN severity = \\\"HIGH\\\" THEN \'高危\'\\n   WHEN severity = \\\"MEDIUM\\\" THEN \'中危\'\\n   WHEN severity = \\\"LOW\\\" THEN \'低危\'\\n   WHEN severity = \\\"可信\\\" THEN \'可信\'\\n\\n   end) as s,\\n   num\\n  from (\\nSELECT\\n        (CASE\\n        WHEN LEAK_SEVERITY_V3 = \\\"CRITICAL\\\" THEN \\\"CRITICAL\\\"\\n        WHEN LEAK_SEVERITY_V3 = \\\"HIGH\\\" THEN \\\"HIGH\\\"\\n        WHEN LEAK_SEVERITY_V3 = \\\"MEDIUM\\\" THEN \\\"MEDIUM\\\"\\n        ELSE \\\"LOW\\\"\\n        END) AS severity,\\n        COUNT(*) AS num\\n        FROM `devops_leak`\\n        WHERE\\n        ID IN (SELECT DISTINCT LEAK_ID FROM `devops_leak_dp_relation` WHERE DP_DETAIL_ID IN (SELECT DP_DETAIL_ID FROM `devops_app_dp_relation` WHERE APP_HISTORY_ID in (select h.id\\nfrom devops_app app left join devops_app_scan_history h on app.id = h.app_id\\nwhere h.del_flag=0\\ngroup by h.app_id\\n)))\\n        GROUP BY severity) m\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"漏洞等级安全分布\",\"transformations\":[],\"type\":\"piechart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"max\":100,\"min\":0,\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"#ffb71f\",\"value\":null}]},\"unit\":\"percent\"},\"overrides\":[]},\"gridPos\":{\"h\":6,\"w\":5,\"x\":12,\"y\":29},\"id\":26,\"options\":{\"orientation\":\"auto\",\"reduceOptions\":{\"calcs\":[],\"fields\":\"\",\"values\":true},\"showThresholdLabels\":false,\"showThresholdMarkers\":false,\"text\":{}},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select ((select count(h.`vulnerability`)\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and h.`vulnerability` = 0 and if(\\\"$amp_organ_name\\\" = \'all\', 1=1, t.tenant_id in($amp_organ_id))\\n order by h.create_time desc) / (select count(h.`vulnerability`)\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \'all\', 1=1, t.tenant_id in($amp_organ_id))\\n order by h.create_time desc)) * 100\",\"refId\":\"A\"