"x\":0,\"y\":3},\"id\":9,\"options\":{\"legend\":{\"displayMode\":\"list\",\"placement\":\"right\",\"showLegend\":true,\"values\":[\"value\"]},\"pieType\":\"pie\",\"reduceOptions\":{\"calcs\":[],\"fields\":\"\",\"values\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \'延期项目\' as name,\\ncount(1) as count\\nfrom project\\nwhere del_flag=0 and end_time is not null and end_time \\u003c now() and status in(1,2)  and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant_id in($amp_organ_id))\\nunion\\nselect \'进行中项目\' as name,\\ncount(1) as count\\nfrom project\\nwhere del_flag=0 and status=\'1\' and (end_time is null or end_time \\u003e= now())  and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant_id in($amp_organ_id))\\nunion\\nselect \'未开始项目\' as name,\\ncount(1) as count\\nfrom project\\nwhere del_flag=0 and status=\'2\' and (end_time is null or end_time \\u003e= now())  and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant_id in($amp_organ_id))\\nunion\\nselect \'已完成项目\' as name,\\ncount(1) as count\\nfrom project\\nwhere del_flag=0 and status=3  and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant_id in($amp_organ_id))\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"项目状态\",\"type\":\"piechart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":100,\"gradientMode\":\"opacity\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"失败\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"red\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"成功\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":6,\"w\":7,\"x\":17,\"y\":4},\"id\":17,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\',\\n  middle.status_name as \'metric\'\\nFROM ( \\nselect count(1) as count, i.update_time ,\\n(case \\n  when i.status=\'SUCCESS\' then \'成功\'\\n  when i.status=\'FAILED\' then \'失败\'\\n  when i.status=\'ABORTED\' then \'中止\'\\n  else i.status\\nend) as status_name\\nfrom devops_job_build_info i\\nwhere i.del_flag=0 and status in(\'SUCCESS\',\'FAILED\') and job_id in(select id from devops_jenkins_job where del_flag=0  and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant in($amp_organ_id)))\\ngroup by date_format(i.update_time,\'%Y%m%d\'), i.status\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nGROUP BY 1,2\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"每日构建统计\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"If5u9w-Vz\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[]},\"gridPos\":{\"h\":4,\"w\":10,\"x\":7,\"y\":6},\"id\":13,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"center\",\"orientation\":\"vertical\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"/^count$/\",\"values\":true},\"textMode\":\"auto\"},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"If5u9w-Vz\"},\"fields\":[{\"jsonPath\":\"$.data[*].date\"},{\"jsonPath\":\"$.data[*].count\",\"language\":\"jsonpath\",\"name\":\"\",\"type\":\"string\"}],\"headers\":[[\"X-SCM-TOKEN\",\"SCM@2023\"]],\"method\":\"GET\",\"queryParams\":\"\",\"refId\":\"A\",\"urlPath\":\"/dashboard/commitCountRecent\"}],\"title\":\"代码提交统计\",\"transformations\":[],\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"description\":\"\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"工作项类型\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":50,\"gradientMode\":\"opacity\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"smooth\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":1,\"pointSize\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":6,\"w\":7,\"x\":0,\"y\":10},\"id\":35,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"timezones\":[\"Asia/Shanghai\"],\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[{\"params\":[\"1d\",\"none\"],\"type\":\"time\"}],\"hide\":false,\"metricColumn\":\"create_time\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.time,1d),\\n  middle.count,\\n  middle.name as metric\\nFROM (  select \\n case\\n \\twhen issues_type_id=96 then \'研发需求\'\\n \\twhen issues_type_id=97 then \'任务\'\\n \\twhen issues_type_id=98 then \'缺陷\'\\n \\tend as name,\\n count(1) as count, cast(close_time as datetime) as time\\nfrom issues\\nwhere issues_type_id in(96,97,98) and status_id = 3 and del_flag=0 and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant_id in($amp_organ_id)) and close_time is not null\\ngroup by date_format(cast(close_time as datetime), \'%Y%m%d\'),issues_type_id\\n) as middle\\nWHERE\\n  $__timeFilter(middle.time)\\nORDER BY $__timeGroup(middle.time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"},{\"params\":[\"avg\"],\"type\":\"aggregate\"},{\"params\":[\"id\"],\"type\":\"alias\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"issues\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"每日完成工作项情况\",\"transformations\":[],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"If5u9w-Vz\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[]},\"gridPos\":{\"h\":4,\"w\":10,\"x\":7,\"y\":10},\"id\":15,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"center\",\"orientation\":\"vertical\",\"reduceOptions\":{\"calcs\":[],\"fields\":\"/^count$/\",\"values\":true},\"textMode\":\"auto\"},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"If5u9w-Vz\"},\"fields\":[{\"jsonPath\":\"$.data[*].date\"},{\"jsonPath\":\"$.data[*].count\",\"language\":\"jsonpath\",\"name\":\"\",\"type\":\"string\"}],\"headers\":[[\"X-SCM-TOKEN\",\"SCM@2023\"]],\"method\":\"GET\",\"queryParams\":\"\",\"refId\":\"A\",\"urlPath\":\"/dashboard/authorCountRecent\"}],\"title\":\"贡献者统计\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\",\"seriesBy\":\"last\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisGridShow\":true,\"axisLabel\":\"分钟\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"bars\",\"fillOpacity\":100,\"gradientMode\":\"scheme\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"smooth\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"dashed\"}},\"decimals\":1,\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":5}]}},\"overrides\":[]},\"gridPos\":{\"h\":6,\"w\":7,\"x\":17,\"y\":10},\"id\":19,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.avg_time as \'时长\'\\nFROM ( \\n\\nselect _m.update_time,avg(duration) / 60 as avg_time\\nfrom (select i.update_time,(unix_timestamp(i.end_time) - unix_timestamp(i.start_time)) as duration\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\nwhere\\ni.update_time is not null and i.status=\'SUCCESS\' and i.del_flag=0  and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, j.tenant in($amp_organ_id))\\norder by update_time asc\\n) as _m\\ngroup by date_format(update_time,\'%Y%m%d\')\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nGROUP BY 1,2\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"devops_job_build_info\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"流水线构建平均时长\",\"transformations\":[],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":0,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":5,\"w\":10,\"x\":7,\"y\":14},\"id\":39,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.time,1d),\\n  middle.count as \'数量\'\\nFROM (select count(1) as count,p.create_time as time\\nfrom devops_product p\\nleft join devops_repository r on p.repo_id=r.id\\nwhere p.create_time is not null and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, r.tenant_id in($amp_organ_id))\\ngroup by date_format(p.create_time, \'%Y%m%d\')\\norder by p.create_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.time)\\nORDER BY $__timeGroup(middle.time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"每日新增制品数量\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false}},\"mappings\":[]},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"延期项目\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"dark-red\",\"mode\":\"fixed\"}}]},{\"__systemRef\":\"hideSeriesFrom\",\"matcher\":{\"id\":\"byNames\",\"options\":{\"mode\":\"exclude\",\"names\":[\"count\",\"未开始\"],\"prefix\":\"All except:\",\"readOnly\":true}},\"properties\":[{\"id\":\"custom.hideFrom\",\"value\":{\"legend\":false,\"tooltip\":false,\"viz\":true}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"关闭\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#24292e\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"未开始\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"light-blue\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"已完成\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"延期处理\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"super-light-red\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":7,\"w\":7,\"x\":0,\"y\":16},\"id\":37,\"options\":{\"legend\":{\"displayMode\":\"list\",\"placement\":\"right\",\"showLegend\":true,\"values\":[\"value\"]},\"pieType\":\"pie\",\"reduceOptions\":{\"calcs\":[],\"fields\":\"\",\"values\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select  s.name, count(1) as count\\n\\nfrom issues i left join issues_status s on i.status_id = s.id\\nwhere \\ni.issues_type_id in (96,97,98) and\\ni.del_flag=0 and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant_id in($amp_organ_id))\\n\\ngroup by i.status_id\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"工作项状态统计\",\"type\":\"piechart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"gridPos\":{\"h\":19,\"w\":7,\"x\":17,\"y\":16},\"id\":31,\"options\":{\"content\":\"\\u003cdiv style=\\\"display: flex; margin-top: -0.8rem\\\"\\u003e\\n  \\u003cdiv style=\\\"width: 30px\\\"\\u003e\\n    {{#if (eq status \\\"SUCCESS\\\")}}\\n    \\u003cimg\\n      style=\\\"height: 1.2em; width: 1.2em; margin-left: 3px\\\"\\n      src=\\\"data:image/svg+xml;base64,\\\"\\n    /\\u003e\\n    {{else if (eq status \\\"FAILED\\\")}}\\n    \\u003cimg\\n      style=\\\"height: 1.45em; width: 1.45em; margin-left: 1px\\\"\\n      src=\\\"data:image/svg+xml;base64,\\\"\\n    /\\u003e\\n    {{else if (eq status \\\"IN_PROGRESS\\\")}}\\n    \\u003cimg\\n      style=\\\"height: 1.4em; width: 1.4em; margin-left: 3px\\\"\\n      src=\\\"data:image/png;base64,\\\"\\n    /\\u003e\\n    {{else}}\\n    \\u003cimg\\n      style=\\\"height: 1.5em; width: 1.5em; margin-left: 1px\\\"\\n      src=\\\"data:image/png;base64,\\\"\\n    /\\u003e\\n    {{/if}}\\n  \\u003c/div\\u003e\\n  \\u003cdiv style=\\\"width: calc(100% - 105px)\\\"\\u003e{{job_name}}\\u003c/div\\u003e\\n  \\u003cdiv style=\\\"width: 70px; color: rgba(0, 0, 0, 0.4);text-align: right\\\"\\u003e{{time_str}}\\u003c/div\\u003e\\n  \\u003cdiv style=\\\"margin-left: 20px\\\"\\u003e\\n    \\u003ca href=\\\"/efficiency/pipeline/{{id}}/detail/recent_run\\\" target=\\\"_blank\\\"\\u003e\\n      \\u003cimg\\n        style=\\\"height: 1em; width: 1em\\\"\\n        src=\\\"data:image/svg+xml;base64,\\\"\\n      /\\u003e\\n    \\u003c/a\\u003e\\n  \\u003c/div\\u003e\\n\\u003c/div\\u003e\",\"defaultContent\":\"The query didn\'t return any results.\",\"editor\":{\"format\":\"auto\",\"height\":200,\"language\":\"markdown\"},\"editors\":[],\"everyRow\":true,\"helpers\":\"\",\"styles\":\"\"},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \\n job.job_name,\\n status,\\ncase \\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 345600 THEN date_format(info.start_time, \'%m-%d\')\\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 86400 THEN concat( TIMESTAMPDIFF( DAY, info.start_time, NOW()) ,\'d ago\')\\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 3600 THEN concat(TIMESTAMPDIFF(HOUR,info.start_time,NOW()), \'h ago\')\\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 60 THEN concat(TIMESTAMPDIFF(MINUTE,info.start_time,NOW()), \'m ago\')\\n\\t\\tELSE \'刚刚\'\\nend as time_str,\\nstart_time,\\nconvert(job.id,char) as id\\n       \\n        \\nfrom devops_job_build_info info left join devops_jenkins_job job on job.id=info.job_id\\nwhere\\njob.job_name is not null and info.id in(select max(id) from devops_job_build_info group by job_id) and job.del_flag=0\\n and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, job.tenant in($amp_organ_id))\\ngroup by job_id\\norder by info.update_time desc\\nlimit 20\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"最近构建情况\",\"type\":\"harmonycloud-dynamictext-panel\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[]},\"gridPos\":{\"h\":4,\"w\":10,\"x\":7,\"y\":19},\"id\":40,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"center\",\"orientation\":\"vertical\",\"reduceOptions\":{\"calcs\":[],\"fields\":\"\",\"values\":true},\"textMode\":\"auto\"},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"SELECT \'项目制品库\' as name, count(1) as count\\nFROM devops_repository \\nWHERE format = \'raw\' AND kind = 2 AND repository_type = \'hosted\' and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant_id in($amp_organ_id))\\nunion\\n\\n\\n\\nSELECT \'组件库\' as name, count(1) as count\\nFROM devops_repository \\nWHERE format != \'raw\' AND kind = 0 AND repository_type = \'hosted\' and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant_id in($amp_organ_id))\\n\\nunion\\n\\nSELECT \'公共依赖库\' as name, count(1) as count FROM devops_repository WHERE kind = 1 AND repository_type = \'group\' AND scope = 0  and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant_id in($amp_organ_id))\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"制品库统计\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"description\":\"所选时间区间内每日新增、修复以及存量(即尚未完成)缺陷的数量曲线\",\"gridPos\":{\"h\":8,\"w\":7,\"x\":0,\"y\":23},\"id\":33,\"options\":{\"followTheme\":false,\"getOption\":\"if(data.series.length == 0) {\\n  return;\\n}\\nfunction formatDate(date){\\n  var year = date.getFullYear();\\n  var month =(date.getMonth() + 1).toString();\\n  var day = (date.getDate()).toString();\\n  if (month.length == 1) {\\n    month = \\\"0\\\" + month;\\n  }\\n  if (day.length == 1) {\\n    day = \\\"0\\\" + day;\\n  }\\n  var dateTime = year + \\\"-\\\" + month + \\\"-\\\" + day;\\n  return dateTime;\\n}\\nconst timeArr = data.series[0].fields[0].values.buffer;\\nconst newCountArr = data.series[0].fields[1].values.buffer;\\nconst finishCountArr = data.series[0].fields[2].values.buffer;\\nconst remainCountArr = data.series[0].fields[3].values.buffer;\\nconst mockData = [];\\nfor(let i = 0;i\\u003ctimeArr.length;i++) {\\n  mockData.push({\\n    time: formatDate(new Date(timeArr[i])),\\n    new: newCountArr[i],\\n    fix: finishCountArr[i],\\n    stock: remainCountArr[i]\\n  })\\n}\\n\\n  const timeArray = mockData.map((item) =\\u003e item.time)\\n  const newArray = mockData.map((item) =\\u003e item.new)\\n  const fixArray = mockData.map((item) =\\u003e item.fix * -1)\\n  const stockArray = mockData.map((item) =\\u003e item.stock)\\n  const option = {\\n    color: [\'#FADF60\', \'#E27668\', \'#6BC07A\'],\\n    grid: {\\n      right: 0,\\n    },\\n    tooltip: {\\n      trigger: \'axis\',\\n      formatter: (params) =\\u003e {\\n        let res = `${params[0].name} \\u003cbr/\\u003e`\\n        for (const item of params) {\\n          res += `\\u003cspan style=\\\"background: ${\\n            item.color\\n          }; height:10px; width: 10px; border-radius: 50%;display: inline-block;margin-right:10px;margin-top: 5px\\\"\\u003e\\u003c/span\\u003e ${\\n            item.seriesName\\n          } ：${Math.abs(item.value)}\\u003cbr/\\u003e`\\n        }\\n        return res\\n      },\\n    },\\n    legend: {\\n      data: [\'存量\', \'新增\', \'修复\'],\\n      icon: \'circle\',\\n      itemHeight: 8,\\n      itemWidth: 8,\\n      right: 0,\\n    },\\n    xAxis: [\\n      {\\n        type: \'category\',\\n        data: timeArray,\\n        axisPointer: {\\n          type: \'shadow\',\\n        },\\n        axisTick: {\\n          show: false,\\n        },\\n        axisLine: {\\n          show: false,\\n        },\\n      },\\n    ],\\n    yAxis: [\\n      {\\n        type: \'value\',\\n        minInterval: 5,\\n        axisLabel: {\\n          formatter: (value) =\\u003e {\\n            return Math.abs(value)\\n          },\\n        },\\n      },\\n    ],\\n    series: [\\n      {\\n        name: \'存量\',\\n        type: \'line\',\\n        data: stockArray,\\n        smooth: true,\\n        areaStyle: {\\n          color: \'#FDFAEC\',\\n        },\\n        z: -1,\\n        symbol: \'none\',\\n      },\\n      {\\n        name: \'新增\',\\n        type: \'bar\',\\n        stack: \'stack\',\\n        data: newArray,\\n        barWidth: 20,\\n        itemStyle: {\\n          normal: {\\n            barBorderRadius: [5, 5, 0, 0],\\n          },\\n        },\\n      },\\n      {\\n        name: \'修复\',\\n        type: \'bar\',\\n        stack: \'stack\',\\n        data: fixArray,\\n        barWidth: 20,\\n        itemStyle: {\\n          normal: {\\n            barBorderRadius: [0, 0, 5, 5],\\n          },\\n        },\\n      },\\n    ],\\n  }\\n  echartsInstance.setOption(option)\"},\"pluginVersion\":\"8.4.4\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"hide\":false,\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"select \\n$__timeGroupAlias(i1.create_time,1d),\\ncount(1) as new_count,\\n(select count(1) from issues i2 where i2.del_flag=0 and i2.issues_type_id=98  and date_format(cast(i2.close_time as datetime), \'%Y%m%d\') = date_format(cast(i1.create_time as datetime), \'%Y%m%d\') and i2.status_id in (7855,4) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, i2.tenant_id in($amp_organ_id))) as finish_count,\\n\\n((select count(1) from issues i2 where if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, i2.tenant_id in($amp_organ_id)) and i2.del_flag=0 and i2.issues_type_id=98   and date_format(cast(i2.create_time as datetime), \'%Y%m%d\') \\u003c= date_format(cast(i1.create_time as datetime), \'%Y%m%d\')) - (select count(1) from issues i3 where i3.del_flag=0 and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, i3.tenant_id in($amp_organ_id)) and i3.issues_type_id=98   and date_format(cast(i3.close_time as datetime), \'%Y%m%d\') \\u003c= date_format(cast(i1.create_time as datetime), \'%Y%m%d\') and i3.status_id in (7855,4))) as remain_count\\n\\n\\n\\n\\nfrom issues i1\\nwhere i1.del_flag = 0 and i1.issues_type_id=98 and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, i1.tenant_id in($amp_organ_id))\\nand $__timeFilter(i1.create_time)\\ngroup by date_format(cast(i1.create_time as datetime), \'%Y%m%d\')\\n\\nORDER BY i1.create_time ASC\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"artifacts_repositories\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"timestamp\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"缺陷趋势\",\"transformations\":[],\"type\":\"bilibala-echarts-panel\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"left\",\"displayMode\