f(\'$amp_organ_id\'=\'null\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')) and del_flag=0)\\ngroup by date_format(i.update_time,\'%Y%m%d\'),i.status\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\n  \\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"devops_job_build_info\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"流水线状态分布\",\"transformations\":[],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"每日流水线构建次数\",\"fieldConfig\":{\"defaults\":{\"color\":{\"fixedColor\":\"#226ee7\",\"mode\":\"fixed\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"构建次数\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":25,\"gradientMode\":\"opacity\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineWidth\":2,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":20},\"id\":12,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\'\\nFROM ( select count(1) as count, i.update_time \\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\n where i.del_flag=0 \\n and if(\'$amp_organ_id\'=\'null\', 1=1, j.tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, j.label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\ngroup by date_format(i.update_time,\'%Y%m%d\')\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"devops_job_build_info\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"流水线构建次数\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":0,\"gradientMode\":\"opacity\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":7,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"never\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"失败\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#e15a33\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"成功\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#58b076\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":20},\"id\":14,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\',\\n  middle.status_name as \'metric\'\\nFROM ( \\nselect count(1) as count, i.update_time ,\\n(case \\n  when i.status=\'SUCCESS\' then \'成功\'\\n  when i.status=\'FAILURE\' then \'失败\'\\n  when i.status=\'FAILED\' then \'失败\'\\n  else i.status\\nend) as status_name\\nfrom devops_job_build_info i\\nwhere i.del_flag=0 and status in(\'SUCCESS\',\'FAILURE\',\'FAILED\') and job_id in(select id from devops_jenkins_job where del_flag=0 and tenant = if(\'$amp_organ_id\'=\'null\', tenant,\'$amp_organ_id\') and  if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')))\\ngroup by date_format(i.update_time,\'%Y%m%d\'), i.status\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"每日构建统计\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"gridPos\":{\"h\":14,\"w\":12,\"x\":0,\"y\":28},\"id\":21,\"options\":{\"content\":\"\\n\\u003cdiv style=\\\"display: flex; margin-top: -0.8rem\\\"\\u003e\\n  \\u003cdiv style=\\\"width: 30px\\\"\\u003e\\n    {{#if (eq status \\\"SUCCESS\\\")}}\\n    \\u003cimg\\n      style=\\\"height: 1.2em; width: 1.2em; margin-left: 3px\\\"\\n      src=\\\"data:image/svg+xml;base64,\\\"\\n    /\\u003e\\n    {{else if (eq status \\\"FAILED\\\")}}\\n    \\u003cimg\\n      style=\\\"height: 1.45em; width: 1.45em; margin-left: 1px\\\"\\n      src=\\\"data:image/svg+xml;base64,\\\"\\n    /\\u003e\\n    {{else if (eq status \\\"FAILURE\\\")}}\\n    \\u003cimg\\n      style=\\\"height: 1.45em; width: 1.45em; margin-left: 1px\\\"\\n      src=\\\"data:image/svg+xml;base64,\\\"\\n    /\\u003e\\n    {{else if (eq status \\\"IN_PROGRESS\\\")}}\\n    \\u003cimg\\n      style=\\\"height: 1.4em; width: 1.4em; margin-left: 3px\\\"\\n      src=\\\"data:image/png;base64,\\\"\\n    /\\u003e\\n    {{else}}\\n    \\u003cimg\\n      style=\\\"height: 1.5em; width: 1.5em; margin-left: 1px\\\"\\n      src=\\\"data:image/png;base64,\\\"\\n    /\\u003e\\n    {{/if}}\\n  \\u003c/div\\u003e\\n  \\u003cdiv style=\\\"width: calc(100% - 105px)\\\"\\u003e{{job_name}}\\u003c/div\\u003e\\n  \\u003cdiv style=\\\"width: 70px; color: rgba(0, 0, 0, 0.4);text-align: right\\\"\\u003e{{time_str}}\\u003c/div\\u003e\\n  \\u003cdiv style=\\\"margin-left: 20px\\\"\\u003e\\n    \\u003ca href=\\\"/efficiency/pipeline/{{id}}/detail/recent_run\\\" target=\\\"_blank\\\"\\u003e\\n      \\u003cimg\\n        style=\\\"height: 1em; width: 1em\\\"\\n        src=\\\"data:image/svg+xml;base64,\\\"\\n      /\\u003e\\n    \\u003c/a\\u003e\\n  \\u003c/div\\u003e\\n\\u003c/div\\u003e\",\"defaultContent\":\"The query didn\'t return any results.\",\"editor\":{\"format\":\"auto\",\"height\":200,\"language\":\"markdown\"},\"editors\":[],\"everyRow\":true,\"helpers\":\"\",\"styles\":\"\"},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \\n job.job_name,\\n status,\\ncase \\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 345600 THEN date_format(info.start_time, \'%m-%d\')\\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 86400 THEN concat( TIMESTAMPDIFF( DAY, info.start_time, NOW()) ,\'d ago\')\\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 3600 THEN concat(TIMESTAMPDIFF(HOUR,info.start_time,NOW()), \'h ago\')\\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 60 THEN concat(TIMESTAMPDIFF(MINUTE,info.start_time,NOW()), \'m ago\')\\n\\t\\tELSE \'刚刚\'\\nend as time_str,\\nstart_time,\\nconvert(job.id,char) as id\\n       \\n        \\nfrom devops_job_build_info info left join devops_jenkins_job job on job.id=info.job_id\\nwhere\\njob.job_name is not null and info.id in(select max(id) from devops_job_build_info where status in (\'FAILED\',\'FAILURE\') group by job_id) and job.del_flag=0\\nand job.tenant = if(\'$amp_organ_id\'=\'null\', job.tenant,\'$amp_organ_id\') and if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, job.label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\ngroup by job_id\\norder by info.update_time desc\\nlimit 20\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"构建失败列表\",\"type\":\"harmonycloud-dynamictext-panel\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"gridPos\":{\"h\":14,\"w\":12,\"x\":12,\"y\":28},\"id\":18,\"options\":{\"content\":\"\\n\\u003cdiv style=\\\"display: flex; margin-top: -0.8rem\\\"\\u003e\\n  \\u003cdiv style=\\\"width: 30px\\\"\\u003e\\n    {{#if (eq status \\\"SUCCESS\\\")}}\\n    \\u003cimg\\n      style=\\\"height: 1.2em; width: 1.2em; margin-left: 3px\\\"\\n      src=\\\"data:image/svg+xml;base64,