\',replace(replace(\\\"$userIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\nand $__timeFilter(create_time) \\n) \\nand if(\\\"$projectName\\\" = \\\"\'all\'\\\", 1=1  ,belong_to_project in($projectIds))\\n\\n union\\n\\n select count(1) as value ,\'缺陷总数\' as name, \'#F34D1F\' as color from issues_type_ext_pm_bug where issues_id in (\\nselect id from issues where issues_type_id=\'98\' and del_flag=0 and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\nand if(\\\"$userNames\\\" = \\\"\'all\'\\\", 1=1, assigned_ids regexp concat(\'(^|,)(\',replace(replace(\\\"$userIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\nand $__timeFilter(create_time) \\n) \\nand if(\\\"$projectName\\\" = \\\"\'all\'\\\", 1=1  ,belong_to_project in($projectIds))\\nand if(\\\"$sprintName\\\" = \\\"\'all\'\\\", 1=1  ,sprint in($sprintIds))\\nand if(\\\"$bugSolutionName\\\" = \\\"\'all\'\\\", 1=1  ,bug_solution in ($bugSolutionName))\\nand  if(\\\"$tagName\\\" =\\\"\'all\'\\\",1=1,issues_id in(select issues_id from issues_tag where tag_ids in ($tagIds)))\\n\\n union\\n\\n select count(1),\'解决缺陷数\' as type, \'#F34D1F\' as color from issues_type_ext_pm_bug where issues_id in (\\nselect id from issues where issues_type_id=\'98\' and del_flag=0 and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\nand if(\\\"$userNames\\\" = \\\"\'all\'\\\", 1=1, assigned_ids regexp concat(\'(^|,)(\',replace(replace(\\\"$userIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\nand status_id in(\'7855\',\'4\')\\nand $__timeFilter(create_time) \\n) \\nand if(\\\"$projectName\\\" = \\\"\'all\'\\\", 1=1  ,belong_to_project in($projectIds))\\nand if(\\\"$sprintName\\\" = \\\"\'all\'\\\", 1=1  ,sprint in($sprintIds))\\nand if(\\\"$bugSolutionName\\\" = \\\"\'all\'\\\", 1=1  ,bug_type in ($bugSolutionName))\\nand  if(\\\"$tagName\\\" =\\\"\'all\'\\\",1=1,issues_id in(select issues_id from issues_tag where tag_ids in ($tagIds)))\\n\\n union\\n\\n select count(1), \'重新打开缺陷数\' as type, \'#F34D1F\' as color from issues_type_ext_pm_bug where issues_id in (\\nselect id from issues where issues_type_id=\'98\' and del_flag=0 and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\nand if(\\\"$userNames\\\" = \\\"\'all\'\\\", 1=1, assigned_ids regexp concat(\'(^|,)(\',replace(replace(\\\"$userIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\nand is_reopen = \'1\'\\nand $__timeFilter(create_time) \\n) \\nand if(\\\"$projectName\\\" = \\\"\'all\'\\\", 1=1  ,belong_to_project in($projectIds))\\nand if(\\\"$sprintName\\\" = \\\"\'all\'\\\", 1=1  ,sprint in($sprintIds))\\nand if(\\\"$bugSolutionName\\\" = \\\"\'all\'\\\", 1=1  ,bug_solution in ($bugSolutionName))\\nand  if(\\\"$tagName\\\" =\\\"\'all\'\\\",1=1,issues_id in(select issues_id from issues_tag where tag_ids in ($tagIds)))\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"测试现状概览\",\"type\":\"harmonycloud-dynamictext-panel\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"gridPos\":{\"h\":5,\"w\":10,\"x\":14,\"y\":0},\"id\":44,\"options\":{\"content\":\"\\u003cdiv class=\\\"flex justify-content\\\" style=\\\"color:#9D9D9D;width:100%;\\\"\\u003e\\n  {{#each data}}\\n\\n  \\u003cdiv style=\\\"text-align:center\\\"\\u003e\\n    \\u003cdiv\\u003e{{name}}\\u003c/div\\u003e\\n    \\u003cdiv\\u003e\\n      \\u003cspan style=\\\"font-size:60px;margin-right:5px;color:{{color}}\\\"\\u003e{{value}}\\u003c/span\\u003e\\u003cspan\\u003e{{unit}}\\u003c/span\\u003e\\n    \\u003c/div\\u003e\\n  \\u003c/div\\u003e\\n\\n  {{/each}}\\n\\u003c/div\\u003e\",\"defaultContent\":\"The query didn\'t return any results.\",\"editor\":{\"format\":\"auto\",\"height\":200,\"language\":\"html\"},\"editors\":[\"styles\"],\"everyRow\":false,\"helpers\":\"\",\"styles\":\"div.justify-content {\\n  justify-content: space-around;\\n}\\n\\ndiv.flex {\\n  display: flex;\\n}\"},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select count(1) as value,\'已修复缺陷数\' as name,\'#28B370\' as color from issues_type_ext_pm_bug where issues_id in (\\nselect id from issues where issues_type_id=\'98\' and del_flag=0 and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\nand if(\\\"$userNames\\\" = \\\"\'all\'\\\", 1=1, assigned_ids regexp concat(\'(^|,)(\',replace(replace(\\\"$userIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\nand status_id in(\'7855\',\'4\')\\nand $__timeFilter(create_time) \\n) \\nand if(\\\"$projectName\\\" = \\\"\'all\'\\\", 1=1  ,belong_to_project in($projectIds))\\nand if(\\\"$sprintName\\\" = \\\"\'all\'\\\", 1=1  ,sprint in($sprintIds))\\nand if(\\\"$bugSolutionName\\\" = \\\"\'all\'\\\", 1=1  ,bug_type in ($bugSolutionName))\\nand  if(\\\"$tagName\\\" =\\\"\'all\'\\\",1=1,issues_id in(select issues_id from issues_tag where tag_ids in ($tagIds)))\\n\\n union\\nselect round(avg(UNIX_TIMESTAMP(cast(close_time as datetime)) - UNIX_TIMESTAMP(cast(real_start_time as datetime))) / 86400,1) as value,\\n\'平均修复时长（天）\' as name,\'#28B370\' as color\\n\\n\\nfrom \\n(select * from issues where issues_type_id=98 and del_flag=0 and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\nand if(\\\"$userNames\\\" = \\\"\'all\'\\\", 1=1, assigned_ids regexp concat(\'(^|,)(\',replace(replace(\\\"$userIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\n and $__timeFilter(create_time) ) i left join issues_type_ext_pm_bug ext on i.id=ext.issues_id \\nleft join issues_status s on i.status_id = s.id\\nwhere \\nif(\\\"$projectName\\\" = \\\"\'all\'\\\", 1=1  ,ext.belong_to_project in($projectIds))\\nand if(\\\"$sprintName\\\" = \\\"\'all\'\\\", 1=1  ,ext.sprint in($sprintIds))\\nand if(\\\"$bugSolutionName\\\" = \\\"\'all\'\\\", 1=1  ,ext.bug_solution in ($bugSolutionName))\\nand  if(\\\"$tagName\\\" =\\\"\'all\'\\\",1=1,i.id in(select issues_id from issues_tag where tag_ids in ($tagIds)))\\nand s.type in (\'2\',\'3\')\\nand real_start_time is not null and real_start_time != \'\'\\nand close_time is not null and close_time != \'\'\\n\\n\\n\\n\\n  union\\n  select round(avg(m.count),0) as value,\\n\'日均修复数\' as name,\'#28B370\' as color\\n\\nfrom (\\nselect count(1) as count from \\n(select * from issues where issues_type_id=98 and del_flag=0 and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\nand if(\\\"$userNames\\\" = \\\"\'all\'\\\", 1=1, assigned_ids regexp concat(\'(^|,)(\',replace(replace(\\\"$userIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\n and $__timeFilter(create_time) ) i left join issues_type_ext_pm_bug ext on i.id=ext.issues_id \\nleft join issues_status s on i.status_id = s.id\\nwhere \\nif(\\\"$projectName\\\" = \\\"\'all\'\\\", 1=1  ,ext.belong_to_project in($projectIds))\\nand if(\\\"$sprintName\\\" = \\\"\'all\'\\\", 1=1  ,ext.sprint in($sprintIds))\\nand if(\\\"$bugSolutionName\\\" = \\\"\'all\'\\\", 1=1  ,ext.bug_solution in ($bugSolutionName))\\nand  if(\\\"$tagName\\\" =\\\"\'all\'\\\",1=1,i.id in(select issues_id from issues_tag where tag_ids in ($tagIds)))\\nand s.type in (\'2\',\'3\')\\nand real_start_time is not null and real_start_time != \'\'\\nand close_time is not null and close_time != \'\'\\ngroup by date_format(close_time, \'%Y%m%d\')\\n)m\\n\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"缺陷修复概览\",\"type\":\"harmonycloud-dynamictext-panel\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"gridPos\":{\"h\":7,\"w\":8,\"x\":0,\"y\":5},\"id\":25,\"options\":{\"followTheme\":false,\"getOption\":\"if(data.series.length ==0||data.series[0].length==0) {\\n  const option = {\\n    graphic: {\\n      elements: [\\n        {\\n          type: \'text\',\\n          left: \'center\',\\n          top: \'center\',\\n          style: {\\n            text: \'No data\',\\n            fontSize: 18,\\n//             fontWeight: 400,\\n            fill: \'#5E6164\',\\n            fontFamily:\'Inter, Helvetica, Arial, sans-serif\',\\n          }\\n        }\\n      ]\\n    }\\n  };\\n  echartsInstance.setOption(option)\\n  return \\n}\\nconst names = data.series[0].fields[0].values.buffer || []\\n  const values = data.series[0].fields[1].values.buffer || []\\n  const _data = []\\n  let total = 0\\n  names.forEach((v, i) =\\u003e {\\n    _data.push({ name: v, value: values[i] })\\n    total += Number(values[i])\\n  })\\n  _data.sort((a, b) =\\u003e a.value - b.value)\\n  const getValue = (name) =\\u003e {\\n    return Math.round(\\n      (_data.find((v) =\\u003e {\\n        return v.name === name\\n      })?.value /\\n        total) *\\n        100\\n    )\\n  }\\n\\n  const option = {\\n    tooltip: {\\n      trigger: \'item\',\\n    },\\n    legend: {\\n      right: \'5%\',\\n      top: \'center\',\\n      orient: \'vertical\',\\n      icon: \'rect\',\\n      itemHeight: 10,\\n      itemWidth: 14,\\n      itemGap: 10,\\n      formatter: function (name) {\\n        return `{a|${name}}` + `{c|${getValue(name)}%}`\\n      },\\n      textStyle: {\\n        rich: {\\n          a: {\\n            color: \'#333333\',\\n            width: 60,\\n            padding: [0, 20, 0, 6],\\n          },\\n          c: {\\n            color: \'#292E43\',\\n            fontWeight: 500,\\n            fontSize: 14,\\n          },\\n        },\\n      },\\n    },\\n    series: [\\n      {\\n        name: \'缺陷类型\',\\n        type: \'pie\',\\n        color: [\\n          \'#396CDF\',\\n          \'#79C9AA\',\\n          \'#EF8633\',\\n          \'#F6D047\',\\n          \'#B678D8\',\\n          \'#F0A2B0\',\\n          \'#BDBDBE\',\\n        ],\\n        center: [\'25%\', \'50%\'],\\n        radius: [\'0%\', \'70%\'],\\n        avoidLabelOverlap: false,\\n        label: {\\n          show: false,\\n          position: \'center\',\\n        },\\n        emphasis: {\\n          label: {\\n            show: false,\\n          },\\n        },\\n        labelLine: {\\n          show: false,\\n        },\\n        data: _data.reverse(),\\n      },\\n    ],\\n  }\\n  echartsInstance.setOption(option)\"},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \\nbug_type,\\n\\n\\ncount(1) as \'数量\'\\nfrom issues_type_ext_pm_bug b left join issues_tag t on b.issues_id=t.issues_id \\nwhere b.issues_id in(\\nselect id from issues where issues_type_id = 98 and del_flag=0 and  if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\nand if(\\\"$userNames\\\" = \\\"\'all\'\\\", 1=1, assigned_ids regexp concat(\'(^|,)(\',replace(replace(\\\"$userIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\nand $__timeFilter(create_time) \\n)\\nand if(\\\"$projectName\\\" = \\\"\'all\'\\\", 1=1  ,belong_to_project in($projectIds))\\nand if(\\\"$sprintName\\\" = \\\"\'all\'\\\", 1=1  ,sprint in($sprintIds))\\nand if(\\\"$bugSolutionName\\\" = \\\"\'all\'\\\", 1=1  ,bug_solution in ($bugSolutionName))\\nand if(\\\"$tagName\\\" =\\\"\'all\'\\\",1=1,t.tag_ids in ($tagIds))\\n\\nand bug_type is not null\\n\\ngroup by bug_type\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"缺陷类型统计图\",\"type\":\"bilibala-echarts-panel\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"description\":\"当前时刻尚未完成的缺陷按严重程度、优先级、状态、阶段的分布占比\",\"gridPos\":{\"h\":7,\"w\":9,\"x\":8,\"y\":5},\"id\":10,\"options\":{\"followTheme\":false,\"getOption\":\"if(data.series.length ==0||data.series[0].length==0) {\\n  const option = {\\n    graphic: {\\n      elements: [\\n        {\\n          type: \'text\',\\n          left: \'center\',\\n          top: \'center\',\\n          style: {\\n            text: \'No data\',\\n            fontSize: 18,\\n//             fontWeight: 400,\\n            fill: \'#5E6164\',\\n            fontFamily:\'Inter, Helvetica, Arial, sans-serif\',\\n          }\\n        }\\n      ]\\n    }\\n  };\\n  echartsInstance.setOption(option)\\n  return \\n}  \\nconst names = data.series[0].fields[0].values.buffer || []\\n  const values = data.series[0].fields[1].values.buffer || []\\n  const _data = []\\n  let total = 0\\n  names.forEach((v, i) =\\u003e {\\n    _data.push({ name: v, value: values[i] })\\n    total += Number(values[i])\\n  })\\n  const getValue = (name) =\\u003e {\\n    return (\\n      _data.find((v) =\\u003e {\\n        return v.name === name\\n      })?.value || 0\\n    )\\n  }\\n\\n  const option = {\\n    tooltip: {\\n      trigger: \'item\',\\n    },\\n    legend: {\\n      top: \'center\',\\n      right: 0,\\n      orient: \'vertical\',\\n      icon: \'rect\',\\n      itemHeight: 10,\\n      itemWidth: 14,\\n      itemGap: 20,\\n      formatter: function (name) {\\n        return (\\n          `{a|${name}}` +\\n          `value:` +\\n          `{c|${getValue(name)}}` +\\n          `Percent:` +\\n          // eslint-disable-next-line @typescript-eslint/ban-ts-comment\\n          // @ts-ignore\\n          `{c|${parseInt((getValue(name) / total) * 100)}%}`\\n        )\\n      },\\n      textStyle: {\\n        rich: {\\n          a: {\\n            color: \'#333333\',\\n            width: 40,\\n          },\\n          c: {\\n            color: \'#292E43\',\\n            fontWeight: 500,\\n            fontSize: 14,\\n            padding: [0, 10, 0, 6],\\n          },\\n        },\\n      },\\n    },\\n    series: [\\n      {\\n        name: \'存量缺陷\',\\n        type: \'pie\',\\n        color: [\'#A3302F\', \'#E14645\', \'#EEC86B\', \'#58B076\'],\\n        center: [\'25%\', \'50%\'],\\n        radius: [\'50%\', \'70