ata: rollMinArray,\\n        type: \'line\',\\n        symbol: \'none\',\\n        areaStyle: {\\n          color: \'rgba(255,255,255)\',\\n        },\\n      },\\n      {\\n        name: \'标准差\',\\n        z: 0,\\n        stack: \'Total\',\\n        data: rollMaxArray,\\n        type: \'line\',\\n        symbol: \'none\',\\n        areaStyle: {},\\n      },\\n      {\\n        name: \'滚动均值(4个)\',\\n        z: 1,\\n        data: rollAvgArray,\\n        type: \'line\',\\n        symbol: \'none\',\\n      },\\n      {\\n        name: \'均值\',\\n        z: 2,\\n        data: avgArray,\\n        type: \'line\',\\n        symbol: \'none\',\\n        itemStyle: {\\n          normal: {\\n            lineStyle: {\\n              type: \'dashed\',\\n            },\\n          },\\n        },\\n      },\\n    ],\\n  }\\nechartsInstance.setOption(option)\"},\"pluginVersion\":\"8.4.4\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"\\nselect \\ncast(close_time as datetime) as \'time\',\\n((unix_timestamp(cast(close_time as datetime))-unix_timestamp(create_time)) /(60*60*24)) as need\\nfrom issues\\nwhere\\nstatus_id in (7855,4) and issues_type_id=98\\nand del_flag=0 \\nand  if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\nand if(\\\"$userNames\\\" = \\\"\'all\'\\\", 1=1, assigned_ids regexp concat(\'(^|,)(\',replace(replace(\\\"$userIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\nand $__timeFilter(create_time) \\nand close_time is not null\\ngroup by date_format(create_time,\'%Y%m%d\')\\nORDER BY close_time asc\\n\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"artifacts_repositories\",\"timeColumn\":\"create_time\",\"time