f(\'$amp_organ_id\'=\'null\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')) and del_flag=0)\\ngroup by date_format(i.update_time,\'%Y%m%d\'),i.status\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\n  \\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"devops_job_build_info\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"流水线状态分布\",\"transformations\":[],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"每日流水线构建次数\",\"fieldConfig\":{\"defaults\":{\"color\":{\"fixedColor\":\"#226ee7\",\"mode\":\"fixed\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"构建次数\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":25,\"gradientMode\":\"opacity\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineWidth\":2,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":20},\"id\":12,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource