INSERT INTO `dashboard_version` VALUES (453, 19, 15, 0, 16, '2024-06-12 08:21:04', 40, '', '{\"annotations\":{\"list\":[{\"builtIn\":1,\"datasource\":{\"type\":\"grafana\",\"uid\":\"-- Grafana --\"},\"enable\":true,\"hide\":true,\"iconColor\":\"rgba(0, 211, 255, 1)\",\"name\":\"Annotations \\u0026 Alerts\",\"target\":{\"limit\":100,\"matchAny\":false,\"tags\":[],\"type\":\"dashboard\"},\"type\":\"dashboard\"}]},\"editable\":true,\"fiscalYearStartMonth\":0,\"graphTooltip\":0,\"id\":19,\"links\":[],\"liveNow\":false,\"panels\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"super-light-blue\",\"value\":null}]}},\"overrides\":[]},\"gridPos\":{\"h\":3,\"w\":2,\"x\":0,\"y\":0},\"id\":2,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"none\",\"justifyMode\":\"auto\",\"orientation\":\"auto\",\"reduceOptions\":{\"calcs\":[],\"fields\":\"\",\"values\":false},\"textMode\":\"auto\"},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select count(1)\\nfrom project \\nwhere del_flag=0 and tenant_id = if(\'$amp_organ_id\'=\'null\', tenant_id,\'$amp_organ_id\')\\n\\n\\n\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"项目总数\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"yellow\",\"value\":null}]}},\"overrides\":[]},\"gridPos\":{\"h\":3,\"w\":2,\"x\":2,\"y\":0},\"id\":4,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"auto\",\"orientation\":\"auto\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"\",\"values\":false},\"textMode\":\"auto\"},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select count(distinct u.id) from yanlian_devops_issues_track_v2.project p \\nleft join yanlian_app_management.sys_resource_instance r on concat(p.resource_type_code,p.id)=concat(r.resource_type_code,r.resource_instance_id)\\nleft join yanlian_app_management.sys_owner_resource o on r.id = o.resource_id\\nleft join yanlian_app_management.sys_resource_owner_instance i on i.id = o.resource_owner_id\\nleft join yanlian_app_management.sys_user u on u.id = i.resource_owner_instance_id\\nwhere  if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, p.tenant_id in($amp_organ_id))\\n and p.del_flag=0\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"人员总数\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[]},\"gridPos\":{\"h\":3,\"w\":3,\"x\":4,\"y\":0},\"id\":7,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"auto\",\"orientation\":\"auto\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"\",\"values\":false},\"textMode\":\"auto\"},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select  count(1) as count\\n\\nfrom issues i\\nwhere \\ni.issues_type_id in (96,97,98) and i.status_id =3 and\\ni.del_flag=0 and tenant_id = if(\'$amp_organ_id\'=\'null\', tenant_id,\'$amp_organ_id\')\",\"refId\":\"A\",\"sql\"