INSERT INTO `dashboard_version` VALUES (456, 32, 57, 0, 58, '2024-06-17 15:43:18', 40, '', '{\"annotations\":{\"list\":[{\"builtIn\":1,\"datasource\":{\"type\":\"grafana\",\"uid\":\"-- Grafana --\"},\"enable\":true,\"hide\":true,\"iconColor\":\"rgba(0, 211, 255, 1)\",\"name\":\"Annotations \\u0026 Alerts\",\"target\":{\"limit\":100,\"matchAny\":false,\"tags\":[],\"type\":\"dashboard\"},\"type\":\"dashboard\"}]},\"editable\":true,\"fiscalYearStartMonth\":0,\"graphTooltip\":0,\"id\":32,\"links\":[],\"liveNow\":false,\"panels\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"gridPos\":{\"h\":5,\"w\":20,\"x\":0,\"y\":0},\"id\":2,\"options\":{\"content\":\"\\u003cdiv class=\\\"flex justify-content\\\" style=\\\"color:#9D9D9D;width:100%;\\\"\\u003e\\n  {{#each data}}\\n\\n  \\u003cdiv style=\\\"text-align:center\\\"\\u003e\\n    \\u003cdiv\\u003e{{name}}\\u003c/div\\u003e\\n    \\u003cdiv\\u003e\\n      \\u003cspan style=\\\"font-size:60px;margin-right:5px;color:{{color}}\\\"\\u003e{{count}}\\u003c/span\\u003e\\u003cspan\\u003e{{unit}}\\u003c/span\\u003e\\n    \\u003c/div\\u003e\\n  \\u003c/div\\u003e\\n\\n  {{/each}}\\n\\u003c/div\\u003e\",\"defaultContent\":\"The query didn\'t return any results.\",\"editor\":{\"format\":\"auto\",\"height\":200,\"language\":\"html\"},\"editors\":[\"styles\"],\"everyRow\":false,\"helpers\":\"\",\"styles\":\"div.justify-content {\\n  justify-content: space-around;\\n}\\n\\ndiv.flex {\\n  display: flex;\\n}\"},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select  \'待处理需求\' as name,count(1) as count,\'个\' as unit,\'#28B370\' as color\\nfrom issues i left join issues_status s on i.status_id=s.id\\n where  issues_type_id=\'96\' and s.type = 0\\n and find_in_set(\'$userId\',i.assigned_ids)\\n and i.del_flag=0\\n and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\n\\n union\\n\\nselect  \'处理中需求\' as name,count(1) as count,\'个\' as unit,\'#28B370\' as color\\nfrom issues i left join issues_status s on i.status_id=s.id\\n where  issues_type_id=\'96\' and s.type = 1\\n and find_in_set(\'$userId\',i.assigned_ids)\\n and i.del_flag=0\\n and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\n\\n union\\n\\nselect \'逾期需求\' as name,count(1) as count,\'个\' as unit,\'#F34D1F\' as color\\nfrom issues i left join issues_status s on i.status_id=s.id\\n where  i.issues_type_id=\'96\' \\n  and find_in_set(\'$userId\',i.assigned_ids)\\n and i.del_flag=0\\n and i.end_date is not null and i.end_date != \'\' and now() \\u003e cast(i.end_date as date )and (s.type in(0,1) or cast(i.close_time as date) \\u003e cast(i.end_date as date))\\nand if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\')\\n\\n union\\n\\nselect  \'待处理缺陷\' as name,count(1) as count,\'个\' as unit,\'#226EE7\' as color\\nfrom issues i left join issues_status s on i.status_id=s.id\\n where  issues_type_id=\'98\' and s.type = 0\\n and find_in_set(\'$userId\',i.assigned_ids)\\n and i.del_flag=0\\n and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\n\\n union\\n\\nselect  \'处理中缺陷\' as name,count(1) as count,\'个\' as unit,\'#226EE7\' as color\\nfrom issues i left join issues_status s on i.status_id=s.id\\n where  issues_type_id=\'98\' and s.type = 1\\n and i.assigned_ids like concat(\'%\',\'$userId\',\'%\')\\n and i.del_flag=0\\n and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') \\n\\n union\\n\\nselect \'记录工时\' as name , sum(working_hours) as count,\'小时\' as unit,\'#226EE7\' as color\\nfrom issues_type_ext_working_hours \\nwhere issues_id in(select id from issues i where issues_type_id=114  and find_in_set(\'$userId\',i.assigned_ids) and del_flag=0  and if(\'$amp_organ_id\'=\'null\', 1=1, tenant_id =  \'$amp_organ_id\') ) \",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"个人工作概览\",\"type\":\"harmonycloud-dynamictext-panel\"},{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"If5u9w-Vz\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"fixedColor\":\"#226ee7\",\"mode\":\"fixed\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[]},\"gridPos\":{\"h\":5,\"w\":4,\"x\":20,\"y\":0},\"id\":16,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"auto\",\"orientation\":\"auto\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"\",\"values\":false},\"text\":{\"titleSize\":1},\"textMode\":\"auto\"},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"cacheDurationSeconds\":0,\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"If5u9w-Vz\"},\"fields\":[{\"jsonPath\":\"$.data\",\"type\":\"number\"}],\"headers\":[[\"X-SCM-TOKEN\",\"SCM@2023\"]],\"method\":\"GET\",\"queryParams\":\"\",\"refId\":\"A\",\"urlPath\":\"/dashboard/getLineCount?from=$__from\\u0026to=$__to\\u0026username=$userLoginName\"}],\"title\":\"代码行数\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"description\":\"所选时间区间内每日新增、完成以及存量(即尚未完成)需求的数量曲线\",\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":5},\"id\":4,\"options\":{\"followTheme\":false,\"getOption\":\"if(data.series.length ==0||data.series[0].length==0) {\\n  const option = {\\n    graphic: {\\n      elements: [\\n        {\\n          type: \'text\',\\n          left: \'center\',\\n          top: \'center\',\\n          style: {\\n            text: \'No data\',\\n            fontSize: 18,\\n//             fontWeight: 400,\\n            fill: \'#5E6164\',\\n            fontFamily:\'Inter, Helvetica, Arial, sans-serif\',\\n          }\\n        }\\n      ]\\n    }\\n  };\\n  echartsInstance.setOption(option)\\n  return \\n}\\nfunction formatDate(date){\\n  var year = date.getFullYear();\\n  var month =(date.getMonth() + 1).toString();\\n  var day = (date.getDate()).toString();\\n  if (month.length == 1) {\\n    month = \\\"0\\\" + month;\\n  }\\n  if (day.length == 1) {\\n    day = \\\"0\\\" + day;\\n  }\\n  var dateTime = year + \\\"/\\\" + month + \\\"/\\\" + day;\\n  return dateTime;\\n}\\nconst timeArr = data.series[0].fields[0].values.buffer;\\nconst newCountArr = data.series[0].fields[1].values.buffer;\\nconst finishCountArr = data.series[0].fields[2].values.buffer;\\nconst remainCountArr = data.series[0].fields[3].values.buffer;\\nconst mockData = [];\\nfor(let i = 0;i\\u003ctimeArr.length;i++) {\\n  mockData.push({\\n    time: formatDate(new Date(timeArr[i])),\\n    new: newCountArr[i],\\n    fix: finishCountArr[i],\\n    stock: remainCountArr[i]\\n  })\\n}\\n\\n  const timeArray = mockData.map((item) =\\u003e item.time)\\n  const newArray = mockData.map((item) =\\u003e item.new)\\n  const fixArray = mockData.map((item) =\\u003e item.fix)\\n  const stockArray = mockData.map((item) =\\u003e item.stock)\\n  const option = {\\n    color: [\'#EDC86B\', \'#E05933\', \'#58B076\'],\\n    grid: {\\n      left: 40,\\n      right: 40,\\n      bottom: 40,\\n    },\\n    tooltip: {\\n      trigger: \'axis\',\\n    },\\n    legend: {\\n      data: [\'存量\', \'新增\', \'修复\'],\\n      icon: \'rect\',\\n      itemHeight: 8,\\n      itemWidth: 12,\\n      right: 0,\\n    },\\n    xAxis: [\\n      {\\n        type: \'category\',\\n        data: timeArray,\\n        axisPointer: {\\n          type: \'shadow\',\\n        },\\n        axisTick: {\\n          show: false,\\n        },\\n        axisLine: {\\n          show: false,\\n        },\\n      },\\n    ],\\n    yAxis: [\\n      {\\n        type: \'value\',\\n        minInterval: 5,\\n      },\\n    ],\\n    series: [\\n      {\\n        name: \'存量\',\\n        type: \'line\',\\n        data: stockArray,\\n        z: -1,\\n      },\\n      {\\n        name: \'新增\',\\n        type: \'bar\',\\n        data: newArray,\\n        barMaxWidth: 10,\\n      },\\n      {\\n        name: \'修复\',\\n        type: \'bar\',\\n        data: fixArray,\\n        barGap: \'0%\',\\n        barMaxWidth: 10,\\n      },\\n    ],\\n  }\\n  echartsInstance.setOption(option)\"},\"pluginVersion\":\"8.4.4\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"hide\":false,\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"select \\n$__timeGroupAlias(i1.create_time,1d),\\ncount(1) as new_count,\\n(select count(1) from issues i2 where i2.del_flag=0 and i2.issues_type_id=96 and find_in_set(\'$userId\',i2.assigned_ids) and if(\'$amp_organ_id\'=\'null\', 1=1, i2.tenant_id =  \'$amp_organ_id\')   and date_format(cast(i2.close_time as datetime), \'%Y%m%d\') = date_format(cast(i1.create_time as datetime), \'%Y%m%d\') and i2.status_id in (\'3\',\'4\',\'10\') ) as finish_count,\\n\\n((select count(1) from issues i2 where i2.del_flag=0 and i2.issues_type_id=96 and find_in_set(\'$userId\',i2.assigned_ids) and if(\'$amp_organ_id\'=\'null\', 1=1, i2.tenant_id =  \'$amp_organ_id\')   and date_format(cast(i2.create_time as datetime), \'%Y%m%d\') \\u003c= date_format(cast(i1.create_time as datetime), \'%Y%m%d\')) - (select count(1) from issues i3 where i3.del_flag=0 and i3.issues_type_id=96 and find_in_set(\'$userId\',i3.assigned_ids) and if(\'$amp_organ_id\'=\'null\', 1=1, i3.tenant_id =  \'$amp_organ_id\')   and date_format(cast(i3.close_time as datetime), \'%Y%m%d\') \\u003c= date_format(cast(i1.create_time as datetime), \'%Y%m%d\') and i3.status_id in (\'3\',\'4\',\'10\'))) as remain_count\\n\\n\\n\\n\\nfrom issues i1\\nwhere  i1.issues_type_id=96\\n and find_in_set(\'$userId\',i1.assigned_ids)\\n and i1.del_flag=0\\n and if(\'$amp_organ_id\'=\'null\', 1=1, i1.tenant_id =  \'$amp_organ_id\') \\nand $__timeFilter(i1.create_time)\\ngroup by date_format(cast(i1.create_time as datetime), \'%Y%m%d\')\\n\\nORDER BY i1.create_time ASC\\n\\n\\n\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"artifacts_repositories\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"timestamp\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"需求趋势\",\"transformations\":[],\"type\":\"bilibala-echarts-panel\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"description\":\"所选时间区间内每日新增、修复以及存量(即尚未完成)缺陷的数量曲线\",\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":5},\"id\":5,\"options\":{\"followTheme\":false,\"getOption\":\"if(data.series.length ==0||data.series[0].length==0) {\\n  const option = {\\n    graphic: {\\n      elements: [\\n        {\\n          type: \'text\',\\n          left: \'center\',\\n          top: \'center\',\\n          style: {\\n            text: \'No data\',\\n            fontSize: 18,\\n//             fontWeight: 400,\\n            fill: \'#5E6164\',\\n            fontFamily:\'Inter, Helvetica, Arial, sans-serif\',\\n          }\\n        }\\n      ]\\n    }\\n  };\\n  echartsInstance.setOption(option)\\n  return \\n}\\nfunction formatDate(date){\\n  var year = date.getFullYear();\\n  var month =(date.getMonth() + 1).toString();\\n  var day = (date.getDate()).toString();\\n  if (month.length == 1) {\\n    month = \\\"0\\\" + month;\\n  }\\n  if (day.length == 1) {\\n    day = \\\"0\\\" + day;\\n  }\\n  var dateTime = year + \\\"/\\\" + month + \\\"/\\\" + day;\\n  return dateTime;\\n}\\nconst timeArr = data.series[0].fields[0].values.buffer;\\nconst newCountArr = data.series[0].fields[1].values.buffer;\\nconst finishCountArr = data.series[0].fields[2].values.buffer;\\nconst remainCountArr = data.series[0].fields[3].values.buffer;\\nconst mockData = [];\\nfor(let i = 0;i\\u003ctimeArr.length;i++) {\\n  mockData.push({\\n    time: formatDate(new Date(timeArr[i])),\\n    new: newCountArr[i],\\n    fix: finishCountArr[i],\\n    stock: remainCountArr[i]\\n  })\\n}\\n\\n  const timeArray = mockData.map((item) =\\u003e item.time)\\n  const newArray = mockData.map((item) =\\u003e item.new)\\n  const fixArray = mockData.map((item) =\\u003e item.fix)\\n  const stockArray = mockData.map((item) =\\u003e item.stock)\\n  const option = {\\n    color: [\'#EDC86B\', \'#E05933\', \'#396CDF\'],\\n    grid: {\\n      left: 40,\\n      right: 40,\\n      bottom: 40,\\n    },\\n    tooltip: {\\n      trigger: \'axis\',\\n    },\\n    legend: {\\n      data: [\'存量\', \'新增\', \'修复\'],\\n      icon: \'rect\',\\n      itemHeight: 8,\\n      itemWidth: 12,\\n      right: 0,\\n    },\\n    xAxis: [\\n      {\\n        type: \'category\',\\n        data: timeArray,\\n        axisPointer: {\\n          type: \'shadow\',\\n        },\\n        axisTick: {\\n          show: false,\\n        },\\n        axisLine: {\\n          show: false,\\n        },\\n      },\\n    ],\\n    yAxis: [\\n      {\\n        type: \'value\',\\n        minInterval: 5,\\n      },\\n    ],\\n    series: [\\n      {\\n        name: \'存量\',\\n        type: \'line\',\\n        data: stockArray,\\n        z: -1,\\n      },\\n      {\\n        name: \'新增\',\\n        type: \'bar\',\\n        data: newArray,\\n        barMaxWidth: 10,\\n      },\\n      {\\n        name: \'修复\',\\n        type: \'bar\',\\n        data: fixArray,\\n        barGap: \'0%\',\\n        barMaxWidth: 10,\\n      },\\n    ],\\n  }\\n  echartsInstance.setOption(option)\"},\"pluginVersion\":\"8.4.4\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"hide\":false,\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"select \\n$__timeGroupAlias(i1.create_time,1d),\\ncount(1) as new_count,\\n(select count(1) from issues i2 where i2.del_flag=0 and i2.issues_type_id=98 and find_in_set(\'$userId\',i2.assigned_ids) and if(\'$amp_organ_id\'=\'null\', 1=1, i2.tenant_id =  \'$amp_organ_id\')   and date_format(cast(i2.close_time as datetime), \'%Y%m%d\') = date_format(cast(i1.create_time as datetime), \'%Y%m%d\') and i2.status_id in (\'7855\',\'4\') ) as finish_count,\\n\\n((select count(1) from issues i2 where i2.del_flag=0 and i2.issues_type_id=98 and find_in_set(\'$userId\',i2.assigned_ids) and if(\'$amp_organ_id\'=\'null\', 1=1, i2.tenant_id =  \'$amp_organ_id\')   and date_format(cast(i2.create_time as datetime), \'%Y%m%d\') \\u003c= date_format(cast(i1.create_time as datetime), \'%Y%m%d\')) - (select count(1) from issues i3 where i3.del_flag=0 and i3.issues_type_id=98 and find_in_set(\'$userId\',i3.assigned_ids) and if(\'$amp_organ_id\'=\'null\', 1=1, i3.tenant_id =  \'$amp_organ_id\')   and date_format(cast(i3.close_time as datetime), \'%Y%m%d\') \\u003c= date_format(cast(i1.create_time as datetime), \'%Y%m%d\') and i3.status_id in (\'7855\',\'4\'))) as remain_count\\n\\n\\n\\n\\nfrom issues i1\\nwhere  i1.issues_type_id=98\\n and find_in_set(\'$userId\',i1.assigned_ids)\\n and i1.del_flag=0\\n and if(\'$amp_organ_id\'=\'null\', 1=1, i1.tenant_id =  \'$amp_organ_id\') \\nand $__timeFilter(i1.create_time)\\ngroup by date_format(cast(i1.create_time as datetime), \'%Y%m%d\')\\n\\nORDER BY i1.create_time ASC\\n\\n\\n\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"artifacts_repositories\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"timestamp\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"缺陷趋势\",\"transformations\":[],\"type\":\"bilibala-echarts-panel\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"description\":\"统计当天完成的需求耗时，按周统计\",\"gridPos\":{\"h\":9,\"w\":12,\"x\":0,\"y\":13},\"id\":13,\"options\":{\"followTheme\":false,\"getOption\":\"if(data.series.length ==0||data.series[0].length==0) {\\n  const option = {\\n    graphic: {\\n      elements: [\\n        {\\n          type: \'text\',\\n          left: \'center\',\\n          top: \'center\',\\n          style: {\\n            text: \'No data\',\\n            fontSize: 18,\\n//             fontWeight: 400,\\n            fill: \'#5E6164\',\\n            fontFamily:\'Inter, Helvetica, Arial, sans-serif\',\\n          }\\n        }\\n      ]\\n    }\\n  };\\n  echartsInstance.setOption(option)\\n  return \\n}\\nconst json = data  \\nconsole.log(data)\\nconst formatDate = (date) =\\u003e {\\n    //时间戳\\n    const _date = new Date(date)\\n    const year = _date.getFullYear()\\n    let month = (_date.getMonth() + 1).toString()\\n    let day = _date.getDate().toString()\\n    if (month.length == 1) {\\n      month = \'0\' + month\\n    }\\n    if (day.length == 1) {\\n      day = \'0\' + day\\n    }\\n    const dateTime = month + \'/\' + day\\n    return dateTime\\n  }\\n  const fields = json.series[0].fields\\n  const timeArray =\\n    fields\\n      .find((v) =\\u003e {\\n        return v.name === \'Time\'\\n      })\\n      ?.values?.buffer?.map((v) =\\u003e {\\n        return formatDate(v)\\n      }) || []\\n  const array1 =\\n    fields.find((v) =\\u003e {\\n      return v.name === \'耗时1周内\'\\n    })?.values?.buffer || []\\n  const array2 =\\n    fields.find((v) =\\u003e {\\n      return v.name === \'耗时1-2周\'\\n    })?.values?.buffer || []\\n  const array3 =\\n    fields.find((v) =\\u003e {\\n      return v.name === \'耗时2-4周\'\\n    })?.values?.buffer || []\\n  const array4 =\\n    fields.find((v) =\\u003e {\\n      return v.name === \'耗时4周以上\'\\n    })?.values?.buffer || []\\n  const option = {\\n    color: [\'#7EB5F8\', \'#6195F5\', \'#396CDF\', \'#163C95\'],\\n    grid: {\\n      left:40,\\n      right: 40,\\n      bottom:40,\\n    },\\n    tooltip: {\\n      trigger: \'axis\',\\n    },\\n    legend: {\\n      data: [\'耗时1周内\', \'耗时1-2周\', \'耗时2-4周\', \'耗时4周以上\'],\\n      icon: \'rect\',\\n      itemHeight: 8,\\n      itemWidth: 12,\\n      right: 0,\\n    },\\n    xAxis: [\\n      {\\n        type: \'category\',\\n        data: timeArray,\\n        axisPointer: {\\n          type: \'shadow\',\\n        },\\n        axisTick: {\\n          show: false,\\n        },\\n        axisLine: {\\n          show: false,\\n        },\\n      },\\n    ],\\n    yAxis: [\\n      {\\n        type: \'value\',\\n        minInterval: 5,\\n      },\\n    ],\\n    series: [\\n      {\\n        name: \'耗时1周内\',\\n        type: \'bar\',\\n        stack: \'stack\',\\n        data: array1,\\n        barMaxWidth: 12,\\n      },\\n      {\\n        name: \'耗时1-2周\',\\n        type: \'bar\',\\n        stack: \'stack\',\\n        data: array2,\\n        barMaxWidth: 12,\\n      },\\n      {\\n        name: \'耗时2-4周\',\\n        type: \'bar\',\\n        stack: \'stack\',\\n        data: array3,\\n        barMaxWidth: 12,\\n      },\\n      {\\n        name: \'耗时4周以上\',\\n        type: \'bar\',\\n        stack: \'stack\',\\n        data: array4,\\n        barMaxWidth: 12,\\n      },\\n    ],\\n  }\\n  echartsInstance.setOption(option)\"},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"rawQuery\":true,\"rawSql\":\"select $__timeGroupAlias(create_time,1d),\\ncase when UNIX_TIMESTAMP(cast(close_time as datetime)) - UNIX_TIMESTAMP(cast(real_start_time as datetime)) \\u003c= 604800 then \'耗时1周内\'\\nwhen UNIX_TIMESTAMP(cast(close_time as datetime)) - UNIX_TIMESTAMP(cast(real_start_time as datetime)) \\u003c= 1209600 then \'耗时1-2周\'\\nwhen UNIX_TIMESTAMP(cast(close_time as datetime)) - UNIX_TIMESTAMP(cast(real_start_time as datetime)) \\u003c= 2419200 then \'耗时2-4周\'\\nelse \'耗时4周以上\' end as metric,count(1)\\n\\n\\n\\n from issues  where  issues_type_id=\'96\' and del_flag=0 and real_start_time is not null and close_time is not null and del_flag=0