INSERT INTO `dashboard_version` VALUES (540, 43, 19, 0, 20, '2024-09-25 09:57:48', 40, '', '{\"annotations\":{\"list\":[{\"builtIn\":1,\"datasource\":{\"type\":\"grafana\",\"uid\":\"-- Grafana --\"},\"enable\":true,\"hide\":true,\"iconColor\":\"rgba(0, 211, 255, 1)\",\"name\":\"Annotations \\u0026 Alerts\",\"target\":{\"limit\":100,\"matchAny\":false,\"tags\":[],\"type\":\"dashboard\"},\"type\":\"dashboard\"}]},\"description\":\"\",\"editable\":true,\"fiscalYearStartMonth\":0,\"graphTooltip\":0,\"id\":43,\"links\":[],\"liveNow\":false,\"panels\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false}},\"mappings\":[]},\"overrides\":[]},\"gridPos\":{\"h\":11,\"w\":7,\"x\":0,\"y\":0},\"id\":23,\"options\":{\"displayLabels\":[\"value\"],\"legend\":{\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"pieType\":\"pie\",\"reduceOptions\":{\"calcs\":[\"first\"],\"fields\":\"\",\"values\":true},\"tooltip\":{\"mode\":\"multi\",\"sort\":\"asc\"}},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select\\n  d.dept_name,\\n  count(1) as name\\nfrom\\n  devops_jenkins_job job\\n  left join yanlian_app_management.sys_department d on job.tenant = d.organization_id\\nwhere\\n  job.del_flag = 0\\n  and job.tenant != \'\'\\ngroup by\\n  d.dept_name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"流水线总数\",\"type\":\"piechart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"每日流水线构建次数\",\"fieldConfig\":{\"defaults\":{\"color\":{\"fixedColor\":\"#226ee7\",\"mode\":\"fixed\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"构建次数\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":25,\"gradientMode\":\"opacity\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineWidth\":2,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":6,\"w\":17,\"x\":7,\"y\":0},\"id\":12,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\'\\nFROM ( select count(1) as count, i.update_time \\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\n where i.del_flag=0 \\n and if(\'$amp_organ_id\'=\'3267246491214659584\', 1=1, j.tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, j.label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\ngroup by date_format(i.update_time,\'%Y%m%d\')\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"devops_job_build_info\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"流水线构建次数\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":0,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 公共信用部\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"red\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"公共信用部（平台办）\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 科技交付中心\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"科技交付中心\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 普惠信用部\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"blue\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"普惠信用部\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 企业信用部\"},\"properties\":[{\"id\":\"displayName\",\"value\":\"企业信用部\"},{\"id\":\"color\",\"value\":{\"fixedColor\":\"orange\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":5,\"w\":17,\"x\":7,\"y\":6},\"id\":20,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"fields\":[{\"jsonPath\":\"\"}],\"format\":\"table\",\"hide\":false,\"method\":\"GET\",\"queryParams\":\"\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\',\\n  middle.status_name as \'metric\'\\nFROM ( select count(1) as count,i.update_time ,(case \\n  when j.tenant=\'3267282568738619392\' then \'公共信用部\'\\n  when j.tenant=\'3267284931239067648\' then \'科技交付中心\'\\n  when j.tenant=\'3267282062251245568\' then \'企业信用部\'\\n  when j.tenant=\'3267281511404912640\' then \'普惠信用部\'\\n  when j.tenant=\'3267283983108259840\' then \'创新研发中心\'\\n  else j.tenant\\nend) as status_name\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\n where i.del_flag=0 and j.tenant !=\'\' and j.del_flag=0 \\ngroup by date_format(i.update_time,\'%Y%m%d\')\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\n  group by 1,2\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"urlPath\":\"\"}],\"title\":\"流水线构建情况\",\"transformations\":[{\"id\":\"prepareTimeSeries\",\"options\":{\"format\":\"multi\"}}],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"统计每日成功执行的流水线构建时长，单位：分钟\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\",\"seriesBy\":\"last\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisGridShow\":true,\"axisLabel\":\"分钟\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"bars\",\"fillOpacity\":100,\"gradientMode\":\"scheme\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"smooth\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"normal\"},\"thresholdsStyle\":{\"mode\":\"dashed\"}},\"decimals\":1,\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"#226ee7\",\"value\":null},{\"color\":\"#f34d1f\",\"value\":5}]}},\"overrides\":[]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":0,\"y\":11},\"id\":8,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.avg_time as \'时长\'\\nFROM ( \\n\\nselect _m.update_time,avg(duration) / 60 as avg_time\\nfrom (select i.update_time,(unix_timestamp(i.end_time) - unix_timestamp(i.start_time)) as duration\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\nwhere\\ni.update_time is not null and i.status=\'SUCCESS\' and i.del_flag=0\\nand job_id in(select id from devops_jenkins_job where del_flag=0 and if(\'$amp_organ_id\'=\'3267246491214659584\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')))\\norder by update_time asc\\n) as _m\\ngroup by date_format(update_time,\'%Y%m%d\')\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"devops_job_build_info\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFil