\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 公共信用部\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"red\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"公共信用部（平台办）\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 科技交付中心\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"科技交付中心\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 普惠信用部\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"blue\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"普惠信用部\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 企业信用部\"},\"properties\":[{\"id\":\"displayName\",\"value\":\"企业信用部\"},{\"id\":\"color\",\"value\":{\"fixedColor\":\"orange\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":12,\"y\":35},\"id\":20,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"fields\":[{\"jsonPath\":\"\"}],\"format\":\"table\",\"hide\":false,\"method\":\"GET\",\"queryParams\":\"\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\',\\n  middle.status_name as \'metric\'\\nFROM ( select count(1) as count,i.update_time ,(case \\n  when j.tenant=\'3267282568738619392\' then \'公共信用部\'\\n  when j.tenant=\'3267284931239067648\' then \'科技交付中心\'\\n  when j.tenant=\'3267282062251245568\' then \'企业信用部\'\\n  when j.tenant=\'3267281511404912640\' then \'普惠信用部\'\\n  when j.tenant=\'3267283983108259840\' then \'创新研发中心\'\\n  else j.tenant\\nend) as status_name\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\n where i.del_flag=0 and j.tenant !=\'\' and j.del_flag=0 \\ngroup by date_format(i.update_time,\'%Y%m%d\')\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\n  group by 1,2\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"urlPath\":\"\"}],\"title\":\"各部门流水线构建情况\",\"transformations\":[{\"id\":\"prepareTimeSeries\",\"options\":{\"format\":\"multi\"}}],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"统计每日成功执行的流水线构建时长，单位：分钟\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\",\"seriesBy\":\"last\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisGridShow\":true,\"axisLabel\":\"分钟\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"bars\",\"fillOpacity\":100,\"gradientMode\":\"scheme\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"smooth\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"normal\"},\"thresholdsStyle\":{\"mode\":\"dashed\"}},\"decimals\":1,\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"#226ee7\",\"value\":null},{\"color\":\"#f34d1f\",\"value\":5}]}},\"overrides\":[]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":0,\"y\":45},\"id\":8,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.avg_time as \'时长\'\\nFROM ( \\n\\nselect _m.update_time,avg(duration) / 60 as avg_time\\nfrom (select i.update_time,(unix_timestamp(i.end_time) - unix_timestamp(i.start_time)) as duration\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\nwhere\\ni.update_time is not null and i.status=\'SUCCESS\' and i.del_flag=0\\nand job_id in(select id from devops_jenkins_job where del_flag=0 and if(\'$amp_organ_id\'=\'3267246491214659584\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')))\\norder by update_time asc\\n) as _m\\ngroup by date_format(update_time,\'%Y%m%d\')\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"devops_job_build_info\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"流水线构建平均时长\",\"transformations\":[],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":0,\"gradientMode\":\"opacity\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":7,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"never\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"失败\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#e15a33\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"成功\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#58b076\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":12,\"y\":45},\"id\":14,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"multi\",\"sort\":\"asc\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.time,1d),\\n  middle.count as \'数量\'\\nFROM (select count(1) as count,p.create_time as time\\nfrom devops_product p\\nleft join devops_repository r on p.repo_id=r.id\\nwhere p.create_time is not null \\ngroup by date_format(p.create_time, \'%Y%m%d\')\\norder by p.create_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.time)\\nORDER BY $__timeGroup(middle.time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"构建制品统计\",\"type\":\"timeseries\"}],\"refresh\":false,\"schemaVersion\":37,\"style\":\"dark\",\"tags\":[],\"templating\":{\"list\":[{\"allValue\":\"\'all\'\",\"current\":{\"selected\":true,\"text\":[\"All\"],\"value\":[\"$__all\"]},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select name from sys_tag where classification_id= 2428931245089341440 and if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope = 1)) and is_deleted=0\\nunion\\nselect \'\'\",\"description\":\"\",\"hide\":2,\"includeAll\":true,\"label\":\"标签\",\"multi\":true,\"name\":\"tagNames\",\"options\":[],\"query\":\"select name from sys_tag where classification_id= 2428931245089341440 and if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope = 1)) and is_deleted=0\\nunion\\nselect \'\'\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"},{\"current\":{\"selected\":false,\"text\":\"3267246491214659584\",\"value\":\"3267246491214659584\"},\"hide\":2,\"label\":\"amp_organ_id\",\"name\":\"amp_organ_id\",\"options\":[{\"selected\":false,\"text\":\"2498172061581504512\",\"value\":\"2498172061581504512\"}],\"query\":\"3267246491214659584\",\"skipUrlSync\":false,\"type\":\"textbox\"},{\"current\":{\"selected\":true,\"text\":[\"All\"],\"value\":[\"$__all\"]},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select concat(id,\'\') from sys_tag where classification_id = \'2428931245089341440\' and \\nif(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=2  ,name in ($tagNames)) and is_deleted=0\\nand  if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope=1))\\nunion\\nselect -9999999\",\"description\":\"如果tagName是all那么就不查出来\",\"hide\":2,\"includeAll\":true,\"multi\":true,\"name\":\"tagIds\",\"options\":[],\"query\":\"select concat(id,\'\') from sys_tag where classification_id = \'2428931245089341440\' and \\nif(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=2  ,name in ($tagNames)) and is_deleted=0\\nand  if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope=1))\\nunion\\nselect -9999999\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"}]},\"time\":{\"from\":\"now-30d\",\"to\":\"now\"},\"timepicker\":{},\"timezone\":\"\",\"title\":\"安徽征信DevOps运行情况\",\"uid\":\"2vpnFBgHk\",\"version\":31,\"weekStart\":\"\"}');
INSERT INTO `dashboard_version` VALUES (552, 43, 31, 0, 32, '2024-10-14 16:44:38', 40, '1', '{\"annotations\":{\"list\":[{\"builtIn\":1,\"datasource\":{\"type\":\"grafana\",\"uid\":\"-- Grafana --\"},\"enable\":true,\"hide\":true,\"iconColor\":\"rgba(0, 211, 255, 1)\",\"name\":\"Annotations \\u0026 Alerts\",\"target\":{\"limit\":100,\"matchAny\":false,\"tags\":[],\"type\":\"dashboard\"},\"type\":\"dashboard\"}]},\"description\":\"\",\"editable\":true,\"fiscalYearStartMonth\":0,\"graphTooltip\":0,\"id\":43,\"links\":[],\"liveNow\":false,\"panels\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"b-L36I-4z\"},\"gridPos\":{\"h\":19,\"w\":24,\"x\":0,\"y\":0},\"id\":35,\"options\":{\"code\":{\"language\":\"plaintext\",\"showLineNumbers\":false,\"showMiniMap\":false},\"content\":\"**报告周期：2024年第二、三季度（4月1日至9月30日）**\\r\\n\\r\\n**一、概述**\\r\\n\\r\\n第二、三季度，主要完成安徽征信的DevOps平台搭建，通过“集中培训+分批次轮训”模式完成对公司前中台人员的系统操作培训，完成了各部门存量系统开发项目迁移及新增系统开发项目接入工作，\\r\\n实现公司系统开发项目、代码仓库、制品等统一管理。协助各项目经理建立任务流水线，加强了各项目持续集成/持续部署(CI/CD)的能力，通过代码质量扫描提高了软件开发效率与产品质量。通过一系列的技术改进和服务优化，缩短系统开发迭代周期。\\r\\n\\r\\n**二、关键绩效指标(KPIs)**\\r\\n\\r\\n- **日均代码合并次数**：\\t系统上线前平均4.83，系统投产后平均8.88，提升幅度84%。\\r\\n- **日均构建次数**：\\t系统上线前平均5.8，系统投产后平均8.32，提升幅度30%。\\r\\n- **单次构建平均用时（分钟）**：\\t系统上线前平均5，系统投产后平均2.24，提升幅度\\t223%。\\r\\n- **测试环境平均部署时间（分钟）**：\\t系统上线前平均5.6，系统投产后平均0.5，提升幅度\\t1120%。\\r\\n- **执行回退需要的时间（分钟）**：\\t系统上线前平均16，系统投产后平均6.4，提升幅度\\t250%。\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n**三、主要工作**\\r\\n\\r\\n1. **完成流水线功能模块上线，实现全自动化构建、代码安全检测和测试环境部署流程，提高系统交付速度和质量，全面代码构建效率。**\\r\\n2. **完成可信源管理模块上线并持续对漏洞库进行更新，实现从项目集成、发版门禁源头堵截高危漏洞，定期从中央漏洞库拉去漏洞，在流水线中对使用到的依赖包做扫描校验，在发布前对漏洞进行拦截，确保对代码安全性；**\\r\\n3. **结合行业最佳实践，完成《代码开发规范》建设,建立统一的代码风格和质量标准，确保代码的可读性、可维护性和安全性；**\\r\\n4. **完成代码评审模块功能上线，实现代码合并审查全流程线上化，对代码修改记录实现可视化管理，流程中嵌入代码安全监测，提高代码审查效率和代码安全质量；**\\r\\n5. **完成与OA系统进行打通，实现DevOps系统用户、任务代办、项目需求通过OA系统实现移动端在线办理；2024年7月份完成在库外包厂商需求处理功能在DevOps平台上线；**\\r\\n6. **完成《效能度量2.0指标》指定，并明确各效能指标展现形式及处理逻辑；**\\r\\n7. **截止三季度末已完成59个项目接入DevOps平台，实现项目需求、计划、代码仓库、流水线、制品等统一管理；**\\r\\n\\r\\n**四、下一步规划**\\r\\n\\r\\n1. **推进微服务架构改造**：计划将部分单体应用拆分为微服务，以增强系统的灵活性和可维护性。\\r\\n2. **加强团队建设**：定期组织内部培训和技术分享会，提升团队成员的专业技能和服务意识。\\r\\n3. **探索新技术**：关注行业发展趋势，适时引入人工智能、代码开发大模型等前沿技术，为公司提供更多创新价值。\\r\\n4. **平台功能迭代升级**：及时收集平台上线后各部门使用反馈意见，促进产品持续改进。\",\"mode\":\"markdown\"},\"pluginVersion\":\"9.4.0-pre\",\"title\":\"安徽征信DevOps整体运行情况\",\"type\":\"text\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":19},\"id\":27,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select org.name as name ,\\r\\ncount(1) as 项目数量\\r\\nfrom project\\r\\nleft join yanlian_app_management.sys_organization org on tenant_id = org.id\\r\\nwhere del_flag=0  and tenant_id !=\'2498172061581504512\'\\r\\ngroup by tenant_id\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门系统开发项目统计\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":19},\"id\":29,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select o.name as \'组织名称\',count(distinct s.system_id) as \'系统\',count(distinct s.id) as \'子系统（服务）\'  \\r\\n from yanlian_devops_scm.commit_info c \\r\\n left join yanlian_devops_development.sub_system_component s on c.gitlab_id=s.component_key and s.component=\'GITLAB\'\\r\\n left join yanlian_devops_development.devops_system d on s.system_id=d.id\\r\\n left join yanlian_app_management.sys_organization o on d.tenant_id = o.id\\r\\n where 1=1 and o.name !=\'\' and o.name!=\'样板间\'\\r\\n group by o.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门系统开发子系统统计\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"green\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":9,\"w\":12,\"x\":0,\"y\":27},\"id\":23,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select\\n  org.name,\\n  count(1) as \'流水线数量\'\\nfrom\\n  devops_jenkins_job job\\n left join yanlian_app_management.sys_organization org on job.tenant = org.id\\nwhere\\n  job.del_flag = 0\\n  and job.tenant != \'\'\\ngroup by\\n  org.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门流水线总数\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":9,\"w\":12,\"x\":12,\"y\":27},\"id\":25,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select o.name as \'组织名称\' ,sum(c.total)/10000 as \'变更行数\' ,sum(c.deletions)/10000 as \'删除行数\' ,sum(c.additions)/10000 as \'新增行数\' \\r\\n from yanlian_devops_scm.commit_info c \\r\\n left join yanlian_devops_development.sub_system_component s on c.gitlab_id=s.component_key and s.component=\'GITLAB\'\\r\\n left join yanlian_devops_development.devops_system d on s.system_id=d.id\\r\\n left join yanlian_app_management.sys_organization o on d.tenant_id = o.id\\r\\n where 1=1 and o.name !=\'\' and o.name!=\'样板间\'\\r\\n group by o.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门代码贡献情况（单位万）\",\"type\":\"barchart\"},{\"gridPos\":{\"h\":10,\"w\":12,\"x\":0,\"y\":36},\"id\":33,\"libraryPanel\":{\"name\":\"公司总的流水线每月运行情况\",\"uid\":\"5cXvEImHz\"},\"title\":\"流水线构建情况\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":0,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 公共信用部\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"red\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"公共信用部（平台办）\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 科技交付中心\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"科技交付中心\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 普惠信用部\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"blue\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"普惠信用部\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 企业信用部\"},\"properties\":[{\"id\":\"displayName\",\"value\":\"企业信用部\"},{\"id\":\"color\",\"value\":{\"fixedColor\":\"orange\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":12,\"y\":36},\"id\":20,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"fields\":[{\"jsonPath\":\"\"}],\"format\":\"table\",\"hide\":false,\"method\":\"GET\",\"queryParams\":\"\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\',\\n  middle.status_name as \'metric\'\\nFROM ( select count(1) as count,i.update_time ,(case \\n  when j.tenant=\'3267282568738619392\' then \'公共信用部\'\\n  when j.tenant=\'3267284931239067648\' then \'科技交付中心\'\\n  when j.tenant=\'3267282062251245568\' then \'企业信用部\'\\n  when j.tenant=\'3267281511404912640\' then \'普惠信用部\'\\n  when j.tenant=\'3267283983108259840\' then \'创新研发中心\'\\n  else j.tenant\\nend) as status_name\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\n where i.del_flag=0 and j.tenant !=\'\' and j.del_flag=0 \\ngroup by date_format(i.update_time,\'%Y%m%d\')\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\n  group by 1,2\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"urlPath\":\"\"}],\"title\":\"各部门流水线构建情况\",\"transformations\":[{\"id\":\"prepareTimeSeries\",\"options\":{\"format\":\"multi\"}}],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"统计每日成功执行的流水线构建时长，单位：分钟\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\",\"seriesBy\":\"last\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisGridShow\":true,\"axisLabel\":\"分钟\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"bars\",\"fillOpacity\":100,\"gradientMode\":\"scheme\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"smooth\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"normal\"},\"thresholdsStyle\":{\"mode\":\"dashed\"}},\"decimals\":1,\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"#226ee7\",\"value\":null},{\"color\":\"#f34d1f\",\"value\":5}]}},\"overrides\":[]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":0,\"y\":46},\"id\":8,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.avg_time as \'时长\'\\nFROM ( \\n\\nselect _m.update_time,avg(duration) / 60 as avg_time\\nfrom (select i.update_time,(unix_timestamp(i.end_time) - unix_timestamp(i.start_time)) as duration\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\nwhere\\ni.update_time is not null and i.status=\'SUCCESS\' and i.del_flag=0\\nand job_id in(select id from devops_jenkins_job where del_flag=0 and if(\'$amp_organ_id\'=\'3267246491214659584\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')))\\norder by update_time asc\\n) as _m\\ngroup by date_format(update_time,\'%Y%m%d\')\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"devops_job_build_info\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"流水线构建平均时长\",\"transformations\":[],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":0,\"gradientMode\":\"opacity\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":7,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"never\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"失败\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#e15a33\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"成功\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#58b076\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":12,\"y\":46},\"id\":14,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"multi\",\"sort\":\"asc\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.time,1d),\\n  middle.count as \'数量\'\\nFROM (select count(1) as count,p.create_time as time\\nfrom devops_product p\\nleft join devops_repository r on p.repo_id=r.id\\nwhere p.create_time is not null \\ngroup by date_format(p.create_time, \'%Y%m%d\')\\norder by p.create_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.time)\\nORDER BY $__timeGroup(middle.time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"构建制品统计\",\"type\":\"timeseries\"}],\"refresh\":false,\"schemaVersion\":37,\"style\":\"dark\",\"tags\":[],\"templating\":{\"list\":[{\"allValue\":\"\'all\'\",\"current\":{\"selected\":true,\"text\":[\"All\"],\"value\":[\"$__all\"]},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select name from sys_tag where classification_id= 2428931245089341440 and if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope = 1)) and is_deleted=0\\nunion\\nselect \'\'\",\"description\":\"\",\"hide\":2,\"includeAll\":true,\"label\":\"标签\",\"multi\":true,\"name\":\"tagNames\",\"options\":[],\"query\":\"select name from sys_tag where classification_id= 2428931245089341440 and if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope = 1)) and is_deleted=0\\nunion\\nselect \'\'\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"},{\"current\":{\"selected\":false,\"text\":\"3267246491214659584\",\"value\":\"3267246491214659584\"},\"hide\":2,\"label\":\"amp_organ_id\",\"name\":\"amp_organ_id\",\"options\":[{\"selected\":false,\"text\":\"2498172061581504512\",\"value\":\"2498172061581504512\"}],\"query\":\"3267246491214659584\",\"skipUrlSync\":false,\"type\":\"textbox\"},{\"current\":{\"selected\":true,\"text\":[\"All\"],\"value\":[\"$__all\"]},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select concat(id,\'\') from sys_tag where classification_id = \'2428931245089341440\' and \\nif(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=2  ,name in ($tagNames)) and is_deleted=0\\nand  if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope=1))\\nunion\\nselect -9999999\",\"description\":\"如果tagName是all那么就不查出来\",\"hide\":2,\"includeAll\":true,\"multi\":true,\"name\":\"tagIds\",\"options\":[],\"query\":\"select concat(id,\'\') from sys_tag where classification_id = \'2428931245089341440\' and \\nif(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=2  ,name in ($tagNames)) and is_deleted=0\\nand  if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope=1))\\nunion\\nselect -9999999\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"}]},\"time\":{\"from\":\"now-30d\",\"to\":\"now\"},\"timepicker\":{},\"timezone\":\"\",\"title\":\"安徽征信DevOps运行情况\",\"uid\":\"2vpnFBgHk\",\"version\":32,\"weekStart\":\"\"}');
INSERT INTO `dashboard_version` VALUES (553, 43, 32, 0, 33, '2024-10-14 16:46:20', 40, '', '{\"annotations\":{\"list\":[{\"builtIn\":1,\"datasource\":{\"type\":\"grafana\",\"uid\":\"-- Grafana --\"},\"enable\":true,\"hide\":true,\"iconColor\":\"rgba(0, 211, 255, 1)\",\"name\":\"Annotations \\u0026 Alerts\",\"target\":{\"limit\":100,\"matchAny\":false,\"tags\":[],\"type\":\"dashboard\"},\"type\":\"dashboard\"}]},\"description\":\"\",\"editable\":true,\"fiscalYearStartMonth\":0,\"graphTooltip\":0,\"id\":43,\"links\":[],\"liveNow\":false,\"panels\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"left\",\"displayMode\":\"auto\",\"inspect\":false},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":6,\"w\":5,\"x\":0,\"y\":0},\"id\":37,\"options\":{\"footer\":{\"countRows\":false,\"enablePagination\":false,\"fields\":\"\",\"reducer\":[\"sum\"],\"show\":false},\"showHeader\":false},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \'代码覆盖率\' as name,avg(coverage) as count \\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\nunion\\n\\nselect \'代码重复率\' as name, avg(repetition) as count\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n\\nunion\\n\\nselect \'代码坏味道\' as name, avg(`code_smell`) as count\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n \\n union\\n select \'Bugs\' as name, avg(bug) as count \\n  from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n\\nunion\\n select \'代码得分\' as name, avg(score) as count \\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"代码扫描情况\",\"type\":\"table\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"b-L36I-4z\"},\"gridPos\":{\"h\":19,\"w\":24,\"x\":0,\"y\":6},\"id\":35,\"options\":{\"code\":{\"language\":\"plaintext\",\"showLineNumbers\":false,\"showMiniMap\":false},\"content\":\"**报告周期：2024年第二、三季度（4月1日至9月30日）**\\r\\n\\r\\n**一、概述**\\r\\n\\r\\n第二、三季度，主要完成安徽征信的DevOps平台搭建，通过“集中培训+分批次轮训”模式完成对公司前中台人员的系统操作培训，完成了各部门存量系统开发项目迁移及新增系统开发项目接入工作，\\r\\n实现公司系统开发项目、代码仓库、制品等统一管理。协助各项目经理建立任务流水线，加强了各项目持续集成/持续部署(CI/CD)的能力，通过代码质量扫描提高了软件开发效率与产品质量。通过一系列的技术改进和服务优化，缩短系统开发迭代周期。\\r\\n\\r\\n**二、关键绩效指标(KPIs)**\\r\\n\\r\\n- **日均代码合并次数**：\\t系统上线前平均4.83，系统投产后平均8.88，提升幅度84%。\\r\\n- **日均构建次数**：\\t系统上线前平均5.8，系统投产后平均8.32，提升幅度30%。\\r\\n- **单次构建平均用时（分钟）**：\\t系统上线前平均5，系统投产后平均2.24，提升幅度\\t223%。\\r\\n- **测试环境平均部署时间（分钟）**：\\t系统上线前平均5.6，系统投产后平均0.5，提升幅度\\t1120%。\\r\\n- **执行回退需要的时间（分钟）**：\\t系统上线前平均16，系统投产后平均6.4，提升幅度\\t250%。\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n**三、主要工作**\\r\\n\\r\\n1. **完成流水线功能模块上线，实现全自动化构建、代码安全检测和测试环境部署流程，提高系统交付速度和质量，全面代码构建效率。**\\r\\n2. **完成可信源管理模块上线并持续对漏洞库进行更新，实现从项目集成、发版门禁源头堵截高危漏洞，定期从中央漏洞库拉去漏洞，在流水线中对使用到的依赖包做扫描校验，在发布前对漏洞进行拦截，确保对代码安全性；**\\r\\n3. **结合行业最佳实践，完成《代码开发规范》建设,建立统一的代码风格和质量标准，确保代码的可读性、可维护性和安全性；**\\r\\n4. **完成代码评审模块功能上线，实现代码合并审查全流程线上化，对代码修改记录实现可视化管理，流程中嵌入代码安全监测，提高代码审查效率和代码安全质量；**\\r\\n5. **完成与OA系统进行打通，实现DevOps系统用户、任务代办、项目需求通过OA系统实现移动端在线办理；2024年7月份完成在库外包厂商需求处理功能在DevOps平台上线；**\\r\\n6. **完成《效能度量2.0指标》指定，并明确各效能指标展现形式及处理逻辑；**\\r\\n7. **截止三季度末已完成59个项目接入DevOps平台，实现项目需求、计划、代码仓库、流水线、制品等统一管理；**\\r\\n\\r\\n**四、下一步规划**\\r\\n\\r\\n1. **推进微服务架构改造**：计划将部分单体应用拆分为微服务，以增强系统的灵活性和可维护性。\\r\\n2. **加强团队建设**：定期组织内部培训和技术分享会，提升团队成员的专业技能和服务意识。\\r\\n3. **探索新技术**：关注行业发展趋势，适时引入人工智能、代码开发大模型等前沿技术，为公司提供更多创新价值。\\r\\n4. **平台功能迭代升级**：及时收集平台上线后各部门使用反馈意见，促进产品持续改进。\",\"mode\":\"markdown\"},\"pluginVersion\":\"9.4.0-pre\",\"title\":\"安徽征信DevOps整体运行情况\",\"type\":\"text\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":25},\"id\":27,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select org.name as name ,\\r\\ncount(1) as 项目数量\\r\\nfrom project\\r\\nleft join yanlian_app_management.sys_organization org on tenant_id = org.id\\r\\nwhere del_flag=0  and tenant_id !=\'2498172061581504512\'\\r\\ngroup by tenant_id\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门系统开发项目统计\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":25},\"id\":29,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select o.name as \'组织名称\',count(distinct s.system_id) as \'系统\',count(distinct s.id) as \'子系统（服务）\'  \\r\\n from yanlian_devops_scm.commit_info c \\r\\n left join yanlian_devops_development.sub_system_component s on c.gitlab_id=s.component_key and s.component=\'GITLAB\'\\r\\n left join yanlian_devops_development.devops_system d on s.system_id=d.id\\r\\n left join yanlian_app_management.sys_organization o on d.tenant_id = o.id\\r\\n where 1=1 and o.name !=\'\' and o.name!=\'样板间\'\\r\\n group by o.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门系统开发子系统统计\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"green\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":9,\"w\":12,\"x\":0,\"y\":33},\"id\":23,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select\\n  org.name,\\n  count(1) as \'流水线数量\'\\nfrom\\n  devops_jenkins_job job\\n left join yanlian_app_management.sys_organization org on job.tenant = org.id\\nwhere\\n  job.del_flag = 0\\n  and job.tenant != \'\'\\ngroup by\\n  org.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门流水线总数\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":9,\"w\":12,\"x\":12,\"y\":33},\"id\":25,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select o.name as \'组织名称\' ,sum(c.total)/10000 as \'变更行数\' ,sum(c.deletions)/10000 as \'删除行数\' ,sum(c.additions)/10000 as \'新增行数\' \\r\\n from yanlian_devops_scm.commit_info c \\r\\n left join yanlian_devops_development.sub_system_component s on c.gitlab_id=s.component_key and s.component=\'GITLAB\'\\r\\n left join yanlian_devops_development.devops_system d on s.system_id=d.id\\r\\n left join yanlian_app_management.sys_organization o on d.tenant_id = o.id\\r\\n where 1=1 and o.name !=\'\' and o.name!=\'样板间\'\\r\\n group by o.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门代码贡献情况（单位万）\",\"type\":\"barchart\"},{\"gridPos\":{\"h\":10,\"w\":12,\"x\":0,\"y\":42},\"id\":33,\"libraryPanel\":{\"name\":\"公司总的流水线每月运行情况\",\"uid\":\"5cXvEImHz\"},\"title\":\"流水线构建情况\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":0,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 公共信用部\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"red\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"公共信用部（平台办）\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 科技交付中心\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"科技交付中心\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 普惠信用部\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"blue\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"普惠信用部\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 企业信用部\"},\"properties\":[{\"id\":\"displayName\",\"value\":\"企业信用部\"},{\"id\":\"color\",\"value\":{\"fixedColor\":\"orange\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":12,\"y\":42},\"id\":20,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"fields\":[{\"jsonPath\":\"\"}],\"format\":\"table\",\"hide\":false,\"method\":\"GET\",\"queryParams\":\"\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\',\\n  middle.status_name as \'metric\'\\nFROM ( select count(1) as count,i.update_time ,(case \\n  when j.tenant=\'3267282568738619392\' then \'公共信用部\'\\n  when j.tenant=\'3267284931239067648\' then \'科技交付中心\'\\n  when j.tenant=\'3267282062251245568\' then \'企业信用部\'\\n  when j.tenant=\'3267281511404912640\' then \'普惠信用部\'\\n  when j.tenant=\'3267283983108259840\' then \'创新研发中心\'\\n  else j.tenant\\nend) as status_name\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\n where i.del_flag=0 and j.tenant !=\'\' and j.del_flag=0 \\ngroup by date_format(i.update_time,\'%Y%m%d\')\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\n  group by 1,2\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"urlPath\":\"\"}],\"title\":\"各部门流水线构建情况\",\"transformations\":[{\"id\":\"prepareTimeSeries\",\"options\":{\"format\":\"multi\"}}],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"统计每日成功执行的流水线构建时长，单位：分钟\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\",\"seriesBy\":\"last\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisGridShow\":true,\"axisLabel\":\"分钟\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"bars\",\"fillOpacity\":100,\"gradientMode\":\"scheme\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"smooth\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"normal\"},\"thresholdsStyle\":{\"mode\":\"dashed\"}},\"decimals\":1,\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"#226ee7\",\"value\":null},{\"color\":\"#f34d1f\",\"value\":5}]}},\"overrides\":[]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":0,\"y\":52},\"id\":8,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.avg_time as \'时长\'\\nFROM ( \\n\\nselect _m.update_time,avg(duration) / 60 as avg_time\\nfrom (select i.update_time,(unix_timestamp(i.end_time) - unix_timestamp(i.start_time)) as duration\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\nwhere\\ni.update_time is not null and i.status=\'SUCCESS\' and i.del_flag=0\\nand job_id in(select id from devops_jenkins_job where del_flag=0 and if(\'$amp_organ_id\'=\'3267246491214659584\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')))\\norder by update_time asc\\n) as _m\\ngroup by date_format(update_time,\'%Y%m%d\')\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"devops_job_build_info\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"流水线构建平均时长\",\"transformations\":[],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":0,\"gradientMode\":\"opacity\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":7,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"never\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"失败\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#e15a33\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"成功\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#58b076\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":12,\"y\":52},\"id\":14,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"multi\",\"sort\":\"asc\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.time,1d),\\n  middle.count as \'数量\'\\nFROM (select count(1) as count,p.create_time as time\\nfrom devops_product p\\nleft join devops_repository r on p.repo_id=r.id\\nwhere p.create_time is not null \\ngroup by date_format(p.create_time, \'%Y%m%d\')\\norder by p.create_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.time)\\nORDER BY $__timeGroup(middle.time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"构建制品统计\",\"type\":\"timeseries\"}],\"refresh\":false,\"schemaVersion\":37,\"style\":\"dark\",\"tags\":[],\"templating\":{\"list\":[{\"allValue\":\"\'all\'\",\"current\":{\"selected\":true,\"text\":[\"All\"],\"value\":[\"$__all\"]},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select name from sys_tag where classification_id= 2428931245089341440 and if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope = 1)) and is_deleted=0\\nunion\\nselect \'\'\",\"description\":\"\",\"hide\":2,\"includeAll\":true,\"label\":\"标签\",\"multi\":true,\"name\":\"tagNames\",\"options\":[],\"query\":\"select name from sys_tag where classification_id= 2428931245089341440 and if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope = 1)) and is_deleted=0\\nunion\\nselect \'\'\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"},{\"current\":{\"selected\":false,\"text\":\"3267246491214659584\",\"value\":\"3267246491214659584\"},\"hide\":2,\"label\":\"amp_organ_id\",\"name\":\"amp_organ_id\",\"options\":[{\"selected\":false,\"text\":\"2498172061581504512\",\"value\":\"2498172061581504512\"}],\"query\":\"3267246491214659584\",\"skipUrlSync\":false,\"type\":\"textbox\"},{\"current\":{\"selected\":true,\"text\":[\"All\"],\"value\":[\"$__all\"]},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select concat(id,\'\') from sys_tag where classification_id = \'2428931245089341440\' and \\nif(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=2  ,name in ($tagNames)) and is_deleted=0\\nand  if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope=1))\\nunion\\nselect -9999999\",\"description\":\"如果tagName是all那么就不查出来\",\"hide\":2,\"includeAll\":true,\"multi\":true,\"name\":\"tagIds\",\"options\":[],\"query\":\"select concat(id,\'\') from sys_tag where classification_id = \'2428931245089341440\' and \\nif(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=2  ,name in ($tagNames)) and is_deleted=0\\nand  if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope=1))\\nunion\\nselect -9999999\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"}]},\"time\":{\"from\":\"now-30d\",\"to\":\"now\"},\"timepicker\":{},\"timezone\":\"\",\"title\":\"安徽征信DevOps运行情况\",\"uid\":\"2vpnFBgHk\",\"version\":33,\"weekStart\":\"\"}');
INSERT INTO `dashboard_version` VALUES (554, 43, 33, 0, 34, '2024-10-14 16:46:49', 40, '', '{\"annotations\":{\"list\":[{\"builtIn\":1,\"datasource\":{\"type\":\"grafana\",\"uid\":\"-- Grafana --\"},\"enable\":true,\"hide\":true,\"iconColor\":\"rgba(0, 211, 255, 1)\",\"name\":\"Annotations \\u0026 Alerts\",\"target\":{\"limit\":100,\"matchAny\":false,\"tags\":[],\"type\":\"dashboard\"},\"type\":\"dashboard\"}]},\"description\":\"\",\"editable\":true,\"fiscalYearStartMonth\":0,\"graphTooltip\":0,\"id\":43,\"links\":[],\"liveNow\":false,\"panels\":[{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"wT7CrQa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"left\",\"displayMode\":\"auto\",\"filterable\":false,\"inspect\":false},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"val\"},\"properties\":[{\"id\":\"mappings\",\"value\":[{\"options\":{\"BLOCKER\":{\"index\":0,\"text\":\"阻断\"},\"CRITICAL\":{\"index\":1,\"text\":\"严重\"},\"INFO\":{\"index\":4,\"text\":\"轻微\"},\"MAJOR\":{\"index\":2,\"text\":\"主要\"},\"MINOR\":{\"index\":3,\"text\":\"次要\"}},\"type\":\"value\"}]}]}]},\"gridPos\":{\"h\":6,\"w\":5,\"x\":0,\"y\":0},\"id\":39,\"options\":{\"footer\":{\"countRows\":false,\"enablePagination\":false,\"fields\":\"\",\"reducer\":[\"sum\"],\"show\":false},\"frameIndex\":1,\"showHeader\":false},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"wT7CrQa4k\"},\"fields\":[{\"jsonPath\":\"$.facets[0].values[*].val\"},{\"jsonPath\":\"$.facets[0].values[*].count\",\"language\":\"jsonpath\",\"name\":\"\"}],\"method\":\"GET\",\"queryParams\":\"\",\"refId\":\"A\",\"urlPath\":\"/api/issues/search?s=FILE_LINE\\u0026resolved=false\\u0026ps=1\\u0026facets=severities\\u0026additionalFields=_all\\u0026timeZone=Asia%2FShanghai\"}],\"title\":\"存量代码问题\",\"transformations\":[{\"id\":\"sortBy\",\"options\":{\"fields\":{},\"sort\":[{\"desc\":false,\"field\":\"val\"}]}}],\"type\":\"table\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"left\",\"displayMode\":\"auto\",\"inspect\":false},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":6,\"w\":5,\"x\":5,\"y\":0},\"id\":37,\"options\":{\"footer\":{\"countRows\":false,\"enablePagination\":false,\"fields\":\"\",\"reducer\":[\"sum\"],\"show\":false},\"showHeader\":false},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \'代码覆盖率\' as name,avg(coverage) as count \\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\nunion\\n\\nselect \'代码重复率\' as name, avg(repetition) as count\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n\\nunion\\n\\nselect \'代码坏味道\' as name, avg(`code_smell`) as count\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n \\n union\\n select \'Bugs\' as name, avg(bug) as count \\n  from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n\\nunion\\n select \'代码得分\' as name, avg(score) as count \\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"代码扫描情况\",\"type\":\"table\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"b-L36I-4z\"},\"gridPos\":{\"h\":19,\"w\":24,\"x\":0,\"y\":6},\"id\":35,\"options\":{\"code\":{\"language\":\"plaintext\",\"showLineNumbers\":false,\"showMiniMap\":false},\"content\":\"**报告周期：2024年第二、三季度（4月1日至9月30日）**\\r\\n\\r\\n**一、概述**\\r\\n\\r\\n第二、三季度，主要完成安徽征信的DevOps平台搭建，通过“集中培训+分批次轮训”模式完成对公司前中台人员的系统操作培训，完成了各部门存量系统开发项目迁移及新增系统开发项目接入工作，\\r\\n实现公司系统开发项目、代码仓库、制品等统一管理。协助各项目经理建立任务流水线，加强了各项目持续集成/持续部署(CI/CD)的能力，通过代码质量扫描提高了软件开发效率与产品质量。通过一系列的技术改进和服务优化，缩短系统开发迭代周期。\\r\\n\\r\\n**二、关键绩效指标(KPIs)**\\r\\n\\r\\n- **日均代码合并次数**：\\t系统上线前平均4.83，系统投产后平均8.88，提升幅度84%。\\r\\n- **日均构建次数**：\\t系统上线前平均5.8，系统投产后平均8.32，提升幅度30%。\\r\\n- **单次构建平均用时（分钟）**：\\t系统上线前平均5，系统投产后平均2.24，提升幅度\\t223%。\\r\\n- **测试环境平均部署时间（分钟）**：\\t系统上线前平均5.6，系统投产后平均0.5，提升幅度\\t1120%。\\r\\n- **执行回退需要的时间（分钟）**：\\t系统上线前平均16，系统投产后平均6.4，提升幅度\\t250%。\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n**三、主要工作**\\r\\n\\r\\n1. **完成流水线功能模块上线，实现全自动化构建、代码安全检测和测试环境部署流程，提高系统交付速度和质量，全面代码构建效率。**\\r\\n2. **完成可信源管理模块上线并持续对漏洞库进行更新，实现从项目集成、发版门禁源头堵截高危漏洞，定期从中央漏洞库拉去漏洞，在流水线中对使用到的依赖包做扫描校验，在发布前对漏洞进行拦截，确保对代码安全性；**\\r\\n3. **结合行业最佳实践，完成《代码开发规范》建设,建立统一的代码风格和质量标准，确保代码的可读性、可维护性和安全性；**\\r\\n4. **完成代码评审模块功能上线，实现代码合并审查全流程线上化，对代码修改记录实现可视化管理，流程中嵌入代码安全监测，提高代码审查效率和代码安全质量；**\\r\\n5. **完成与OA系统进行打通，实现DevOps系统用户、任务代办、项目需求通过OA系统实现移动端在线办理；2024年7月份完成在库外包厂商需求处理功能在DevOps平台上线；**\\r\\n6. **完成《效能度量2.0指标》指定，并明确各效能指标展现形式及处理逻辑；**\\r\\n7. **截止三季度末已完成59个项目接入DevOps平台，实现项目需求、计划、代码仓库、流水线、制品等统一管理；**\\r\\n\\r\\n**四、下一步规划**\\r\\n\\r\\n1. **推进微服务架构改造**：计划将部分单体应用拆分为微服务，以增强系统的灵活性和可维护性。\\r\\n2. **加强团队建设**：定期组织内部培训和技术分享会，提升团队成员的专业技能和服务意识。\\r\\n3. **探索新技术**：关注行业发展趋势，适时引入人工智能、代码开发大模型等前沿技术，为公司提供更多创新价值。\\r\\n4. **平台功能迭代升级**：及时收集平台上线后各部门使用反馈意见，促进产品持续改进。\",\"mode\":\"markdown\"},\"pluginVersion\":\"9.4.0-pre\",\"title\":\"安徽征信DevOps整体运行情况\",\"type\":\"text\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":25},\"id\":27,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select org.name as name ,\\r\\ncount(1) as 项目数量\\r\\nfrom project\\r\\nleft join yanlian_app_management.sys_organization org on tenant_id = org.id\\r\\nwhere del_flag=0  and tenant_id !=\'2498172061581504512\'\\r\\ngroup by tenant_id\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门系统开发项目统计\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":25},\"id\":29,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select o.name as \'组织名称\',count(distinct s.system_id) as \'系统\',count(distinct s.id) as \'子系统（服务）\'  \\r\\n from yanlian_devops_scm.commit_info c \\r\\n left join yanlian_devops_development.sub_system_component s on c.gitlab_id=s.component_key and s.component=\'GITLAB\'\\r\\n left join yanlian_devops_development.devops_system d on s.system_id=d.id\\r\\n left join yanlian_app_management.sys_organization o on d.tenant_id = o.id\\r\\n where 1=1 and o.name !=\'\' and o.name!=\'样板间\'\\r\\n group by o.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门系统开发子系统统计\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"green\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":9,\"w\":12,\"x\":0,\"y\":33},\"id\":23,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select\\n  org.name,\\n  count(1) as \'流水线数量\'\\nfrom\\n  devops_jenkins_job job\\n left join yanlian_app_management.sys_organization org on job.tenant = org.id\\nwhere\\n  job.del_flag = 0\\n  and job.tenant != \'\'\\ngroup by\\n  org.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门流水线总数\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":9,\"w\":12,\"x\":12,\"y\":33},\"id\":25,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select o.name as \'组织名称\' ,sum(c.total)/10000 as \'变更行数\' ,sum(c.deletions)/10000 as \'删除行数\' ,sum(c.additions)/10000 as \'新增行数\' \\r\\n from yanlian_devops_scm.commit_info c \\r\\n left join yanlian_devops_development.sub_system_component s on c.gitlab_id=s.component_key and s.component=\'GITLAB\'\\r\\n left join yanlian_devops_development.devops_system d on s.system_id=d.id\\r\\n left join yanlian_app_management.sys_organization o on d.tenant_id = o.id\\r\\n where 1=1 and o.name !=\'\' and o.name!=\'样板间\'\\r\\n group by o.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门代码贡献情况（单位万）\",\"type\":\"barchart\"},{\"gridPos\":{\"h\":10,\"w\":12,\"x\":0,\"y\":42},\"id\":33,\"libraryPanel\":{\"name\":\"公司总的流水线每月运行情况\",\"uid\":\"5cXvEImHz\"},\"title\":\"流水线构建情况\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":0,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 公共信用部\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"red\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"公共信用部（平台办）\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 科技交付中心\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"科技交付中心\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 普惠信用部\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"blue\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"普惠信用部\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 企业信用部\"},\"properties\":[{\"id\":\"displayName\",\"value\":\"企业信用部\"},{\"id\":\"color\",\"value\":{\"fixedColor\":\"orange\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":12,\"y\":42},\"id\":20,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"fields\":[{\"jsonPath\":\"\"}],\"format\":\"table\",\"hide\":false,\"method\":\"GET\",\"queryParams\":\"\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\',\\n  middle.status_name as \'metric\'\\nFROM ( select count(1) as count,i.update_time ,(case \\n  when j.tenant=\'3267282568738619392\' then \'公共信用部\'\\n  when j.tenant=\'3267284931239067648\' then \'科技交付中心\'\\n  when j.tenant=\'3267282062251245568\' then \'企业信用部\'\\n  when j.tenant=\'3267281511404912640\' then \'普惠信用部\'\\n  when j.tenant=\'3267283983108259840\' then \'创新研发中心\'\\n  else j.tenant\\nend) as status_name\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\n where i.del_flag=0 and j.tenant !=\'\' and j.del_flag=0 \\ngroup by date_format(i.update_time,\'%Y%m%d\')\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\n  group by 1,2\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"urlPath\":\"\"}],\"title\":\"各部门流水线构建情况\",\"transformations\":[{\"id\":\"prepareTimeSeries\",\"options\":{\"format\":\"multi\"}}],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"统计每日成功执行的流水线构建时长，单位：分钟\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\",\"seriesBy\":\"last\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisGridShow\":true,\"axisLabel\":\"分钟\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"bars\",\"fillOpacity\":100,\"gradientMode\":\"scheme\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"smooth\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"normal\"},\"thresholdsStyle\":{\"mode\":\"dashed\"}},\"decimals\":1,\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"#226ee7\",\"value\":null},{\"color\":\"#f34d1f\",\"value\":5}]}},\"overrides\":[]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":0,\"y\":52},\"id\":8,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.avg_time as \'时长\'\\nFROM ( \\n\\nselect _m.update_time,avg(duration) / 60 as avg_time\\nfrom (select i.update_time,(unix_timestamp(i.end_time) - unix_timestamp(i.start_time)) as duration\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\nwhere\\ni.update_time is not null and i.status=\'SUCCESS\' and i.del_flag=0\\nand job_id in(select id from devops_jenkins_job where del_flag=0 and if(\'$amp_organ_id\'=\'3267246491214659584\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')))\\norder by update_time asc\\n) as _m\\ngroup by date_format(update_time,\'%Y%m%d\')\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"devops_job_build_info\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"流水线构建平均时长\",\"transformations\":[],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":0,\"gradientMode\":\"opacity\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":7,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"never\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"失败\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#e15a33\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"成功\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#58b076\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":12,\"y\":52},\"id\":14,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"multi\",\"sort\":\"asc\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.time,1d),\\n  middle.count as \'数量\'\\nFROM (select count(1) as count,p.create_time as time\\nfrom devops_product p\\nleft join devops_repository r on p.repo_id=r.id\\nwhere p.create_time is not null \\ngroup by date_format(p.create_time, \'%Y%m%d\')\\norder by p.create_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.time)\\nORDER BY $__timeGroup(middle.time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"构建制品统计\",\"type\":\"timeseries\"}],\"refresh\":false,\"schemaVersion\":37,\"style\":\"dark\",\"tags\":[],\"templating\":{\"list\":[{\"allValue\":\"\'all\'\",\"current\":{\"selected\":true,\"text\":[\"All\"],\"value\":[\"$__all\"]},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select name from sys_tag where classification_id= 2428931245089341440 and if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope = 1)) and is_deleted=0\\nunion\\nselect \'\'\",\"description\":\"\",\"hide\":2,\"includeAll\":true,\"label\":\"标签\",\"multi\":true,\"name\":\"tagNames\",\"options\":[],\"query\":\"select name from sys_tag where classification_id= 2428931245089341440 and if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope = 1)) and is_deleted=0\\nunion\\nselect \'\'\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"},{\"current\":{\"selected\":false,\"text\":\"3267246491214659584\",\"value\":\"3267246491214659584\"},\"hide\":2,\"label\":\"amp_organ_id\",\"name\":\"amp_organ_id\",\"options\":[{\"selected\":false,\"text\":\"2498172061581504512\",\"value\":\"2498172061581504512\"}],\"query\":\"3267246491214659584\",\"skipUrlSync\":false,\"type\":\"textbox\"},{\"current\":{\"selected\":true,\"text\":[\"All\"],\"value\":[\"$__all\"]},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select concat(id,\'\') from sys_tag where classification_id = \'2428931245089341440\' and \\nif(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=2  ,name in ($tagNames)) and is_deleted=0\\nand  if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope=1))\\nunion\\nselect -9999999\",\"description\":\"如果tagName是all那么就不查出来\",\"hide\":2,\"includeAll\":true,\"multi\":true,\"name\":\"tagIds\",\"options\":[],\"query\":\"select concat(id,\'\') from sys_tag where classification_id = \'2428931245089341440\' and \\nif(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=2  ,name in ($tagNames)) and is_deleted=0\\nand  if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope=1))\\nunion\\nselect -9999999\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"}]},\"time\":{\"from\":\"now-30d\",\"to\":\"now\"},\"timepicker\":{},\"timezone\":\"\",\"title\":\"安徽征信DevOps运行情况\",\"uid\":\"2vpnFBgHk\",\"version\":34,\"weekStart\":\"\"}');
INSERT INTO `dashboard_version` VALUES (555, 43, 34, 0, 35, '2024-10-14 16:47:14', 40, '', '{\"annotations\":{\"list\":[{\"builtIn\":1,\"datasource\":{\"type\":\"grafana\",\"uid\":\"-- Grafana --\"},\"enable\":true,\"hide\":true,\"iconColor\":\"rgba(0, 211, 255, 1)\",\"name\":\"Annotations \\u0026 Alerts\",\"target\":{\"limit\":100,\"matchAny\":false,\"tags\":[],\"type\":\"dashboard\"},\"type\":\"dashboard\"}]},\"description\":\"\",\"editable\":true,\"fiscalYearStartMonth\":0,\"graphTooltip\":0,\"id\":43,\"links\":[],\"liveNow\":false,\"panels\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"J2rj6S-4z\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false}},\"decimals\":0,\"mappings\":[],\"unit\":\"none\"},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"可信\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"严重\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#AD0317\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"高危\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#f5252f\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"中危\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"orange\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"低位\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"yellow\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"低危\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"yellow\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":6,\"w\":5,\"x\":0,\"y\":0},\"id\":41,\"options\":{\"displayLabels\":[],\"legend\":{\"displayMode\":\"table\",\"placement\":\"right\",\"showLegend\":true,\"values\":[\"value\"]},\"pieType\":\"donut\",\"reduceOptions\":{\"calcs\":[],\"fields\":\"/^num$/\",\"values\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"J2rj6S-4z\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \\n(CASE\\n   WHEN severity = \\\"CRITICAL\\\" THEN \'严重\'\\n   WHEN severity = \\\"HIGH\\\" THEN \'高危\'\\n   WHEN severity = \\\"MEDIUM\\\" THEN \'中危\'\\n   WHEN severity = \\\"LOW\\\" THEN \'低危\'\\n   WHEN severity = \\\"可信\\\" THEN \'可信\'\\n\\n   end) as s,\\n   num\\n  from (\\nSELECT\\n        (CASE\\n        WHEN LEAK_SEVERITY_V3 = \\\"CRITICAL\\\" THEN \\\"CRITICAL\\\"\\n        WHEN LEAK_SEVERITY_V3 = \\\"HIGH\\\" THEN \\\"HIGH\\\"\\n        WHEN LEAK_SEVERITY_V3 = \\\"MEDIUM\\\" THEN \\\"MEDIUM\\\"\\n        ELSE \\\"LOW\\\"\\n        END) AS severity,\\n        COUNT(*) AS num\\n        FROM `devops_leak`\\n        WHERE\\n        ID IN (SELECT DISTINCT LEAK_ID FROM `devops_leak_dp_relation` WHERE DP_DETAIL_ID IN (SELECT DP_DETAIL_ID FROM `devops_app_dp_relation` WHERE APP_HISTORY_ID in (select h.id\\nfrom devops_app app left join devops_app_scan_history h on app.id = h.app_id\\nwhere h.del_flag=0\\ngroup by h.app_id\\n)))\\n        GROUP BY severity) m\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"漏洞等级安全分布\",\"transformations\":[],\"type\":\"piechart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"left\",\"displayMode\":\"auto\",\"inspect\":false},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":6,\"w\":5,\"x\":5,\"y\":0},\"id\":37,\"options\":{\"footer\":{\"countRows\":false,\"enablePagination\":false,\"fields\":\"\",\"reducer\":[\"sum\"],\"show\":false},\"showHeader\":false},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \'代码覆盖率\' as name,avg(coverage) as count \\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\nunion\\n\\nselect \'代码重复率\' as name, avg(repetition) as count\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n\\nunion\\n\\nselect \'代码坏味道\' as name, avg(`code_smell`) as count\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n \\n union\\n select \'Bugs\' as name, avg(bug) as count \\n  from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n\\nunion\\n select \'代码得分\' as name, avg(score) as count \\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"代码扫描情况\",\"type\":\"table\"},{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"wT7CrQa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"left\",\"displayMode\":\"auto\",\"filterable\":false,\"inspect\":false},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"val\"},\"properties\":[{\"id\":\"mappings\",\"value\":[{\"options\":{\"BLOCKER\":{\"index\":0,\"text\":\"阻断\"},\"CRITICAL\":{\"index\":1,\"text\":\"严重\"},\"INFO\":{\"index\":4,\"text\":\"轻微\"},\"MAJOR\":{\"index\":2,\"text\":\"主要\"},\"MINOR\":{\"index\":3,\"text\":\"次要\"}},\"type\":\"value\"}]}]}]},\"gridPos\":{\"h\":6,\"w\":5,\"x\":0,\"y\":6},\"id\":39,\"options\":{\"footer\":{\"countRows\":false,\"enablePagination\":false,\"fields\":\"\",\"reducer\":[\"sum\"],\"show\":false},\"frameIndex\":1,\"showHeader\":false},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"wT7CrQa4k\"},\"fields\":[{\"jsonPath\":\"$.facets[0].values[*].val\"},{\"jsonPath\":\"$.facets[0].values[*].count\",\"language\":\"jsonpath\",\"name\":\"\"}],\"method\":\"GET\",\"queryParams\":\"\",\"refId\":\"A\",\"urlPath\":\"/api/issues/search?s=FILE_LINE\\u0026resolved=false\\u0026ps=1\\u0026facets=severities\\u0026additionalFields=_all\\u0026timeZone=Asia%2FShanghai\"}],\"title\":\"存量代码问题\",\"transformations\":[{\"id\":\"sortBy\",\"options\":{\"fields\":{},\"sort\":[{\"desc\":false,\"field\":\"val\"}]}}],\"type\":\"table\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"b-L36I-4z\"},\"gridPos\":{\"h\":19,\"w\":24,\"x\":0,\"y\":12},\"id\":35,\"options\":{\"code\":{\"language\":\"plaintext\",\"showLineNumbers\":false,\"showMiniMap\":false},\"content\":\"**报告周期：2024年第二、三季度（4月1日至9月30日）**\\r\\n\\r\\n**一、概述**\\r\\n\\r\\n第二、三季度，主要完成安徽征信的DevOps平台搭建，通过“集中培训+分批次轮训”模式完成对公司前中台人员的系统操作培训，完成了各部门存量系统开发项目迁移及新增系统开发项目接入工作，\\r\\n实现公司系统开发项目、代码仓库、制品等统一管理。协助各项目经理建立任务流水线，加强了各项目持续集成/持续部署(CI/CD)的能力，通过代码质量扫描提高了软件开发效率与产品质量。通过一系列的技术改进和服务优化，缩短系统开发迭代周期。\\r\\n\\r\\n**二、关键绩效指标(KPIs)**\\r\\n\\r\\n- **日均代码合并次数**：\\t系统上线前平均4.83，系统投产后平均8.88，提升幅度84%。\\r\\n- **日均构建次数**：\\t系统上线前平均5.8，系统投产后平均8.32，提升幅度30%。\\r\\n- **单次构建平均用时（分钟）**：\\t系统上线前平均5，系统投产后平均2.24，提升幅度\\t223%。\\r\\n- **测试环境平均部署时间（分钟）**：\\t系统上线前平均5.6，系统投产后平均0.5，提升幅度\\t1120%。\\r\\n- **执行回退需要的时间（分钟）**：\\t系统上线前平均16，系统投产后平均6.4，提升幅度\\t250%。\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n**三、主要工作**\\r\\n\\r\\n1. **完成流水线功能模块上线，实现全自动化构建、代码安全检测和测试环境部署流程，提高系统交付速度和质量，全面代码构建效率。**\\r\\n2. **完成可信源管理模块上线并持续对漏洞库进行更新，实现从项目集成、发版门禁源头堵截高危漏洞，定期从中央漏洞库拉去漏洞，在流水线中对使用到的依赖包做扫描校验，在发布前对漏洞进行拦截，确保对代码安全性；**\\r\\n3. **结合行业最佳实践，完成《代码开发规范》建设,建立统一的代码风格和质量标准，确保代码的可读性、可维护性和安全性；**\\r\\n4. **完成代码评审模块功能上线，实现代码合并审查全流程线上化，对代码修改记录实现可视化管理，流程中嵌入代码安全监测，提高代码审查效率和代码安全质量；**\\r\\n5. **完成与OA系统进行打通，实现DevOps系统用户、任务代办、项目需求通过OA系统实现移动端在线办理；2024年7月份完成在库外包厂商需求处理功能在DevOps平台上线；**\\r\\n6. **完成《效能度量2.0指标》指定，并明确各效能指标展现形式及处理逻辑；**\\r\\n7. **截止三季度末已完成59个项目接入DevOps平台，实现项目需求、计划、代码仓库、流水线、制品等统一管理；**\\r\\n\\r\\n**四、下一步规划**\\r\\n\\r\\n1. **推进微服务架构改造**：计划将部分单体应用拆分为微服务，以增强系统的灵活性和可维护性。\\r\\n2. **加强团队建设**：定期组织内部培训和技术分享会，提升团队成员的专业技能和服务意识。\\r\\n3. **探索新技术**：关注行业发展趋势，适时引入人工智能、代码开发大模型等前沿技术，为公司提供更多创新价值。\\r\\n4. **平台功能迭代升级**：及时收集平台上线后各部门使用反馈意见，促进产品持续改进。\",\"mode\":\"markdown\"},\"pluginVersion\":\"9.4.0-pre\",\"title\":\"安徽征信DevOps整体运行情况\",\"type\":\"text\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":31},\"id\":27,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select org.name as name ,\\r\\ncount(1) as 项目数量\\r\\nfrom project\\r\\nleft join yanlian_app_management.sys_organization org on tenant_id = org.id\\r\\nwhere del_flag=0  and tenant_id !=\'2498172061581504512\'\\r\\ngroup by tenant_id\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门系统开发项目统计\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":31},\"id\":29,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select o.name as \'组织名称\',count(distinct s.system_id) as \'系统\',count(distinct s.id) as \'子系统（服务）\'  \\r\\n from yanlian_devops_scm.commit_info c \\r\\n left join yanlian_devops_development.sub_system_component s on c.gitlab_id=s.component_key and s.component=\'GITLAB\'\\r\\n left join yanlian_devops_development.devops_system d on s.system_id=d.id\\r\\n left join yanlian_app_management.sys_organization o on d.tenant_id = o.id\\r\\n where 1=1 and o.name !=\'\' and o.name!=\'样板间\'\\r\\n group by o.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门系统开发子系统统计\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"green\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":9,\"w\":12,\"x\":0,\"y\":39},\"id\":23,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select\\n  org.name,\\n  count(1) as \'流水线数量\'\\nfrom\\n  devops_jenkins_job job\\n left join yanlian_app_management.sys_organization org on job.tenant = org.id\\nwhere\\n  job.del_flag = 0\\n  and job.tenant != \'\'\\ngroup by\\n  org.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门流水线总数\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":9,\"w\":12,\"x\":12,\"y\":39},\"id\":25,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select o.name as \'组织名称\' ,sum(c.total)/10000 as \'变更行数\' ,sum(c.deletions)/10000 as \'删除行数\' ,sum(c.additions)/10000 as \'新增行数\' \\r\\n from yanlian_devops_scm.commit_info c \\r\\n left join yanlian_devops_development.sub_system_component s on c.gitlab_id=s.component_key and s.component=\'GITLAB\'\\r\\n left join yanlian_devops_development.devops_system d on s.system_id=d.id\\r\\n left join yanlian_app_management.sys_organization o on d.tenant_id = o.id\\r\\n where 1=1 and o.name !=\'\' and o.name!=\'样板间\'\\r\\n group by o.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门代码贡献情况（单位万）\",\"type\":\"barchart\"},{\"gridPos\":{\"h\":10,\"w\":12,\"x\":0,\"y\":48},\"id\":33,\"libraryPanel\":{\"name\":\"公司总的流水线每月运行情况\",\"uid\":\"5cXvEImHz\"},\"title\":\"流水线构建情况\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":0,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 公共信用部\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"red\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"公共信用部（平台办）\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 科技交付中心\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"科技交付中心\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 普惠信用部\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"blue\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"普惠信用部\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 企业信用部\"},\"properties\":[{\"id\":\"displayName\",\"value\":\"企业信用部\"},{\"id\":\"color\",\"value\":{\"fixedColor\":\"orange\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":12,\"y\":48},\"id\":20,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"fields\":[{\"jsonPath\":\"\"}],\"format\":\"table\",\"hide\":false,\"method\":\"GET\",\"queryParams\":\"\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\',\\n  middle.status_name as \'metric\'\\nFROM ( select count(1) as count,i.update_time ,(case \\n  when j.tenant=\'3267282568738619392\' then \'公共信用部\'\\n  when j.tenant=\'3267284931239067648\' then \'科技交付中心\'\\n  when j.tenant=\'3267282062251245568\' then \'企业信用部\'\\n  when j.tenant=\'3267281511404912640\' then \'普惠信用部\'\\n  when j.tenant=\'3267283983108259840\' then \'创新研发中心\'\\n  else j.tenant\\nend) as status_name\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\n where i.del_flag=0 and j.tenant !=\'\' and j.del_flag=0 \\ngroup by date_format(i.update_time,\'%Y%m%d\')\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\n  group by 1,2\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"urlPath\":\"\"}],\"title\":\"各部门流水线构建情况\",\"transformations\":[{\"id\":\"prepareTimeSeries\",\"options\":{\"format\":\"multi\"}}],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"统计每日成功执行的流水线构建时长，单位：分钟\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\",\"seriesBy\":\"last\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisGridShow\":true,\"axisLabel\":\"分钟\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"bars\",\"fillOpacity\":100,\"gradientMode\":\"scheme\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"smooth\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"normal\"},\"thresholdsStyle\":{\"mode\":\"dashed\"}},\"decimals\":1,\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"#226ee7\",\"value\":null},{\"color\":\"#f34d1f\",\"value\":5}]}},\"overrides\":[]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":0,\"y\":58},\"id\":8,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.avg_time as \'时长\'\\nFROM ( \\n\\nselect _m.update_time,avg(duration) / 60 as avg_time\\nfrom (select i.update_time,(unix_timestamp(i.end_time) - unix_timestamp(i.start_time)) as duration\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\nwhere\\ni.update_time is not null and i.status=\'SUCCESS\' and i.del_flag=0\\nand job_id in(select id from devops_jenkins_job where del_flag=0 and if(\'$amp_organ_id\'=\'3267246491214659584\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')))\\norder by update_time asc\\n) as _m\\ngroup by date_format(update_time,\'%Y%m%d\')\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"devops_job_build_info\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"流水线构建平均时长\",\"transformations\":[],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":0,\"gradientMode\":\"opacity\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":7,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"never\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"失败\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#e15a33\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"成功\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#58b076\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":12,\"y\":58},\"id\":14,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"multi\",\"sort\":\"asc\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.time,1d),\\n  middle.count as \'数量\'\\nFROM (select count(1) as count,p.create_time as time\\nfrom devops_product p\\nleft join devops_repository r on p.repo_id=r.id\\nwhere p.create_time is not null \\ngroup by date_format(p.create_time, \'%Y%m%d\')\\norder by p.create_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.time)\\nORDER BY $__timeGroup(middle.time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"构建制品统计\",\"type\":\"timeseries\"}],\"refresh\":false,\"schemaVersion\":37,\"style\":\"dark\",\"tags\":[],\"templating\":{\"list\":[{\"allValue\":\"\'all\'\",\"current\":{\"selected\":true,\"text\":[\"All\"],\"value\":[\"$__all\"]},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select name from sys_tag where classification_id= 2428931245089341440 and if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope = 1)) and is_deleted=0\\nunion\\nselect \'\'\",\"description\":\"\",\"hide\":2,\"includeAll\":true,\"label\":\"标签\",\"multi\":true,\"name\":\"tagNames\",\"options\":[],\"query\":\"select name from sys_tag where classification_id= 2428931245089341440 and if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope = 1)) and is_deleted=0\\nunion\\nselect \'\'\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"},{\"current\":{\"selected\":false,\"text\":\"3267246491214659584\",\"value\":\"3267246491214659584\"},\"hide\":2,\"label\":\"amp_organ_id\",\"name\":\"amp_organ_id\",\"options\":[{\"selected\":false,\"text\":\"2498172061581504512\",\"value\":\"2498172061581504512\"}],\"query\":\"3267246491214659584\",\"skipUrlSync\":false,\"type\":\"textbox\"},{\"current\":{\"selected\":true,\"text\":[\"All\"],\"value\":[\"$__all\"]},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select concat(id,\'\') from sys_tag where classification_id = \'2428931245089341440\' and \\nif(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=2  ,name in ($tagNames)) and is_deleted=0\\nand  if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope=1))\\nunion\\nselect -9999999\",\"description\":\"如果tagName是all那么就不查出来\",\"hide\":2,\"includeAll\":true,\"multi\":true,\"name\":\"tagIds\",\"options\":[],\"query\":\"select concat(id,\'\') from sys_tag where classification_id = \'2428931245089341440\' and \\nif(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=2  ,name in ($tagNames)) and is_deleted=0\\nand  if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope=1))\\nunion\\nselect -9999999\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"}]},\"time\":{\"from\":\"now-30d\",\"to\":\"now\"},\"timepicker\":{},\"timezone\":\"\",\"title\":\"安徽征信DevOps运行情况\",\"uid\":\"2vpnFBgHk\",\"version\":35,\"weekStart\":\"\"}');
INSERT INTO `dashboard_version` VALUES (556, 43, 35, 0, 36, '2024-10-14 16:47:38', 40, '', '{\"annotations\":{\"list\":[{\"builtIn\":1,\"datasource\":{\"type\":\"grafana\",\"uid\":\"-- Grafana --\"},\"enable\":true,\"hide\":true,\"iconColor\":\"rgba(0, 211, 255, 1)\",\"name\":\"Annotations \\u0026 Alerts\",\"target\":{\"limit\":100,\"matchAny\":false,\"tags\":[],\"type\":\"dashboard\"},\"type\":\"dashboard\"}]},\"description\":\"\",\"editable\":true,\"fiscalYearStartMonth\":0,\"graphTooltip\":0,\"id\":43,\"links\":[],\"liveNow\":false,\"panels\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"max\":100,\"min\":0,\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"#ffb71f\",\"value\":null}]},\"unit\":\"percent\"},\"overrides\":[]},\"gridPos\":{\"h\":6,\"w\":5,\"x\":0,\"y\":0},\"id\":43,\"options\":{\"orientation\":\"auto\",\"reduceOptions\":{\"calcs\":[],\"fields\":\"\",\"values\":true},\"showThresholdLabels\":false,\"showThresholdMarkers\":false,\"text\":{}},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select ((select count(h.`vulnerability`)\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and h.`vulnerability` = 0 and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n order by h.create_time desc) / (select count(h.`vulnerability`)\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n order by h.create_time desc)) * 100\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"代码仓库质量通过率\",\"transformations\":[],\"type\":\"gauge\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"left\",\"displayMode\":\"auto\",\"inspect\":false},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":6,\"w\":5,\"x\":5,\"y\":0},\"id\":37,\"options\":{\"footer\":{\"countRows\":false,\"enablePagination\":false,\"fields\":\"\",\"reducer\":[\"sum\"],\"show\":false},\"showHeader\":false},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \'代码覆盖率\' as name,avg(coverage) as count \\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\nunion\\n\\nselect \'代码重复率\' as name, avg(repetition) as count\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n\\nunion\\n\\nselect \'代码坏味道\' as name, avg(`code_smell`) as count\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n \\n union\\n select \'Bugs\' as name, avg(bug) as count \\n  from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n\\nunion\\n select \'代码得分\' as name, avg(score) as count \\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"代码扫描情况\",\"type\":\"table\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"J2rj6S-4z\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false}},\"decimals\":0,\"mappings\":[],\"unit\":\"none\"},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"可信\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"严重\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#AD0317\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"高危\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#f5252f\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"中危\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"orange\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"低位\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"yellow\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"低危\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"yellow\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":6,\"w\":5,\"x\":0,\"y\":6},\"id\":41,\"options\":{\"displayLabels\":[],\"legend\":{\"displayMode\":\"table\",\"placement\":\"right\",\"showLegend\":true,\"values\":[\"value\"]},\"pieType\":\"donut\",\"reduceOptions\":{\"calcs\":[],\"fields\":\"/^num$/\",\"values\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"J2rj6S-4z\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \\n(CASE\\n   WHEN severity = \\\"CRITICAL\\\" THEN \'严重\'\\n   WHEN severity = \\\"HIGH\\\" THEN \'高危\'\\n   WHEN severity = \\\"MEDIUM\\\" THEN \'中危\'\\n   WHEN severity = \\\"LOW\\\" THEN \'低危\'\\n   WHEN severity = \\\"可信\\\" THEN \'可信\'\\n\\n   end) as s,\\n   num\\n  from (\\nSELECT\\n        (CASE\\n        WHEN LEAK_SEVERITY_V3 = \\\"CRITICAL\\\" THEN \\\"CRITICAL\\\"\\n        WHEN LEAK_SEVERITY_V3 = \\\"HIGH\\\" THEN \\\"HIGH\\\"\\n        WHEN LEAK_SEVERITY_V3 = \\\"MEDIUM\\\" THEN \\\"MEDIUM\\\"\\n        ELSE \\\"LOW\\\"\\n        END) AS severity,\\n        COUNT(*) AS num\\n        FROM `devops_leak`\\n        WHERE\\n        ID IN (SELECT DISTINCT LEAK_ID FROM `devops_leak_dp_relation` WHERE DP_DETAIL_ID IN (SELECT DP_DETAIL_ID FROM `devops_app_dp_relation` WHERE APP_HISTORY_ID in (select h.id\\nfrom devops_app app left join devops_app_scan_history h on app.id = h.app_id\\nwhere h.del_flag=0\\ngroup by h.app_id\\n)))\\n        GROUP BY severity) m\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"漏洞等级安全分布\",\"transformations\":[],\"type\":\"piechart\"},{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"wT7CrQa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"left\",\"displayMode\":\"auto\",\"filterable\":false,\"inspect\":false},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"val\"},\"properties\":[{\"id\":\"mappings\",\"value\":[{\"options\":{\"BLOCKER\":{\"index\":0,\"text\":\"阻断\"},\"CRITICAL\":{\"index\":1,\"text\":\"严重\"},\"INFO\":{\"index\":4,\"text\":\"轻微\"},\"MAJOR\":{\"index\":2,\"text\":\"主要\"},\"MINOR\":{\"index\":3,\"text\":\"次要\"}},\"type\":\"value\"}]}]}]},\"gridPos\":{\"h\":6,\"w\":5,\"x\":0,\"y\":12},\"id\":39,\"options\":{\"footer\":{\"countRows\":false,\"enablePagination\":false,\"fields\":\"\",\"reducer\":[\"sum\"],\"show\":false},\"frameIndex\":1,\"showHeader\":false},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"wT7CrQa4k\"},\"fields\":[{\"jsonPath\":\"$.facets[0].values[*].val\"},{\"jsonPath\":\"$.facets[0].values[*].count\",\"language\":\"jsonpath\",\"name\":\"\"}],\"method\":\"GET\",\"queryParams\":\"\",\"refId\":\"A\",\"urlPath\":\"/api/issues/search?s=FILE_LINE\\u0026resolved=false\\u0026ps=1\\u0026facets=severities\\u0026additionalFields=_all\\u0026timeZone=Asia%2FShanghai\"}],\"title\":\"存量代码问题\",\"transformations\":[{\"id\":\"sortBy\",\"options\":{\"fields\":{},\"sort\":[{\"desc\":false,\"field\":\"val\"}]}}],\"type\":\"table\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"b-L36I-4z\"},\"gridPos\":{\"h\":19,\"w\":24,\"x\":0,\"y\":18},\"id\":35,\"options\":{\"code\":{\"language\":\"plaintext\",\"showLineNumbers\":false,\"showMiniMap\":false},\"content\":\"**报告周期：2024年第二、三季度（4月1日至9月30日）**\\r\\n\\r\\n**一、概述**\\r\\n\\r\\n第二、三季度，主要完成安徽征信的DevOps平台搭建，通过“集中培训+分批次轮训”模式完成对公司前中台人员的系统操作培训，完成了各部门存量系统开发项目迁移及新增系统开发项目接入工作，\\r\\n实现公司系统开发项目、代码仓库、制品等统一管理。协助各项目经理建立任务流水线，加强了各项目持续集成/持续部署(CI/CD)的能力，通过代码质量扫描提高了软件开发效率与产品质量。通过一系列的技术改进和服务优化，缩短系统开发迭代周期。\\r\\n\\r\\n**二、关键绩效指标(KPIs)**\\r\\n\\r\\n- **日均代码合并次数**：\\t系统上线前平均4.83，系统投产后平均8.88，提升幅度84%。\\r\\n- **日均构建次数**：\\t系统上线前平均5.8，系统投产后平均8.32，提升幅度30%。\\r\\n- **单次构建平均用时（分钟）**：\\t系统上线前平均5，系统投产后平均2.24，提升幅度\\t223%。\\r\\n- **测试环境平均部署时间（分钟）**：\\t系统上线前平均5.6，系统投产后平均0.5，提升幅度\\t1120%。\\r\\n- **执行回退需要的时间（分钟）**：\\t系统上线前平均16，系统投产后平均6.4，提升幅度\\t250%。\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n**三、主要工作**\\r\\n\\r\\n1. **完成流水线功能模块上线，实现全自动化构建、代码安全检测和测试环境部署流程，提高系统交付速度和质量，全面代码构建效率。**\\r\\n2. **完成可信源管理模块上线并持续对漏洞库进行更新，实现从项目集成、发版门禁源头堵截高危漏洞，定期从中央漏洞库拉去漏洞，在流水线中对使用到的依赖包做扫描校验，在发布前对漏洞进行拦截，确保对代码安全性；**\\r\\n3. **结合行业最佳实践，完成《代码开发规范》建设,建立统一的代码风格和质量标准，确保代码的可读性、可维护性和安全性；**\\r\\n4. **完成代码评审模块功能上线，实现代码合并审查全流程线上化，对代码修改记录实现可视化管理，流程中嵌入代码安全监测，提高代码审查效率和代码安全质量；**\\r\\n5. **完成与OA系统进行打通，实现DevOps系统用户、任务代办、项目需求通过OA系统实现移动端在线办理；2024年7月份完成在库外包厂商需求处理功能在DevOps平台上线；**\\r\\n6. **完成《效能度量2.0指标》指定，并明确各效能指标展现形式及处理逻辑；**\\r\\n7. **截止三季度末已完成59个项目接入DevOps平台，实现项目需求、计划、代码仓库、流水线、制品等统一管理；**\\r\\n\\r\\n**四、下一步规划**\\r\\n\\r\\n1. **推进微服务架构改造**：计划将部分单体应用拆分为微服务，以增强系统的灵活性和可维护性。\\r\\n2. **加强团队建设**：定期组织内部培训和技术分享会，提升团队成员的专业技能和服务意识。\\r\\n3. **探索新技术**：关注行业发展趋势，适时引入人工智能、代码开发大模型等前沿技术，为公司提供更多创新价值。\\r\\n4. **平台功能迭代升级**：及时收集平台上线后各部门使用反馈意见，促进产品持续改进。\",\"mode\":\"markdown\"},\"pluginVersion\":\"9.4.0-pre\",\"title\":\"安徽征信DevOps整体运行情况\",\"type\":\"text\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":37},\"id\":27,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select org.name as name ,\\r\\ncount(1) as 项目数量\\r\\nfrom project\\r\\nleft join yanlian_app_management.sys_organization org on tenant_id = org.id\\r\\nwhere del_flag=0  and tenant_id !=\'2498172061581504512\'\\r\\ngroup by tenant_id\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门系统开发项目统计\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":37},\"id\":29,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select o.name as \'组织名称\',count(distinct s.system_id) as \'系统\',count(distinct s.id) as \'子系统（服务）\'  \\r\\n from yanlian_devops_scm.commit_info c \\r\\n left join yanlian_devops_development.sub_system_component s on c.gitlab_id=s.component_key and s.component=\'GITLAB\'\\r\\n left join yanlian_devops_development.devops_system d on s.system_id=d.id\\r\\n left join yanlian_app_management.sys_organization o on d.tenant_id = o.id\\r\\n where 1=1 and o.name !=\'\' and o.name!=\'样板间\'\\r\\n group by o.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门系统开发子系统统计\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"green\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":9,\"w\":12,\"x\":0,\"y\":45},\"id\":23,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select\\n  org.name,\\n  count(1) as \'流水线数量\'\\nfrom\\n  devops_jenkins_job job\\n left join yanlian_app_management.sys_organization org on job.tenant = org.id\\nwhere\\n  job.del_flag = 0\\n  and job.tenant != \'\'\\ngroup by\\n  org.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门流水线总数\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":9,\"w\":12,\"x\":12,\"y\":45},\"id\":25,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select o.name as \'组织名称\' ,sum(c.total)/10000 as \'变更行数\' ,sum(c.deletions)/10000 as \'删除行数\' ,sum(c.additions)/10000 as \'新增行数\' \\r\\n from yanlian_devops_scm.commit_info c \\r\\n left join yanlian_devops_development.sub_system_component s on c.gitlab_id=s.component_key and s.component=\'GITLAB\'\\r\\n left join yanlian_devops_development.devops_system d on s.system_id=d.id\\r\\n left join yanlian_app_management.sys_organization o on d.tenant_id = o.id\\r\\n where 1=1 and o.name !=\'\' and o.name!=\'样板间\'\\r\\n group by o.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门代码贡献情况（单位万）\",\"type\":\"barchart\"},{\"gridPos\":{\"h\":10,\"w\":12,\"x\":0,\"y\":54},\"id\":33,\"libraryPanel\":{\"name\":\"公司总的流水线每月运行情况\",\"uid\":\"5cXvEImHz\"},\"title\":\"流水线构建情况\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":0,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 公共信用部\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"red\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"公共信用部（平台办）\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 科技交付中心\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"科技交付中心\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 普惠信用部\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"blue\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"普惠信用部\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 企业信用部\"},\"properties\":[{\"id\":\"displayName\",\"value\":\"企业信用部\"},{\"id\":\"color\",\"value\":{\"fixedColor\":\"orange\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":12,\"y\":54},\"id\":20,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"fields\":[{\"jsonPath\":\"\"}],\"format\":\"table\",\"hide\":false,\"method\":\"GET\",\"queryParams\":\"\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\',\\n  middle.status_name as \'metric\'\\nFROM ( select count(1) as count,i.update_time ,(case \\n  when j.tenant=\'3267282568738619392\' then \'公共信用部\'\\n  when j.tenant=\'3267284931239067648\' then \'科技交付中心\'\\n  when j.tenant=\'3267282062251245568\' then \'企业信用部\'\\n  when j.tenant=\'3267281511404912640\' then \'普惠信用部\'\\n  when j.tenant=\'3267283983108259840\' then \'创新研发中心\'\\n  else j.tenant\\nend) as status_name\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\n where i.del_flag=0 and j.tenant !=\'\' and j.del_flag=0 \\ngroup by date_format(i.update_time,\'%Y%m%d\')\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\n  group by 1,2\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"urlPath\":\"\"}],\"title\":\"各部门流水线构建情况\",\"transformations\":[{\"id\":\"prepareTimeSeries\",\"options\":{\"format\":\"multi\"}}],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"统计每日成功执行的流水线构建时长，单位：分钟\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\",\"seriesBy\":\"last\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisGridShow\":true,\"axisLabel\":\"分钟\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"bars\",\"fillOpacity\":100,\"gradientMode\":\"scheme\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"smooth\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"normal\"},\"thresholdsStyle\":{\"mode\":\"dashed\"}},\"decimals\":1,\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"#226ee7\",\"value\":null},{\"color\":\"#f34d1f\",\"value\":5}]}},\"overrides\":[]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":0,\"y\":64},\"id\":8,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.avg_time as \'时长\'\\nFROM ( \\n\\nselect _m.update_time,avg(duration) / 60 as avg_time\\nfrom (select i.update_time,(unix_timestamp(i.end_time) - unix_timestamp(i.start_time)) as duration\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\nwhere\\ni.update_time is not null and i.status=\'SUCCESS\' and i.del_flag=0\\nand job_id in(select id from devops_jenkins_job where del_flag=0 and if(\'$amp_organ_id\'=\'3267246491214659584\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')))\\norder by update_time asc\\n) as _m\\ngroup by date_format(update_time,\'%Y%m%d\')\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"devops_job_build_info\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"流水线构建平均时长\",\"transformations\":[],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":0,\"gradientMode\":\"opacity\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":7,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"never\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"失败\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#e15a33\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"成功\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#58b076\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":12,\"y\":64},\"id\":14,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"multi\",\"sort\":\"asc\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.time,1d),\\n  middle.count as \'数量\'\\nFROM (select count(1) as count,p.create_time as time\\nfrom devops_product p\\nleft join devops_repository r on p.repo_id=r.id\\nwhere p.create_time is not null \\ngroup by date_format(p.create_time, \'%Y%m%d\')\\norder by p.create_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.time)\\nORDER BY $__timeGroup(middle.time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"构建制品统计\",\"type\":\"timeseries\"}],\"refresh\":false,\"schemaVersion\":37,\"style\":\"dark\",\"tags\":[],\"templating\":{\"list\":[{\"allValue\":\"\'all\'\",\"current\":{\"selected\":true,\"text\":[\"All\"],\"value\":[\"$__all\"]},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select name from sys_tag where classification_id= 2428931245089341440 and if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope = 1)) and is_deleted=0\\nunion\\nselect \'\'\",\"description\":\"\",\"hide\":2,\"includeAll\":true,\"label\":\"标签\",\"multi\":true,\"name\":\"tagNames\",\"options\":[],\"query\":\"select name from sys_tag where classification_id= 2428931245089341440 and if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope = 1)) and is_deleted=0\\nunion\\nselect \'\'\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"},{\"current\":{\"selected\":false,\"text\":\"3267246491214659584\",\"value\":\"3267246491214659584\"},\"hide\":2,\"label\":\"amp_organ_id\",\"name\":\"amp_organ_id\",\"options\":[{\"selected\":false,\"text\":\"2498172061581504512\",\"value\":\"2498172061581504512\"}],\"query\":\"3267246491214659584\",\"skipUrlSync\":false,\"type\":\"textbox\"},{\"current\":{\"selected\":true,\"text\":[\"All\"],\"value\":[\"$__all\"]},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select concat(id,\'\') from sys_tag where classification_id = \'2428931245089341440\' and \\nif(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=2  ,name in ($tagNames)) and is_deleted=0\\nand  if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope=1))\\nunion\\nselect -9999999\",\"description\":\"如果tagName是all那么就不查出来\",\"hide\":2,\"includeAll\":true,\"multi\":true,\"name\":\"tagIds\",\"options\":[],\"query\":\"select concat(id,\'\') from sys_tag where classification_id = \'2428931245089341440\' and \\nif(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=2  ,name in ($tagNames)) and is_deleted=0\\nand  if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope=1))\\nunion\\nselect -9999999\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"}]},\"time\":{\"from\":\"now-30d\",\"to\":\"now\"},\"timepicker\":{},\"timezone\":\"\",\"title\":\"安徽征信DevOps运行情况\",\"uid\":\"2vpnFBgHk\",\"version\":36,\"weekStart\":\"\"}');
INSERT INTO `dashboard_version` VALUES (557, 43, 36, 0, 37, '2024-10-14 16:47:55', 40, '', '{\"annotations\":{\"list\":[{\"builtIn\":1,\"datasource\":{\"type\":\"grafana\",\"uid\":\"-- Grafana --\"},\"enable\":true,\"hide\":true,\"iconColor\":\"rgba(0, 211, 255, 1)\",\"name\":\"Annotations \\u0026 Alerts\",\"target\":{\"limit\":100,\"matchAny\":false,\"tags\":[],\"type\":\"dashboard\"},\"type\":\"dashboard\"}]},\"description\":\"\",\"editable\":true,\"fiscalYearStartMonth\":0,\"graphTooltip\":0,\"id\":43,\"links\":[],\"liveNow\":false,\"panels\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"max\":100,\"min\":0,\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"#ffb71f\",\"value\":null}]},\"unit\":\"percent\"},\"overrides\":[]},\"gridPos\":{\"h\":6,\"w\":5,\"x\":0,\"y\":0},\"id\":43,\"options\":{\"orientation\":\"auto\",\"reduceOptions\":{\"calcs\":[],\"fields\":\"\",\"values\":true},\"showThresholdLabels\":false,\"showThresholdMarkers\":false,\"text\":{}},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select ((select count(h.`vulnerability`)\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and h.`vulnerability` = 0 and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n order by h.create_time desc) / (select count(h.`vulnerability`)\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n order by h.create_time desc)) * 100\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"代码仓库质量通过率\",\"transformations\":[],\"type\":\"gauge\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"left\",\"displayMode\":\"auto\",\"inspect\":false},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":6,\"w\":5,\"x\":5,\"y\":0},\"id\":37,\"options\":{\"footer\":{\"countRows\":false,\"enablePagination\":false,\"fields\":\"\",\"reducer\":[\"sum\"],\"show\":false},\"showHeader\":false},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \'代码覆盖率\' as name,avg(coverage) as count \\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\nunion\\n\\nselect \'代码重复率\' as name, avg(repetition) as count\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n\\nunion\\n\\nselect \'代码坏味道\' as name, avg(`code_smell`) as count\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n \\n union\\n select \'Bugs\' as name, avg(bug) as count \\n  from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n\\nunion\\n select \'代码得分\' as name, avg(score) as count \\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"代码扫描情况\",\"type\":\"table\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"J2rj6S-4z\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false}},\"decimals\":0,\"mappings\":[],\"unit\":\"none\"},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"可信\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"严重\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#AD0317\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"高危\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#f5252f\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"中危\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"orange\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"低位\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"yellow\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"低危\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"yellow\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":6,\"w\":5,\"x\":10,\"y\":0},\"id\":41,\"options\":{\"displayLabels\":[],\"legend\":{\"displayMode\":\"table\",\"placement\":\"right\",\"showLegend\":true,\"values\":[\"value\"]},\"pieType\":\"donut\",\"reduceOptions\":{\"calcs\":[],\"fields\":\"/^num$/\",\"values\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"J2rj6S-4z\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \\n(CASE\\n   WHEN severity = \\\"CRITICAL\\\" THEN \'严重\'\\n   WHEN severity = \\\"HIGH\\\" THEN \'高危\'\\n   WHEN severity = \\\"MEDIUM\\\" THEN \'中危\'\\n   WHEN severity = \\\"LOW\\\" THEN \'低危\'\\n   WHEN severity = \\\"可信\\\" THEN \'可信\'\\n\\n   end) as s,\\n   num\\n  from (\\nSELECT\\n        (CASE\\n        WHEN LEAK_SEVERITY_V3 = \\\"CRITICAL\\\" THEN \\\"CRITICAL\\\"\\n        WHEN LEAK_SEVERITY_V3 = \\\"HIGH\\\" THEN \\\"HIGH\\\"\\n        WHEN LEAK_SEVERITY_V3 = \\\"MEDIUM\\\" THEN \\\"MEDIUM\\\"\\n        ELSE \\\"LOW\\\"\\n        END) AS severity,\\n        COUNT(*) AS num\\n        FROM `devops_leak`\\n        WHERE\\n        ID IN (SELECT DISTINCT LEAK_ID FROM `devops_leak_dp_relation` WHERE DP_DETAIL_ID IN (SELECT DP_DETAIL_ID FROM `devops_app_dp_relation` WHERE APP_HISTORY_ID in (select h.id\\nfrom devops_app app left join devops_app_scan_history h on app.id = h.app_id\\nwhere h.del_flag=0\\ngroup by h.app_id\\n)))\\n        GROUP BY severity) m\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"漏洞等级安全分布\",\"transformations\":[],\"type\":\"piechart\"},{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"wT7CrQa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"left\",\"displayMode\":\"auto\",\"filterable\":false,\"inspect\":false},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"val\"},\"properties\":[{\"id\":\"mappings\",\"value\":[{\"options\":{\"BLOCKER\":{\"index\":0,\"text\":\"阻断\"},\"CRITICAL\":{\"index\":1,\"text\":\"严重\"},\"INFO\":{\"index\":4,\"text\":\"轻微\"},\"MAJOR\":{\"index\":2,\"text\":\"主要\"},\"MINOR\":{\"index\":3,\"text\":\"次要\"}},\"type\":\"value\"}]}]}]},\"gridPos\":{\"h\":6,\"w\":5,\"x\":15,\"y\":0},\"id\":39,\"options\":{\"footer\":{\"countRows\":false,\"enablePagination\":false,\"fields\":\"\",\"reducer\":[\"sum\"],\"show\":false},\"frameIndex\":1,\"showHeader\":false},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"wT7CrQa4k\"},\"fields\":[{\"jsonPath\":\"$.facets[0].values[*].val\"},{\"jsonPath\":\"$.facets[0].values[*].count\",\"language\":\"jsonpath\",\"name\":\"\"}],\"method\":\"GET\",\"queryParams\":\"\",\"refId\":\"A\",\"urlPath\":\"/api/issues/search?s=FILE_LINE\\u0026resolved=false\\u0026ps=1\\u0026facets=severities\\u0026additionalFields=_all\\u0026timeZone=Asia%2FShanghai\"}],\"title\":\"存量代码问题\",\"transformations\":[{\"id\":\"sortBy\",\"options\":{\"fields\":{},\"sort\":[{\"desc\":false,\"field\":\"val\"}]}}],\"type\":\"table\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"b-L36I-4z\"},\"gridPos\":{\"h\":19,\"w\":24,\"x\":0,\"y\":6},\"id\":35,\"options\":{\"code\":{\"language\":\"plaintext\",\"showLineNumbers\":false,\"showMiniMap\":false},\"content\":\"**报告周期：2024年第二、三季度（4月1日至9月30日）**\\r\\n\\r\\n**一、概述**\\r\\n\\r\\n第二、三季度，主要完成安徽征信的DevOps平台搭建，通过“集中培训+分批次轮训”模式完成对公司前中台人员的系统操作培训，完成了各部门存量系统开发项目迁移及新增系统开发项目接入工作，\\r\\n实现公司系统开发项目、代码仓库、制品等统一管理。协助各项目经理建立任务流水线，加强了各项目持续集成/持续部署(CI/CD)的能力，通过代码质量扫描提高了软件开发效率与产品质量。通过一系列的技术改进和服务优化，缩短系统开发迭代周期。\\r\\n\\r\\n**二、关键绩效指标(KPIs)**\\r\\n\\r\\n- **日均代码合并次数**：\\t系统上线前平均4.83，系统投产后平均8.88，提升幅度84%。\\r\\n- **日均构建次数**：\\t系统上线前平均5.8，系统投产后平均8.32，提升幅度30%。\\r\\n- **单次构建平均用时（分钟）**：\\t系统上线前平均5，系统投产后平均2.24，提升幅度\\t223%。\\r\\n- **测试环境平均部署时间（分钟）**：\\t系统上线前平均5.6，系统投产后平均0.5，提升幅度\\t1120%。\\r\\n- **执行回退需要的时间（分钟）**：\\t系统上线前平均16，系统投产后平均6.4，提升幅度\\t250%。\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n**三、主要工作**\\r\\n\\r\\n1. **完成流水线功能模块上线，实现全自动化构建、代码安全检测和测试环境部署流程，提高系统交付速度和质量，全面代码构建效率。**\\r\\n2. **完成可信源管理模块上线并持续对漏洞库进行更新，实现从项目集成、发版门禁源头堵截高危漏洞，定期从中央漏洞库拉去漏洞，在流水线中对使用到的依赖包做扫描校验，在发布前对漏洞进行拦截，确保对代码安全性；**\\r\\n3. **结合行业最佳实践，完成《代码开发规范》建设,建立统一的代码风格和质量标准，确保代码的可读性、可维护性和安全性；**\\r\\n4. **完成代码评审模块功能上线，实现代码合并审查全流程线上化，对代码修改记录实现可视化管理，流程中嵌入代码安全监测，提高代码审查效率和代码安全质量；**\\r\\n5. **完成与OA系统进行打通，实现DevOps系统用户、任务代办、项目需求通过OA系统实现移动端在线办理；2024年7月份完成在库外包厂商需求处理功能在DevOps平台上线；**\\r\\n6. **完成《效能度量2.0指标》指定，并明确各效能指标展现形式及处理逻辑；**\\r\\n7. **截止三季度末已完成59个项目接入DevOps平台，实现项目需求、计划、代码仓库、流水线、制品等统一管理；**\\r\\n\\r\\n**四、下一步规划**\\r\\n\\r\\n1. **推进微服务架构改造**：计划将部分单体应用拆分为微服务，以增强系统的灵活性和可维护性。\\r\\n2. **加强团队建设**：定期组织内部培训和技术分享会，提升团队成员的专业技能和服务意识。\\r\\n3. **探索新技术**：关注行业发展趋势，适时引入人工智能、代码开发大模型等前沿技术，为公司提供更多创新价值。\\r\\n4. **平台功能迭代升级**：及时收集平台上线后各部门使用反馈意见，促进产品持续改进。\",\"mode\":\"markdown\"},\"pluginVersion\":\"9.4.0-pre\",\"title\":\"安徽征信DevOps整体运行情况\",\"type\":\"text\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":25},\"id\":27,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select org.name as name ,\\r\\ncount(1) as 项目数量\\r\\nfrom project\\r\\nleft join yanlian_app_management.sys_organization org on tenant_id = org.id\\r\\nwhere del_flag=0  and tenant_id !=\'2498172061581504512\'\\r\\ngroup by tenant_id\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门系统开发项目统计\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":25},\"id\":29,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select o.name as \'组织名称\',count(distinct s.system_id) as \'系统\',count(distinct s.id) as \'子系统（服务）\'  \\r\\n from yanlian_devops_scm.commit_info c \\r\\n left join yanlian_devops_development.sub_system_component s on c.gitlab_id=s.component_key and s.component=\'GITLAB\'\\r\\n left join yanlian_devops_development.devops_system d on s.system_id=d.id\\r\\n left join yanlian_app_management.sys_organization o on d.tenant_id = o.id\\r\\n where 1=1 and o.name !=\'\' and o.name!=\'样板间\'\\r\\n group by o.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门系统开发子系统统计\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"green\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":9,\"w\":12,\"x\":0,\"y\":33},\"id\":23,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select\\n  org.name,\\n  count(1) as \'流水线数量\'\\nfrom\\n  devops_jenkins_job job\\n left join yanlian_app_management.sys_organization org on job.tenant = org.id\\nwhere\\n  job.del_flag = 0\\n  and job.tenant != \'\'\\ngroup by\\n  org.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门流水线总数\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":9,\"w\":12,\"x\":12,\"y\":33},\"id\":25,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select o.name as \'组织名称\' ,sum(c.total)/10000 as \'变更行数\' ,sum(c.deletions)/10000 as \'删除行数\' ,sum(c.additions)/10000 as \'新增行数\' \\r\\n from yanlian_devops_scm.commit_info c \\r\\n left join yanlian_devops_development.sub_system_component s on c.gitlab_id=s.component_key and s.component=\'GITLAB\'\\r\\n left join yanlian_devops_development.devops_system d on s.system_id=d.id\\r\\n left join yanlian_app_management.sys_organization o on d.tenant_id = o.id\\r\\n where 1=1 and o.name !=\'\' and o.name!=\'样板间\'\\r\\n group by o.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门代码贡献情况（单位万）\",\"type\":\"barchart\"},{\"gridPos\":{\"h\":10,\"w\":12,\"x\":0,\"y\":42},\"id\":33,\"libraryPanel\":{\"name\":\"公司总的流水线每月运行情况\",\"uid\":\"5cXvEImHz\"},\"title\":\"流水线构建情况\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":0,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 公共信用部\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"red\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"公共信用部（平台办）\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 科技交付中心\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"科技交付中心\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 普惠信用部\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"blue\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"普惠信用部\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 企业信用部\"},\"properties\":[{\"id\":\"displayName\",\"value\":\"企业信用部\"},{\"id\":\"color\",\"value\":{\"fixedColor\":\"orange\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":12,\"y\":42},\"id\":20,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"fields\":[{\"jsonPath\":\"\"}],\"format\":\"table\",\"hide\":false,\"method\":\"GET\",\"queryParams\":\"\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\',\\n  middle.status_name as \'metric\'\\nFROM ( select count(1) as count,i.update_time ,(case \\n  when j.tenant=\'3267282568738619392\' then \'公共信用部\'\\n  when j.tenant=\'3267284931239067648\' then \'科技交付中心\'\\n  when j.tenant=\'3267282062251245568\' then \'企业信用部\'\\n  when j.tenant=\'3267281511404912640\' then \'普惠信用部\'\\n  when j.tenant=\'3267283983108259840\' then \'创新研发中心\'\\n  else j.tenant\\nend) as status_name\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\n where i.del_flag=0 and j.tenant !=\'\' and j.del_flag=0 \\ngroup by date_format(i.update_time,\'%Y%m%d\')\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\n  group by 1,2\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"urlPath\":\"\"}],\"title\":\"各部门流水线构建情况\",\"transformations\":[{\"id\":\"prepareTimeSeries\",\"options\":{\"format\":\"multi\"}}],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"统计每日成功执行的流水线构建时长，单位：分钟\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\",\"seriesBy\":\"last\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisGridShow\":true,\"axisLabel\":\"分钟\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"bars\",\"fillOpacity\":100,\"gradientMode\":\"scheme\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"smooth\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"normal\"},\"thresholdsStyle\":{\"mode\":\"dashed\"}},\"decimals\":1,\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"#226ee7\",\"value\":null},{\"color\":\"#f34d1f\",\"value\":5}]}},\"overrides\":[]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":0,\"y\":52},\"id\":8,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.avg_time as \'时长\'\\nFROM ( \\n\\nselect _m.update_time,avg(duration) / 60 as avg_time\\nfrom (select i.update_time,(unix_timestamp(i.end_time) - unix_timestamp(i.start_time)) as duration\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\nwhere\\ni.update_time is not null and i.status=\'SUCCESS\' and i.del_flag=0\\nand job_id in(select id from devops_jenkins_job where del_flag=0 and if(\'$amp_organ_id\'=\'3267246491214659584\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')))\\norder by update_time asc\\n) as _m\\ngroup by date_format(update_time,\'%Y%m%d\')\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"devops_job_build_info\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"流水线构建平均时长\",\"transformations\":[],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":0,\"gradientMode\":\"opacity\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":7,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"never\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"失败\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#e15a33\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"成功\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#58b076\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":10,\"w\":12,\"x\":12,\"y\":52},\"id\":14,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"multi\",\"sort\":\"asc\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.time,1d),\\n  middle.count as \'数量\'\\nFROM (select count(1) as count,p.create_time as time\\nfrom devops_product p\\nleft join devops_repository r on p.repo_id=r.id\\nwhere p.create_time is not null \\ngroup by date_format(p.create_time, \'%Y%m%d\')\\norder by p.create_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.time)\\nORDER BY $__timeGroup(middle.time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"构建制品统计\",\"type\":\"timeseries\"}],\"refresh\":false,\"schemaVersion\":37,\"style\":\"dark\",\"tags\":[],\"templating\":{\"list\":[{\"allValue\":\"\'all\'\",\"current\":{\"selected\":true,\"text\":[\"All\"],\"value\":[\"$__all\"]},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select name from sys_tag where classification_id= 2428931245089341440 and if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope = 1)) and is_deleted=0\\nunion\\nselect \'\'\",\"description\":\"\",\"hide\":2,\"includeAll\":true,\"label\":\"标签\",\"multi\":true,\"name\":\"tagNames\",\"options\":[],\"query\":\"select name from sys_tag where classification_id= 2428931245089341440 and if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope = 1)) and is_deleted=0\\nunion\\nselect \'\'\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"},{\"current\":{\"selected\":false,\"text\":\"3267246491214659584\",\"value\":\"3267246491214659584\"},\"hide\":2,\"label\":\"amp_organ_id\",\"name\":\"amp_organ_id\",\"options\":[{\"selected\":false,\"text\":\"2498172061581504512\",\"value\":\"2498172061581504512\"}],\"query\":\"3267246491214659584\",\"skipUrlSync\":false,\"type\":\"textbox\"},{\"current\":{\"selected\":true,\"text\":[\"All\"],\"value\":[\"$__all\"]},\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"definition\":\"select concat(id,\'\') from sys_tag where classification_id = \'2428931245089341440\' and \\nif(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=2  ,name in ($tagNames)) and is_deleted=0\\nand  if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope=1))\\nunion\\nselect -9999999\",\"description\":\"如果tagName是all那么就不查出来\",\"hide\":2,\"includeAll\":true,\"multi\":true,\"name\":\"tagIds\",\"options\":[],\"query\":\"select concat(id,\'\') from sys_tag where classification_id = \'2428931245089341440\' and \\nif(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=2  ,name in ($tagNames)) and is_deleted=0\\nand  if(\'$amp_organ_id\'=\'null\', 1=1, (organ_id =  \'$amp_organ_id\' or scope=1))\\nunion\\nselect -9999999\",\"refresh\":1,\"regex\":\"\",\"skipUrlSync\":false,\"sort\":0,\"type\":\"query\"}]},\"time\":{\"from\":\"now-30d\",\"to\":\"now\"},\"timepicker\":{},\"timezone\":\"\",\"title\":\"安徽征信DevOps运行情况\",\"uid\":\"2vpnFBgHk\",\"version\":37,\"weekStart\":\"\"}');
INSERT INTO `dashboard_version` VALUES (558, 43, 37, 0, 38, '2024-10-14 16:52:08', 40, '', '{\"annotations\":{\"list\":[{\"builtIn\":1,\"datasource\":{\"type\":\"grafana\",\"uid\":\"-- Grafana --\"},\"enable\":true,\"hide\":true,\"iconColor\":\"rgba(0, 211, 255, 1)\",\"name\":\"Annotations \\u0026 Alerts\",\"target\":{\"limit\":100,\"matchAny\":false,\"tags\":[],\"type\":\"dashboard\"},\"type\":\"dashboard\"}]},\"description\":\"\",\"editable\":true,\"fiscalYearStartMonth\":0,\"graphTooltip\":0,\"id\":43,\"links\":[],\"liveNow\":false,\"panels\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"b-L36I-4z\"},\"gridPos\":{\"h\":19,\"w\":24,\"x\":0,\"y\":0},\"id\":35,\"options\":{\"code\":{\"language\":\"plaintext\",\"showLineNumbers\":false,\"showMiniMap\":false},\"content\":\"**报告周期：2024年第二、三季度（4月1日至9月30日）**\\r\\n\\r\\n**一、概述**\\r\\n\\r\\n第二、三季度，主要完成安徽征信的DevOps平台搭建，通过“集中培训+分批次轮训”模式完成对公司前中台人员的系统操作培训，完成了各部门存量系统开发项目迁移及新增系统开发项目接入工作，\\r\\n实现公司系统开发项目、代码仓库、制品等统一管理。协助各项目经理建立任务流水线，加强了各项目持续集成/持续部署(CI/CD)的能力，通过代码质量扫描提高了软件开发效率与产品质量。通过一系列的技术改进和服务优化，缩短系统开发迭代周期。\\r\\n\\r\\n**二、关键绩效指标(KPIs)**\\r\\n\\r\\n- **日均代码合并次数**：\\t系统上线前平均4.83，系统投产后平均8.88，提升幅度84%。\\r\\n- **日均构建次数**：\\t系统上线前平均5.8，系统投产后平均8.32，提升幅度30%。\\r\\n- **单次构建平均用时（分钟）**：\\t系统上线前平均5，系统投产后平均2.24，提升幅度\\t223%。\\r\\n- **测试环境平均部署时间（分钟）**：\\t系统上线前平均5.6，系统投产后平均0.5，提升幅度\\t1120%。\\r\\n- **执行回退需要的时间（分钟）**：\\t系统上线前平均16，系统投产后平均6.4，提升幅度\\t250%。\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n**三、主要工作**\\r\\n\\r\\n1. **完成流水线功能模块上线，实现全自动化构建、代码安全检测和测试环境部署流程，提高系统交付速度和质量，全面代码构建效率。**\\r\\n2. **完成可信源管理模块上线并持续对漏洞库进行更新，实现从项目集成、发版门禁源头堵截高危漏洞，定期从中央漏洞库拉去漏洞，在流水线中对使用到的依赖包做扫描校验，在发布前对漏洞进行拦截，确保对代码安全性；**\\r\\n3. **结合行业最佳实践，完成《代码开发规范》建设,建立统一的代码风格和质量标准，确保代码的可读性、可维护性和安全性；**\\r\\n4. **完成代码评审模块功能上线，实现代码合并审查全流程线上化，对代码修改记录实现可视化管理，流程中嵌入代码安全监测，提高代码审查效率和代码安全质量；**\\r\\n5. **完成与OA系统进行打通，实现DevOps系统用户、任务代办、项目需求通过OA系统实现移动端在线办理；2024年7月份完成在库外包厂商需求处理功能在DevOps平台上线；**\\r\\n6. **完成《效能度量2.0指标》指定，并明确各效能指标展现形式及处理逻辑；**\\r\\n7. **截止三季度末已完成59个项目接入DevOps平台，实现项目需求、计划、代码仓库、流水线、制品等统一管理；**\\r\\n\\r\\n**四、下一步规划**\\r\\n\\r\\n1. **推进微服务架构改造**：计划将部分单体应用拆分为微服务，以增强系统的灵活性和可维护性。\\r\\n2. **加强团队建设**：定期组织内部培训和技术分享会，提升团队成员的专业技能和服务意识。\\r\\n3. **探索新技术**：关注行业发展趋势，适时引入人工智能、代码开发大模型等前沿技术，为公司提供更多创新价值。\\r\\n4. **平台功能迭代升级**：及时收集平台上线后各部门使用反馈意见，促进产品持续改进。\",\"mode\":\"markdown\"},\"pluginVersion\":\"9.4.0-pre\",\"title\":\"安徽征信DevOps整体运行情况\",\"type\":\"text\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":7,\"w\":12,\"x\":0,\"y\":19},\"id\":27,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select org.name as name ,\\r\\ncount(1) as 项目数量\\r\\nfrom project\\r\\nleft join yanlian_app_management.sys_organization org on tenant_id = org.id\\r\\nwhere del_flag=0  and tenant_id !=\'2498172061581504512\'\\r\\ngroup by tenant_id\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门系统开发项目统计\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":7,\"w\":12,\"x\":12,\"y\":19},\"id\":29,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select o.name as \'组织名称\',count(distinct s.system_id) as \'系统\',count(distinct s.id) as \'子系统（服务）\'  \\r\\n from yanlian_devops_scm.commit_info c \\r\\n left join yanlian_devops_development.sub_system_component s on c.gitlab_id=s.component_key and s.component=\'GITLAB\'\\r\\n left join yanlian_devops_development.devops_system d on s.system_id=d.id\\r\\n left join yanlian_app_management.sys_organization o on d.tenant_id = o.id\\r\\n where 1=1 and o.name !=\'\' and o.name!=\'样板间\'\\r\\n group by o.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门系统开发子系统统计\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"green\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":26},\"id\":23,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select\\n  org.name,\\n  count(1) as \'流水线数量\'\\nfrom\\n  devops_jenkins_job job\\n left join yanlian_app_management.sys_organization org on job.tenant = org.id\\nwhere\\n  job.del_flag = 0\\n  and job.tenant != \'\'\\ngroup by\\n  org.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门流水线总数\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":26},\"id\":25,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select o.name as \'组织名称\' ,sum(c.total)/10000 as \'变更行数\' ,sum(c.deletions)/10000 as \'删除行数\' ,sum(c.additions)/10000 as \'新增行数\' \\r\\n from yanlian_devops_scm.commit_info c \\r\\n left join yanlian_devops_development.sub_system_component s on c.gitlab_id=s.component_key and s.component=\'GITLAB\'\\r\\n left join yanlian_devops_development.devops_system d on s.system_id=d.id\\r\\n left join yanlian_app_management.sys_organization o on d.tenant_id = o.id\\r\\n where 1=1 and o.name !=\'\' and o.name!=\'样板间\'\\r\\n group by o.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门代码贡献情况（单位万）\",\"type\":\"barchart\"},{\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":34},\"id\":33,\"libraryPanel\":{\"name\":\"公司总的流水线每月运行情况\",\"uid\":\"5cXvEImHz\"},\"title\":\"流水线构建情况\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":0,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 公共信用部\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"red\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"公共信用部（平台办）\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 科技交付中心\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"科技交付中心\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 普惠信用部\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"blue\",\"mode\":\"fixed\"}},{\"id\":\"displayName\",\"value\":\"普惠信用部\"}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"构建次数 企业信用部\"},\"properties\":[{\"id\":\"displayName\",\"value\":\"企业信用部\"},{\"id\":\"color\",\"value\":{\"fixedColor\":\"orange\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":34},\"id\":20,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"fields\":[{\"jsonPath\":\"\"}],\"format\":\"table\",\"hide\":false,\"method\":\"GET\",\"queryParams\":\"\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\',\\n  middle.status_name as \'metric\'\\nFROM ( select count(1) as count,i.update_time ,(case \\n  when j.tenant=\'3267282568738619392\' then \'公共信用部\'\\n  when j.tenant=\'3267284931239067648\' then \'科技交付中心\'\\n  when j.tenant=\'3267282062251245568\' then \'企业信用部\'\\n  when j.tenant=\'3267281511404912640\' then \'普惠信用部\'\\n  when j.tenant=\'3267283983108259840\' then \'创新研发中心\'\\n  else j.tenant\\nend) as status_name\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\n where i.del_flag=0 and j.tenant !=\'\' and j.del_flag=0 \\ngroup by date_format(i.update_time,\'%Y%m%d\')\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\n  group by 1,2\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"urlPath\":\"\"}],\"title\":\"各部门流水线构建情况\",\"transformations\":[{\"id\":\"prepareTimeSeries\",\"options\":{\"format\":\"multi\"}}],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"统计每日成功执行的流水线构建时长，单位：分钟\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\",\"seriesBy\":\"last\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisGridShow\":true,\"axisLabel\":\"分钟\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"bars\",\"fillOpacity\":100,\"gradientMode\":\"scheme\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"smooth\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"normal\"},\"thresholdsStyle\":{\"mode\":\"dashed\"}},\"decimals\":1,\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"#226ee7\",\"value\":null},{\"color\":\"#f34d1f\",\"value\":5}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":42},\"id\":8,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.avg_time as \'时长\'\\nFROM ( \\n\\nselect _m.update_time,avg(duration) / 60 as avg_time\\nfrom (select i.update_time,(unix_timestamp(i.end_time) - unix_timestamp(i.start_time)) as duration\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\nwhere\\ni.update_time is not null and i.status=\'SUCCESS\' and i.del_flag=0\\nand job_id in(select id from devops_jenkins_job where del_flag=0 and if(\'$amp_organ_id\'=\'3267246491214659584\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')))\\norder by update_time asc\\n) as _m\\ngroup by date_format(update_time,\'%Y%m%d\')\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"devops_job_build_info\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"流水线构建平均时长\",\"transformations\":[],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":0,\"gradientMode\":\"opacity\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"linear\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":7,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"never\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"失败\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#e15a33\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"成功\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#58b076\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":42},\"id\":14,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"multi\",\"sort\":\"asc\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.time,1d),\\n  middle.count as \'数量\'\\nFROM (select count(1) as count,p.create_time as time\\nfrom devops_product p\\nleft join devops_repository r on p.repo_id=r.id\\nwhere p.create_time is not null \\ngroup by date_format(p.create_time, \'%Y%m%d\')\\norder by p.create_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.time)\\nORDER BY $__timeGroup(middle.time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"构建制品统计\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"max\":100,\"min\":0,\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"#ffb71f\",\"value\":null}]},\"unit\":\"percent\"},\"overrides\":[]},\"gridPos\":{\"h\":6,\"w\":6,\"x\":0,\"y\":50},\"id\":43,\"options\":{\"orientation\":\"auto\",\"redu