系统统计\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"green\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":7},\"id\":23,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select\\n  org.name,\\n  count(1) as \'流水线数量\'\\nfrom\\n  devops_jenkins_job job\\n left join yanlian_app_management.sys_organization org on job.tenant = org.id\\nwhere\\n  job.del_flag = 0\\n  and job.tenant != \'\'\\ngroup by\\n  org.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门流水线总数\",\"type\":\"barchart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"fillOpacity\":80,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineWidth\":1,\"scaleDistribution\":{\"type\":\"linear\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":7},\"id\":25,\"options\":{\"barRadius\":0,\"barWidth\":0.97,\"groupWidth\":0.7,\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"orientation\":\"auto\",\"showValue\":\"auto\",\"stacking\":\"none\",\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"},\"xTickLabelRotation\":0,\"xTickLabelSpacing\":0},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\" select o.name as \'组织名称\' ,sum(c.total)/10000 as \'变更行数\' ,sum(c.deletions)/10000 as \'删除行数\' ,sum(c.additions)/10000 as \'新增行数\' \\r\\n from yanlian_devops_scm.commit_info c \\r\\n left join yanlian_devops_development.sub_system_component s on c.gitlab_id=s.component_key and s.component=\'GITLAB\'\\r\\n left join yanlian_devops_development.devops_system d on s.system_id=d.id\\r\\n left join yanlian_app_management.sys_organization o on d.tenant_id = o.id\\r\\n where 1=1 and o.name !=\'\' and o.name!=\'样板间\'\\r\\n group by o.name\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"各部门代码贡献情况（单位万）\",\"type\":\"barchart\"},{\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":15},\"id\":33,\"libraryPanel\":{\"name\":\"公司总的流水线每月运行情况\",\"uid\":\"5cXvEImHz\"},\"title\":\"流水线构建情况\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":5,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"smooth\",\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":15},\"id\":20,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"fields\":[{\"jsonPath\":\"\"}],\"format\":\"table\",\"hide\":false,\"method\":\"GET\",\"queryParams\":\"\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\',\\n  middle.status_name as \'metric\'\\nFROM ( select count(1) as count,i.update_time ,(case \\n  when j.tenant=\'3267282568738619392\' then \'公共信用部\'\\n  when j.tenant=\'3267284931239067648\' then \'科技交付中心\'\\n  when j.tenant=\'3267282062251245568\' then \'企业信用部\'\\n  when j.tenant=\'3267281511404912640\' then \'普惠信用部\'\\n  when j.tenant=\'3267283983108259840\' then \'创新研发中心\'\\n  else j.tenant\\nend) as status_name\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\n where i.del_flag=0 and j.tenant !=\'\' and j.del_flag=0 \\ngroup by date_format(i.update_time,\'%Y%m%d\')\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\n  group by 1,2\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"urlPath\":\"\"}],\"title\":\"各部门流水线构建情况\",\"transformations\":[{\"id\":\"prepareTimeSeries\",\"options\":{\"format\":\"multi\"}}],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"统计每日成功执行的流水线构建时长，单位：分钟\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\",\"seriesBy\":\"last\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisGridShow\":true,\"axisLabel\":\"分钟\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"bars\",\"fillOpacity\":100,\"gradientMode\":\"scheme\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"smooth\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"normal\"},\"thresholdsStyle\":{\"mode\":\"dashed\"}},\"decimals\":1,\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"#226ee7\",\"value\":null},{\"color\":\"#f34d1f\",\"value\":5}]}},\"overrides\":[]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":0,\"y\":23},\"id\":8,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.avg_time as \'时长\'\\nFROM ( \\n\\nselect _m.update_time,avg(duration) / 60 as avg_time\\nfrom (select i.update_time,(unix_timestamp(i.end_time) - unix_timestamp(i.start_time)) as duration\\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\nwhere\\ni.update_time is not null and i.status=\'SUCCESS\' and i.del_flag=0\\nand job_id in(select id from devops_jenkins_job where del_flag=0 and if(\'$amp_organ_id\'=\'3267246491214659584\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')))\\norder by update_time asc\\n) as _m\\ngroup by date_format(update_time,\'%Y%m%d\')\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"devops_job_build_info\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"流水线构建平均时长\",\"transformations\":[],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":7,\"gradientMode\":\"opacity\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"lineInterpolation\":\"smooth\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":2,\"pointSize\":7,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"never\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"失败\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#e15a33\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"成功\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#58b076\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":8,\"w\":12,\"x\":12,\"y\":23},\"id\":14,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"mode\":\"multi\",\"sort\":\"asc\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.time,1d),\\n  middle.count as \'数量\'\\nFROM (select count(1) as count,p.create_time as time\\nfrom devops_product p\\nleft join devops_repository r on p.repo_id=r.id\\nwhere p.create_time is not null \\ngroup by date_format(p.create_time, \'%Y%m%d\')\\norder by p.create_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.time)\\nORDER BY $__timeGroup(middle.time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"构建制品统计\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"max\":100,\"min\":0,\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"#ffb71f\",\"value\":null}]},\"unit\":\"percent\"},\"overrides\":[]},\"gridPos\":{\"h\":6,\"w\":6,\"x\":0,\"y\":31},\"id\":43,\"options\":{\"orientation\":\"auto\",\"reduceOptions\":{\"calcs\":[],\"fields\":\"\",\"values\":true},\"showThresholdLabels\":false,\"showThresholdMarkers\":false,\"text\":{}},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select ((select count(h.`vulnerability`)\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and h.`vulnerability` = 0 \\n order by h.create_time desc) / (select count(h.`vulnerability`)\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) \\n order by h.create_time desc)) * 100\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"代码仓库质量通过率\",\"transformations\":[],\"type\":\"gauge\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"left\",\"displayMode\":\"auto\",\"inspect\":false},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":6,\"w\":6,\"x\":6,\"y\":31},\"id\":37,\"options\":{\"footer\":{\"countRows\":false,\"enablePagination\":false,\"fields\":\"\",\"reducer\":[\"sum\"],\"show\":false},\"showHeader\":false},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \'代码覆盖率\' as name,avg(coverage) as count \\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) \\nunion\\n\\nselect \'代码重复率\' as name, avg(repetition) as count\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) \\n\\n\\nunion\\n\\nselect \'代码坏味道\' as name, avg(`code_smell`) as count\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) \\n\\n \\n union\\n select \'Bugs\' as name, avg(bug) as count \\n  from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) \\n\\n\\nunion\\n select \'代码得分\' as name, avg(score) as count \\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) \\n\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"代码扫描情况\",\"type\":\"table\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"J2rj6S-4z\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false}},\"decimals\":0,\"mappings\":[],\"unit\":\"none\"},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"可信\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"严重\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#AD0317\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"高危\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#f5252f\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"中危\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"orange\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"低位\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"yellow\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"低危\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"yellow\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":6,\"w\":6,\"x\":12,\"y\":31},\"id\":41,\"options\":{\"displayLabels\":[],\"legend\":{\"displayMode\":\"table\",\"placement\":\"right\",\"showLegend\":true,\"values\":[\"value\"]},\"pieType\":\"donut\",\"reduceOptions\":{\"calcs\":[],\"fields\":\"/^num$/\",\"values\":true},\"tooltip\":{\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"J2rj6S-4z\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \\n(CASE\\n   WHEN severity = \\\"CRITICAL\\\" THEN \'严重\'\\n   WHEN severity = \\\"HIGH\\\" THEN \'高危\'\\n   WHEN severity = \\\"MEDIUM\\\" THEN \'中危\'\\n   WHEN severity = \\\"LOW\\\" THEN \'低危\'\\n   WHEN severity = \\\"可信\\\" THEN \'可信\'\\n\\n   end) as s,\\n   num\\n  from (\\nSELECT\\n        (CASE\\n        WHEN LEAK_SEVERITY_V3 = \\\"CRITICAL\\\" THEN \\\"CRITICAL\\\"\\n        WHEN LEAK_SEVERITY_V3 = \\\"HIGH\\\" THEN \\\"HIGH\\\"\\n        WHEN LEAK_SEVERITY_V3 = \\\"MEDIUM\\\" THEN \\\"MEDIUM\\\"\\n        ELSE \\\"LOW\\\"\\n        END) AS severity,\\n        COUNT(*) AS num\\n        FROM `devops_leak`\\n        WHERE\\n        ID IN (SELECT DISTINCT LEAK_ID FROM `devops_leak_dp_relation` WHERE DP_DETAIL_ID IN (SELECT DP_DETAIL_ID FROM `devops_app_dp_relation` WHERE APP_HISTORY_ID in (select h.id\\nfrom devops_app app left join devops_app_scan_history h on app.id = h.app_id\\nwhere h.del_flag=0\\ngroup by h.app_id\\n)))\\n        GROUP BY severity) m\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"漏洞等级安全分布\",\"transformations\":[],\"type\":\"piechart\"},{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"wT7CrQa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"left\",\"displayMode\":\"auto\",\"filterable\":false,\"inspect\":false},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"val\"},\"properties\":[{\"id\":\"mappings\",\"value\":[{\"options\":{\"BLOCKER\":{\"index\":0,\"text\":\"阻断\"},\"CRITICAL\":{\"index\":1,\"text\":\"严重