unt\\n\\n\\n\\n\\nfrom issues i1\\nwhere i1.del_flag = 0 and i1.issues_type_id=98 and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, i1.tenant_id in($amp_organ_id))\\nand $__timeFilter(i1.create_time)\\ngroup by date_format(cast(i1.create_time as datetime), \'%Y%m%d\')\\n\\nORDER BY i1.create_time ASC\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"artifacts_repositories\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"timestamp\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"缺陷趋势\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"left\",\"cellOptions\":{\"type\":\"auto\"},\"inspect\":false},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":6,\"w\":5,\"x\":7,\"y\":23},\"id\":27,\"options\":{\"cellHeight\":\"sm\",\"footer\":{\"countRows\":false,\"enablePagination\":false,\"fields\":\"\",\"reducer\":[\"sum\"],\"show\":false},\"showHeader\":false},\"pluginVersion\":\"11.1.0\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"l9_EeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \'代码覆盖率\' as name,avg(coverage) as count \\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\nunion\\n\\nselect \'代码重复率\' as name, avg(repetition) as count\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n\\nunion\\n\\nselect \'代码坏味道\' as name, avg(`code_smell`) as count\\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n \\n union\\n select \'Bugs\' as name, avg(bug) as count \\n  from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n\\nunion\\n select \'代码得分\' as name, avg(score) as count \\n from scan_task t left join scan_history h on t.id=h.scan_task_id\\n where t.del_flag=0 and h.id in (select max(id) from scan_history group by scan_task_id) and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, t.tenant_id in($amp_organ_id))\\n\\n\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"代码扫描情况\",\"type\":\"table\"},{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"wT7CrQa4k\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"custom\":{\"align\":\"left\",\"cellOptions\":{\"type\":\"auto\"},\"filterable\":false,\"inspect\":false},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"val\"},\"properties\":[{\"id\":\"mappings\",\"value\":[{\"options\":{\"BLOCKER\":{\"index\":0,\"text\":\"阻断\"},\"CRITICAL\":{\"index\":1,\"text\":\"严重\"},\"INFO\":{\"index\":4,\"text\":\"轻微\"},\"MAJOR\":{\"index\":2,\"text\":\"主要\"},\"MINOR\":{\"index\":3,\"text\"