justifyMode\":\"auto\",\"orientation\":\"auto\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"\",\"values\":false},\"showPercentChange\":false,\"textMode\":\"auto\",\"wideLayout\":true},\"pluginVersion\":\"11.1.0\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"0u4olSa4k\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select count(distinct u.id) from yanlian_devops_issues_track_v2.project p \\nleft join yanlian_app_management.sys_resource_instance r on concat(p.resource_type_code,p.id)=concat(r.resource_type_code,r.resource_instance_id)\\nleft join yanlian_app_management.sys_owner_resource o on r.id = o.resource_id\\nleft join yanlian_app_management.sys_resource_owner_instance i on i.id = o.resource_owner_id\\nleft join yanlian_app_management.sys_user u on u.id = i.resource_owner_instance_id\\nwhere  if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, p.tenant_id in($amp_organ_id))\\n and p.del_flag=0\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"人员总数\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[]},\"gridPos\":{\"h\":3,\"w\":3,\"x\":4,\"y\":0},\"id\":7,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"auto\",\"orientation\":\"auto\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"\",\"values\":false},\"showPercentChange\":false,\"textMode\":\"auto\",\"wideLayout\":true},\"pluginVersion\":\"11.1.0\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select  count(1) as count\\n\\nfrom issues i\\nwhere \\ni.issues_type_id in (96,97,98) and i.status_id =3 and\\ni.del_flag=0  and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant_id in($amp_organ_id))\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"工作项完成数\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"nkc76-sIk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisBorderShow\":false,\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":0,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"insertNulls\":false,\"lineInterpolation\":\"linear\",\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":6,\"w\":10,\"x\":7,\"y\":0},\"id\":11,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"maxHeight\":600,\"mode\":\"single\",\"sort\":\"none\"}},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"mysql\",\"uid\":\"nkc76-sIk\"},\"editorMode\":\"code\",\"fields\":[{\"jsonPath\":\"\"}],\"format\":\"table\",\"method\":\"GET\",\"queryParams\":\"\",\"rawQuery\":true,\"rawSql\":\"SELECT\\r\\n  $__timeGroupAlias(middle.time,1d),\\r\\n  middle.count as \'数量\'\\r\\nFROM (select sum(p.total) as count,p.create_time as time\\r\\nfrom commit_info p\\r\\nwhere p.create_time is not null \\r\\ngroup by date_format(p.create_time, \'%Y%m%d\')\\r\\norder by p.create_time asc\\r\\n) as middle\\r\\nWHERE\\r\\n  $__timeFilter(middle.time)\\r\\nORDER BY $__timeGroup(middle.time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"urlPath\":\"\"}],\"title\":\"代码每日提交记录\",\"transformations\":[{\"id\":\"convertFieldType\",\"options\":{\"conversions\":[],\"fields\":{}}}],\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[]},\"gridPos\":{\"h\":4,\"w\":7,\"x\":17,\"y\":0},\"id\":20,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"center\",\"orientation\":\"vertical\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"\",\"values\":true},\"showPercentChange\":false,\"textMode\":\"auto\",\"wideLayout\":true},\"pluginVersion\":\"11.1.0\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select * from\\n(\\nselect count(1) as \\\"今日\\\"\\nfrom devops_job_build_info\\nwhere \\nDATE_FORMAT(update_time,\'%Y%m%d\') = DATE_FORMAT(now(),\'%Y%m%d\') and job_id in(select id from devops_jenkins_job where del_flag=0 and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant in($amp_organ_id)))) m3,\\n(\\nselect count(1) as \\\"7天内\\\"\\nfrom devops_job_build_info\\nwhere \\nupdate_time between ( SELECT now( ) - INTERVAL 7 day )  AND (SELECT now()) and job_id in(select id from devops_jenkins_job where del_flag=0  and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant in($amp_organ_id)))) m2,\\n(\\nselect count(1) as \\\"14天内\\\"\\nfrom devops_job_build_info\\nwhere \\nupdate_time between ( SELECT now( ) - INTERVAL 14 day )  AND (SELECT now()) and job_id in(select id from devops_jenkins_job where del_flag=0  and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant in($amp_organ_id)))) m1\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"流水线构建情况\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false}},\"mappings\":[]},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"延期项目\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"dark-red\",\"mode\":\"fixed\"}}]},{\"__systemRef\":\"hideSeriesFrom\",\"matcher\":{\"id\":\"byNames\",\"options\":{\"mode\":\"exclude\",\"names\":[\"count\"],\"prefix\":\"All except:\",\"readOnly\":true}},\"properties\":[{\"id\":\"custom.hideFrom\",\"value\":{\"legend\":false,\"tooltip\":false,\"viz\":true}}]}]},\"gridPos\":{\"h\":7,\"w\":7,\"x\":0,\"y\":3},\"id\":9,\"options\":{\"legend\":{\"displayMode\":\"list\",\"placement\":\"right\",\"showLegend\":true,\"values\":[\"value\"]},\"pieType\":\"pie\",\"reduceOptions\":{\"calcs\":[],\"fields\":\"\",\"values\":true},\"tooltip\":{\"maxHeight\":600,\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \'延期项目\' as name,\\ncount(1) as count\\nfrom project\\nwhere del_flag=0 and end_time is not null and end_time \\u003c now() and status in(1,2)  and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant_id in($amp_organ_id))\\nunion\\nselect \'进行中项目\' as name,\\ncount(1) as count\\nfrom project\\nwhere del_flag=0 and status=\'1\' and (end_time is null or end_time \\u003e= now())  and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant_id in($amp_organ_id))\\nunion\\nselect \'未开始项目\' as name,\\ncount(1) as count\\nfrom project\\nwhere del_flag=0 and status=\'2\' and (end_time is null or end_time \\u003e= now())  and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant_id in($amp_organ_id))\\nunion\\nselect \'已完成项目\' as name,\\ncount(1) as count\\nfrom project\\nwhere del_flag=0 and status=3  and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant_id in($amp_organ_id))\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"项目状态\",\"type\":\"piechart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisBorderShow\":false,\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":100,\"gradientMode\":\"opacity\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"insertNulls\":false,\"lineInterpolation\":\"linear\",\"lineStyle\":{\"fill\":\"solid\"},\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":true,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"失败\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"red\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"成功\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":6,\"w\":7,\"x\":17,\"y\":4},\"id\":17,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"maxHeight\":600,\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\',\\n  middle.status_name as \'metric\'\\nFROM ( \\nselect count(1) as count, i.update_time ,\\n(case \\n  when i.status=\'SUCCESS\' then \'成功\'\\n  when i.status=\'FAILED\' then \'失败\'\\n  when i.status=\'ABORTED\' then \'中止\'\\n  else i.status\\nend) as status_name\\nfrom devops_job_build_info i\\nwhere i.del_flag=0 and status in(\'SUCCESS\',\'FAILED\') and job_id in(select id from devops_jenkins_job where del_flag=0  and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant in($amp_organ_id)))\\ngroup by date_format(i.update_time,\'%Y%m%d\'), i.status\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nGROUP BY 1,2\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"每日构建统计\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"If5u9w-Vz\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[]},\"gridPos\":{\"h\":4,\"w\":10,\"x\":7,\"y\":6},\"id\":13,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"center\",\"orientation\":\"vertical\",\"reduceOptions\":{\"calcs\":[\"lastNotNull\"],\"fields\":\"/^count$/\",\"values\":true},\"showPercentChange\":false,\"textMode\":\"auto\",\"wideLayout\":true},\"pluginVersion\":\"11.1.0\",\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"If5u9w-Vz\"},\"fields\":[{\"jsonPath\":\"$.data[*].date\"},{\"jsonPath\":\"$.data[*].count\",\"language\":\"jsonpath\",\"name\":\"\",\"type\"