97,98) and status_id = 3 and del_flag=0 and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant_id in($amp_organ_id)) and close_time is not null\\ngroup by date_format(cast(close_time as datetime), \'%Y%m%d\'),issues_type_id\\n) as middle\\nWHERE\\n  $__timeFilter(middle.time)\\nORDER BY $__timeGroup(middle.time,1d)\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"},{\"params\":[\"avg\"],\"type\":\"aggregate\"},{\"params\":[\"id\"],\"type\":\"alias\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"issues\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"datetime\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}],\"title\":\"每日完成工作项情况\",\"type\":\"timeseries\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisBorderShow\":false,\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":0,\"gradientMode\":\"none\",\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false},\"insertNulls\":false,\"lineInterpolation\":\"linear\",\"lineWidth\":1,\"pointSize\":5,\"scaleDistribution\":{\"type\":\"linear\"},\"showPoints\":\"auto\",\"spanNulls\":false,\"stacking\":{\"group\":\"A\",\"mode\":\"none\"},\"thresholdsStyle\":{\"mode\":\"off\"}},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null},{\"color\":\"red\",\"value\":80}]}},\"overrides\":[]},\"gridPos\":{\"h\":5,\"w\":10,\"x\":7,\"y\":10},\"id\":39,\"options\":{\"legend\":{\"calcs\":[],\"displayMode\":\"list\",\"placement\":\"bottom\",\"showLegend\":true},\"tooltip\":{\"maxHeight\":600,\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"dYOC6S-Vk\"},\"edit