orMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"SELECT \'项目制品库\' as name, count(1) as count\\nFROM devops_repository \\nWHERE format = \'raw\' AND kind = 2 AND repository_type = \'hosted\' and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant_id in($amp_organ_id))\\nunion\\n\\n\\n\\nSELECT \'组件库\' as name, count(1) as count\\nFROM devops_repository \\nWHERE format != \'raw\' AND kind = 0 AND repository_type = \'hosted\' and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant_id in($amp_organ_id))\\n\\nunion\\n\\nSELECT \'公共依赖库\' as name, count(1) as count FROM devops_repository WHERE kind = 1 AND repository_type = \'group\' AND scope = 0  and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant_id in($amp_organ_id))\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"制品库统计\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"hideFrom\":{\"legend\":false,\"tooltip\":false,\"viz\":false}},\"mappings\":[]},\"overrides\":[{\"matcher\":{\"id\":\"byName\",\"options\":\"延期项目\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"dark-red\",\"mode\":\"fixed\"}}]},{\"__systemRef\":\"hideSeriesFrom\",\"matcher\":{\"id\":\"byNames\",\"options\":{\"mode\":\"exclude\",\"names\":[\"count\",\"未开始\"],\"prefix\":\"All except:\",\"readOnly\":true}},\"properties\":[{\"id\":\"custom.hideFrom\",\"value\":{\"legend\":false,\"tooltip\":false,\"viz\":true}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"关闭\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"#24292e\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"未开始\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"light-blue\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"已完成\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"green\",\"mode\":\"fixed\"}}]},{\"matcher\":{\"id\":\"byName\",\"options\":\"延期处理\"},\"properties\":[{\"id\":\"color\",\"value\":{\"fixedColor\":\"super-light-red\",\"mode\":\"fixed\"}}]}]},\"gridPos\":{\"h\":7,\"w\":7,\"x\":0,\"y\":16},\"id\":37,\"options\":{\"legend\":{\"displayMode\":\"list\",\"placement\":\"right\",\"showLegend\":true,\"values\":[\"value\"]},\"pieType\":\"pie\",\"reduceOptions\":{\"calcs\":[],\"fields\":\"\",\"values\":true},\"tooltip\":{\"maxHeight\":600,\"mode\":\"single\",\"sort\":\"none\"}},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select  s.name, count(1) as count\\n\\nfrom issues i left join issues_status s on i.status_id = s.id\\nwhere \\ni.issues_type_id in (96,97,98) and\\ni.del_flag=0 and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, tenant_id in($amp_organ_id))\\n\\ngroup by i.status_id\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"工作项状态统计\",\"type\":\"piechart\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"gridPos\":{\"h\":19,\"w\":7,\"x\":17,\"y\":16},\"id\":31,\"options\":{\"content\":\"\\u003cdiv style=\\\"display: flex; margin-top: -0.8rem\\\"\\u003e\\n  \\u003cdiv style=\\\"width: 30px\\\"\\u003e\\n    {{#if (eq status \\\"SUCCESS\\\")}}\\n    \\u003cimg\\n      style=\\\"height: 1.2em; width: 1.2em; margin-left: 3px\\\"\\n      src=\\\"data:image/svg+xml;base64,\\\"\\n    /\\u003e\\n    {{else if (eq status \\\"FAILED\\\")}}\\n    \\u003cimg\\n      style=\\\"height: 1.45em; width: 1.45em; margin-left: 1px\\\"\\n      src=\\\"data:image/svg+xml;base64,\\\"\\n    /\\u003e\\n    {{else if (eq status \\\"IN_PROGRESS\\\")}}\\n    \\u003cimg\\n      style=\\\"height: 1.4em; width: 1.4em; margin-left: 3px\\\"\\n      src=\\\"data:image/png;base64,\\\"\\n    /\\u003e\\n    {{else}}\\n    \\u003cimg\\n      style=\\\"height: 1.5em; width: 1.5em; margin-left: 1px\\\"\\n      src=\\\"data:image/png;base64,\\\"\\n    /\\u003e\\n    {{/if}}\\n  \\u003c/div\\u003e\\n  \\u003cdiv style=\\\"width: calc(100% - 105px)\\\"\\u003e{{job_name}}\\u003c/div\\u003e\\n  \\u003cdiv style=\\\"width: 70px; color: rgba(0, 0, 0, 0.4);text-align: right\\\"\\u003e{{time_str}}\\u003c/div\\u003e\\n  \\u003cdiv style=\\\"margin-left: 20px\\\"\\u003e\\n    \\u003ca href=\\\"/efficiency/pipeline/{{id}}/detail/recent_run\\\" target=\\\"_blank\\\"\\u003e\\n      \\u003cimg\\n        style=\\\"height: 1em; width: 1em\\\"\\n        src=\\\"data:image/svg+xml;base64,\\\"\\n      /\\u003e\\n    \\u003c/a\\u003e\\n  \\u003c/div\\u003e\\n\\u003c/div\\u003e\",\"defaultContent\":\"The query didn\'t return any results.\",\"editor\":{\"format\":\"auto\",\"height\":200,\"language\":\"markdown\"},\"editors\":[],\"everyRow\":true,\"helpers\":\"\",\"styles\":\"\"},\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select \\n job.job_name,\\n status,\\ncase \\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 345600 THEN date_format(info.start_time, \'%m-%d\')\\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 86400 THEN concat( TIMESTAMPDIFF( DAY, info.start_time, NOW()) ,\'d ago\')\\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 3600 THEN concat(TIMESTAMPDIFF(HOUR,info.start_time,NOW()), \'h ago\')\\n\\t\\tWHEN (unix_timestamp(now()) - unix_timestamp(info.start_time)) \\u003e 60 THEN concat(TIMESTAMPDIFF(MINUTE,info.start_time,NOW()), \'m ago\')\\n\\t\\tELSE \'刚刚\'\\nend as time_str,\\nstart_time,\\nconvert(job.id,char) as id\\n       \\n        \\nfrom devops_job_build_info info left join devops_jenkins_job job on job.id=info.job_id\\nwhere\\njob.job_name is not null and info.id in(select max(id) from devops_job_build_info group by job_id) and job.del_flag=0\\n and if(\\\"$amp_organ_name\\\" = \\\"\'all\'\\\", 1=1, job.tenant in($amp_organ_id))\\ngroup by job_id\\norder by info.update_time desc\\nlimit 20\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"最近构建情况\",\"type\":\"harmonycloud-dynamictext-panel\"},{\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"If5u9w-Vz\"},\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"thresholds\"},\"mappings\":[],\"thresholds\":{\"mode\":\"absolute\",\"steps\":[{\"color\":\"green\",\"value\":null}]}},\"overrides\":[]},\"gridPos\":{\"h\":4,\"w\":10,\"x\":7,\"y\":19},\"id\":15,\"options\":{\"colorMode\":\"value\",\"graphMode\":\"area\",\"justifyMode\":\"center\",\"orientation\":\"vertical\",\"reduceOptions\":{\"calcs\":[],\"fields\":\"/^count$/\",\"values\":true},\"showPercentChange\":false,\"textMode\":\"auto\",\"wideLayout\":true},\"pluginVersion\":\"11.1.0\",\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"harmonycloud-json-datasource\",\"uid\":\"If5u9w-Vz\"},\"fields\":[{\"jsonPath\":\"$.data[*].date\"},{\"jsonPath\":\"$.data[*].count\",\"language\":\"jsonpath\",\"name\":\"\",\"type\":\"string\"}],\"headers\":[[\"X-SCM-TOKEN\",\"SCM@2023\"]],\"method\":\"GET\",\"queryParams\":\"\",\"refId\":\"A\",\"urlPath\":\"/dashboard/authorCountRecent\"}],\"title\":\"贡献者统计\",\"type\":\"stat\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"description\":\"所选时间区间内每日新增、修复以及存量(即尚未完成)缺陷的数量曲线\",\"fieldConfig\":{\"defaults\":{\"color\":{\"mode\":\"palette-classic\"},\"custom\":{\"axisBorderShow\":false,\"axisCenteredZero\":false,\"axisColorMode\":\"text\",\"axisLabel\":\"\",\"axisPlacement\":\"auto\",\"barAlignment\":0,\"drawStyle\":\"line\",\"fillOpacity\":25,\"gradientMode\":\"none\",\"hid