INSERT INTO `dashboard_version` VALUES (568, 33, 70, 0, 71, '2025-01-14 14:57:26', 40, '1', '{\"annotations\":{\"list\":[{\"builtIn\":1,\"datasource\":{\"type\":\"grafana\",\"uid\":\"-- Grafana --\"},\"enable\":true,\"hide\":true,\"iconColor\":\"rgba(0, 211, 255, 1)\",\"name\":\"Annotations \\u0026 Alerts\",\"target\":{\"limit\":100,\"matchAny\":false,\"tags\":[],\"type\":\"dashboard\"},\"type\":\"dashboard\"}]},\"description\":\"\",\"editable\":true,\"fiscalYearStartMonth\":0,\"graphTooltip\":0,\"id\":33,\"links\":[],\"liveNow\":false,\"panels\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"gridPos\":{\"h\":4,\"w\":7,\"x\":0,\"y\":0},\"id\":23,\"options\":{\"content\":\"\\u003cdiv style=\\\"color:#226EE7;text-align:center;\\\"\\u003e\\n  \\u003cspan style=\\\"font-size:60px;font-weight: 500;\\\"\\u003e{{name}}\\u003c/span\\u003e\\u003cspan style=\\\"margin-left:4px\\\"\\u003e条\\u003c/span\\u003e\\n\\u003c/div\\u003e\",\"defaultContent\":\"The query didn\'t return any results.\",\"editor\":{\"format\":\"auto\",\"height\":200,\"language\":\"html\"},\"editors\":[],\"everyRow\":true,\"helpers\":\"\",\"styles\":\"\"},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select count(1) as name\\nfrom devops_jenkins_job job \\nwhere del_flag=0 and job_name is not null and  if(\'$amp_organ_id\'=\'null\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\nand id in (select resource_instance_id from `yanlian_app_management`.sys_resource_instance where resource_type_code = \'pipeline\' and organ_id=$amp_organ_id)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"流水线总数\",\"type\":\"harmonycloud-dynamictext-panel\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"仅统计经历过构建阶段的流水线执行历史\",\"gridPos\":{\"h\":14,\"w\":17,\"x\":7,\"y\":0},\"id\":20,\"options\":{\"followTheme\":false,\"getOption\":\"console.log(\\\"data: xxxx\\\")\\nconsole.log(data)\\nif(data.series.length ==0||data.series[0].length==0) {\\n  const option = {\\n    graphic: {\\n      elements: [\\n        {\\n          type: \'text\',\\n          left: \'center\',\\n          top: \'center\',\\n          style: {\\n            text: \'暂无数据\',\\n            fontSize: 18,\\n//             fontWeight: 400,\\n            fill: \'#5E6164\',\\n            fontFamily:\'Inter, Helvetica, Arial, sans-serif\',\\n          }\\n        }\\n      ]\\n    }\\n  };\\n  echartsInstance.setOption(option)\\n  return \\n}\\n\\n\\n\\nfunction convertDate(ms) {\\n  ms = Number(ms);\\n  let date = new Date(ms);\\n  let year = date.getFullYear();\\n  let month = String(date.getMonth() + 1).padStart(2, \'0\');\\n  let day = String(date.getDate()).padStart(2, \'0\');\\n  return `${year}/${month}/${day}`;\\n}\\n\\n\\nconst bufferA1 = data.series[0].fields[0].values;\\nconst bufferA2 = data.series[0].fields[1].values;\\nconst bufferB1 = data.series[1].fields[0].values;\\nconst bufferB2 = data.series[1].fields[1].values;\\nconst bufferB3 = data.series[1].fields[2].values;\\n\\n\\nconst dataMap = {};\\nfor(let i = 0;i\\u003cbufferA1.length;i++) {\\n  let date = bufferA1[i];\\n  let total = bufferA2[i];\\n  dataMap[date] = {\\n   total: total,\\n   successCount: 0,\\n   failedCount: 0\\n  };\\n}\\n\\nfor(let i = 0;i\\u003cbufferB1.length;i++) {\\n  let date = bufferB1[i];\\n  let metricCount = bufferB2[i];\\n  let metric = bufferB3[i];\\n  let dataObj = dataMap[date];\\n  if(!dataObj) {\\n    continue;\\n  }\\n  if(metric == \'成功\') {\\n    dataObj.successCount = metricCount;\\n  }else if(metric == \'失败\') {\\n    dataObj.failedCount = metricCount;\\n  }\\n}\\n\\nconst dataMapKeys = Object.keys(dataMap);\\nconst dateArr = [];\\nconst totalArr = [];\\nconst successArr = [];\\nconst failedArr = [];\\nfor(let i=0;i\\u003cdataMapKeys.length;i++) {\\n  let date = dataMapKeys[i];\\n  let total = dataMap[date].total;\\n  let success = dataMap[date].successCount;\\n  let failed = dataMap[date].failedCount;\\n  dateArr.push(convertDate(date));\\n  totalArr.push(total);\\n  successArr.push(success);\\n  failedArr.push(failed);\\n}\\n\\n    const max = Math.max(...totalArr) + 10\\n\\n  const option = {\\n    color: [\'#58B076\', \'#E05933\', \'#226EE7\'],\\n    grid: {\\n      right: 40,\\n    },\\n    tooltip: {\\n      trigger: \'axis\',\\n    },\\n    legend: {\\n      data: [\'成功\', \'失败\', \'构建次数\'],\\n      icon: \'rect\',\\n      itemHeight: 8,\\n      itemWidth: 12,\\n      right: 0,\\n    },\\n    xAxis: [\\n      {\\n        type: \'category\',\\n        data: dateArr,\\n        axisPointer: {\\n          type: \'shadow\',\\n        },\\n        axisTick: {\\n          show: false,\\n        },\\n        axisLine: {\\n          show: false,\\n        },\\n      },\\n    ],\\n    yAxis: [\\n      {\\n        type: \'value\',\\n        minInterval: 10,\\n        name: \'成功（次）\',\\n        max: max,\\n      },\\n      {\\n        type: \'value\',\\n        minInterval: 10,\\n        name: \'构建次数（次）\',\\n        max: max,\\n      },\\n    ],\\n    series: [\\n      {\\n        name: \'成功\',\\n        type: \'bar\',\\n        data: successArr,\\n        barMaxWidth: 12,\\n      },\\n      {\\n        name: \'失败\',\\n        type: \'bar\',\\n        data: failedArr,\\n        barMaxWidth: 12,\\n        // barGap: \'0%\',\\n      },\\n      {\\n        name: \'构建次数\',\\n        type: \'line\',\\n        data: totalArr,\\n        yAxisIndex: 1,\\n        z: -1,\\n      },\\n    ],\\n  }\\n  echartsInstance.setOption(option)\\n\\n\\n\\n\\n\\n\"},\"targets\":[{\"cacheDurationSeconds\":300,\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"fields\":[{\"jsonPath\":\"\"}],\"format\":\"table\",\"method\":\"GET\",\"queryParams\":\"\",\"rawQuery\":true,\"rawSql\":\"SELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\'\\nFROM ( select count(1) as count, i.update_time \\nfrom devops_job_build_info i left join devops_jenkins_job j on i.job_id=j.id\\n where i.del_flag=0 \\n and if(\'$amp_organ_id\'=\'null\', 1=1, j.tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, j.label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\'))\\ngroup by date_format(i.update_time,\'%Y%m%d\')\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\n  group by 1\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"urlPath\":\"\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"hide\":false,\"rawQuery\":true,\"rawSql\":\"\\nSELECT\\n  $__timeGroupAlias(middle.update_time,1d),\\n  middle.count as \'构建次数\',\\n  middle.status_name as \'metric\'\\nFROM ( \\nselect count(1) as count, i.update_time ,\\n(case \\n  when i.status=\'SUCCESS\' then \'成功\'\\n  when i.status=\'FAILURE\' then \'失败\'\\n  when i.status=\'FAILED\' then \'失败\'\\n  else i.status\\nend) as status_name\\nfrom devops_job_build_info i\\nwhere i.del_flag=0 and status in(\'SUCCESS\',\'FAILURE\',\'FAILED\') and job_id in(select id from devops_jenkins_job where del_flag=0 and tenant = if(\'$amp_organ_id\'=\'null\', tenant,\'$amp_organ_id\') and  if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')))\\ngroup by date_format(i.update_time,\'%Y%m%d\'), i.status\\norder by i.update_time asc\\n) as middle\\nWHERE\\n  $__timeFilter(middle.update_time)\\nORDER BY $__timeGroup(middle.update_time,1d)\",\"refId\":\"B\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"流水线构建情况\",\"type\":\"bilibala-echarts-panel\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"最近一次构建成功的流水线 / 流水线总数\",\"gridPos\":{\"h\":5,\"w\":7,\"x\":0,\"y\":4},\"id\":22,\"options\":{\"followTheme\":false,\"getOption\":\"  const _value = data.series[0].fields[1].values[0].split(\'%\')[0]\\n  const option = {\\n  series: [\\n    {\\n      type: \'gauge\',\\n      radius: \'100%\',\\n      splitNumber: 5,\\n      startAngle: 200,\\n      endAngle: -20,\\n      pointer: {\\n        show: false,\\n      },\\n      progress: {\\n        show: true,\\n        width: 16,\\n      },\\n      axisLine: {\\n        lineStyle: {\\n          width: 16,\\n        },\\n      },\\n      axisTick: {\\n        show: false,\\n      },\\n      splitLine: {\\n        show: false,\\n      },\\n      axisLabel: {\\n        show: false,\\n      },\\n      itemStyle: {\\n        color: \'#28B370\',\\n      },\\n      detail: {\\n        valueAnimation: true,\\n        fontSize: 20,\\n        color: \'#28B370\',\\n        offsetCenter: [0, 0],\\n        formatter: \'{value}{a|%}\',\\n        textStyle: {\\n          rich: {\\n            a: {\\n              fontSize: 14,\\n              padding: [2, 0, 0, 6],\\n            },\\n          },\\n        },\\n      },\\n      data: [\\n        {\\n          value: _value,\\n        },\\n      ],\\n    },\\n  ],\\n}\\nechartsInstance.setOption(option)\"},\"pluginVersion\":\"9.4.0-pre\",\"targets\":[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"editorMode\":\"code\",\"format\":\"table\",\"rawQuery\":true,\"rawSql\":\"select name, if(value is null, 0, value) value from (\\nselect \'流水线构建成功率\' as name, concat(ROUND((select count(1) from devops_job_build_info where status = \'SUCCESS\' and $__timeFilter(start_time) and id in(select max(id) from devops_job_build_info where  job_id in (select id from devops_jenkins_job where   if(\'$amp_organ_id\'=\'null\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')) and del_flag=0) group by job_id)) \\n/\\n (select count(1) from devops_job_build_info where  $__timeFilter(start_time) and id in(select max(id) from devops_job_build_info where  job_id in (select id from devops_jenkins_job where   if(\'$amp_organ_id\'=\'null\', 1=1, tenant =  \'$amp_organ_id\') \\nand if(\\\"$tagNames\\\" = \\\"\'all\'\\\", 1=1, label regexp concat(\'(^|,)(\',replace(replace(\\\"$tagIds\\\",\\\"\'\\\",\'\'),\',\',\'|\'),\')(,|$)\')) and del_flag=0) group by job_id)) * 100,2),\'%\') as value) a\\n \\n \\n\\n \\n \\n \\n \\n \",\"refId\":\"A\",\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50}}],\"title\":\"流水线成功率\",\"type\":\"bilibala-echarts-panel\"},{\"datasource\":{\"type\":\"mysql\",\"uid\":\"hHOeeI-Vk\"},\"description\":\"构建成功次数 / 流水线构建总次数\",\"gridPos\":{\"h\":5,\"w\":7,\"x\":0,\"y\":9},\"id\":24,\"options\":{\"followTheme\":false,\"getOption\":\"console.log(data)\\nif(data.series.length ==0||data.series[0].length==0) {\\n  const option = {\\n    graphic: {\\n      elements: [\\n        {\\n          type: \'text\',\\n          left: \'center\',\\n          top: \'center\',\\n          style: {\\n            text: \'No data\',\\n            fontSize: 18,\\n//             fontWeight: 400,\\n            fill: \'#5E6164\',\\n            fontFamily:\'Inter, Helvetica, Arial, sans-serif\',\\n          }\\n        }\\n      ]\\n    }\\n  };\\n  echartsInstance.setOption(option)\\n  return \\n}\\nconst _value = data.series[0].fields[1]