INSERT INTO `migration_log` VALUES (6, 'drop index UQE_user_email - v1', 'DROP INDEX `UQE_user_email` ON `user`', 1, '', '2023-03-10 11:27:37');
INSERT INTO `migration_log` VALUES (7, 'Rename table user to user_v1 - v1', 'ALTER TABLE `user` RENAME TO `user_v1`', 1, '', '2023-03-10 11:27:37');
INSERT INTO `migration_log` VALUES (8, 'create user table v2', 'CREATE TABLE IF NOT EXISTS `user` (\n`id` BIGINT(20) PRIMARY KEY AUTO_INCREMENT NOT NULL\n, `version` INT NOT NULL\n, `login` VARCHAR(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL\n, `email` VARCHAR(190) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL\n, `name` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL\n, `password` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL\n, `salt` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL\n, `rands` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL\n, `company` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL\n, `org_id` BIGINT(20) NOT NULL\n, `is_admin` TINYINT(1) NOT NULL\n, `email_verified` TINYINT(1) NULL\n, `theme` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL\n, `created` DATETIME NOT NULL\n, `updated` DATETIME NOT NULL\n) ENGINE=InnoDB DEFAULT CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;', 1, '', '2023-03-10 11:27:37');
INSERT INTO `migration_log` VALUES (9, 'create index UQE_user_login - v2', 'CREATE UNIQUE INDEX `UQE_user_login` ON `user` (`login`);', 1, '', '2023-03-10 11:27:37');
INSERT INTO `migration_log` VALUES (10, 'create index UQE_user_email - v2', 'CREATE UNIQUE INDEX `UQE_user_email` ON `user` (`email`);', 1, '', '2023-03-10 11:27:38');
INSERT INTO `migration_log` VALUES (11, 'copy data_source v1 to v2', 'INSERT INTO `user` (`version`\n, `rands`\n, `company`\n, `created`\n, `id`\n, `login`\n, `email`\n, `name`\n, `password`\n, `salt`\n, `org_id`\n, `is_admin`\n, `updated`) SELECT `version`\n, `rands`\n, `company`\n, `created`\n, `id`\n, `login`\n, `email`\n, `name`\n, `password`\n, `salt`\n, `account_id`\n, `is_admin`\n, `updated` FROM `user_v1`', 1, '', '2023-03-10 11:27:38');
