-- Table structure for ngalert_configuration
-- ----------------------------
DROP TABLE IF EXISTS `ngalert_configuration`;
CREATE TABLE `ngalert_configuration`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT,
  `org_id` bigint(0) NOT NULL,
  `alertmanagers` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `created_at` int(0) NOT NULL,
  `updated_at` int(0) NOT NULL,
  `send_alerts_to` smallint(0) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `UQE_ngalert_configuration_org_id`(`org_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

