INSERT INTO `query_history` VALUES (1, 'be8qhnq56mrr4c', 1, 'mXN6ODiSk', 40, 1735784813, '', '[{\"datasource\":{\"type\":\"mysql\",\"uid\":\"mXN6ODiSk\"},\"editorMode\":\"code\",\"format\":\"time_series\",\"group\":[],\"hide\":false,\"metricColumn\":\"none\",\"rawQuery\":true,\"rawSql\":\"select \\n$__timeGroupAlias(i1.create_time,1d),\\ncount(1) as new_count,\\n(select count(1) from issues i2 where i2.del_flag=0 and i2.issues_type_id=98  and date_format(cast(i2.close_time as datetime), \'%Y%m%d\') = date_format(cast(i1.create_time as datetime), \'%Y%m%d\') and i2.status_id in (7855,4) and if(\\\"\'all\'\\\" = \\\"\'all\'\\\", 1=1, i2.tenant_id in(\'3267246491214659584\'))) as finish_count,\\n\\n((select count(1) from issues i2 where if(\\\"\'all\'\\\" = \\\"\'all\'\\\", 1=1, i2.tenant_id in(\'3267246491214659584\')) and i2.del_flag=0 and i2.issues_type_id=98   and date_format(cast(i2.create_time as datetime), \'%Y%m%d\') \\u003c= date_format(cast(i1.create_time as datetime), \'%Y%m%d\')) - (select count(1) from issues i3 where i3.del_flag=0 and if(\\\"\'all\'\\\" = \\\"\'all\'\\\", 1=1, i3.tenant_id in(\'3267246491214659584\')) and i3.issues_type_id=98   and date_format(cast(i3.close_time as datetime), \'%Y%m%d\') \\u003c= date_format(cast(i1.create_time as datetime), \'%Y%m%d\') and i3.status_id in (7855,4))) as remain_count\\n\\n\\n\\n\\nfrom issues i1\\nwhere i1.del_flag = 0 and i1.issues_type_id=98 and if(\\\"\'all\'\\\" = \\\"\'all\'\\\", 1=1, i1.tenant_id in(\'3267246491214659584\'))\\nand $__timeFilter(i1.create_time)\\ngroup by date_format(cast(i1.create_time as datetime), \'%Y%m%d\')\\n\\nORDER BY i1.create_time ASC\",\"refId\":\"A\",\"select\":[[{\"params\":[\"id\"],\"type\":\"column\"}]],\"sql\":{\"columns\":[{\"parameters\":[],\"type\":\"function\"}],\"groupBy\":[{\"property\":{\"type\":\"string\"},\"type\":\"groupBy\"}],\"limit\":50},\"table\":\"artifacts_repositories\",\"timeColumn\":\"create_time\",\"timeColumnType\":\"timestamp\",\"where\":[{\"name\":\"$__timeFilter\",\"params\":[],\"type\":\"macro\"}]}]');
